// ─────────────────────────────────────────────────────────────
// Claude API 호출
// - 429 Rate Limit: exponential backoff 자동 재시도 (최대 5회)
// - fetch timeout: 90초 (무한 대기 방지)
// - max_tokens 기본값: 4096
// ─────────────────────────────────────────────────────────────
// 커스텀 드롭다운 — OS 기본 select 대신 앱 내부에서 펼쳐지는 컴포넌트
// options: [{ value, label }] / value, onChange, className, style
function CustomSelect({ value, onChange, options, style = {}, fontSize = 12, placeholder = '선택' }) {
 const [open, setOpen] = React.useState(false);
 const [highlightIdx, setHighlightIdx] = React.useState(-1);
 const wrapperRef = React.useRef(null);

 const selected = options.find(o => o.value === value);

 useEffect(() => {
 if (!open) return;
 const handler = (e) => {
 if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
 setOpen(false);
 }
 };
 const key = (e) => {
 if (e.key === 'Escape') setOpen(false);
 else if (e.key === 'ArrowDown') {
 e.preventDefault();
 setHighlightIdx(i => Math.min(options.length - 1, i + 1));
 } else if (e.key === 'ArrowUp') {
 e.preventDefault();
 setHighlightIdx(i => Math.max(0, i - 1));
 } else if (e.key === 'Enter' && highlightIdx >= 0) {
 e.preventDefault();
 onChange(options[highlightIdx].value);
 setOpen(false);
 }
 };
 setTimeout(() => document.addEventListener('mousedown', handler), 0);
 document.addEventListener('keydown', key);
 return () => {
 document.removeEventListener('mousedown', handler);
 document.removeEventListener('keydown', key);
 };
 }, [open, highlightIdx, options, onChange]);

 return (
 <div ref={wrapperRef} style={{ position: 'relative', ...style }}>
 <button
 type="button"
 onClick={() => {
 setOpen(o => !o);
 const idx = options.findIndex(o => o.value === value);
 setHighlightIdx(idx >= 0 ? idx : 0);
 }}
 style={{
 width: '100%',
 padding: '8px 32px 8px 12px',
 borderRadius: 'var(--radius-sm)',
 border: `1px solid ${open ? 'var(--green-500)' : 'var(--border)'}`,
 background: 'var(--bg-primary)',
 color: 'var(--text-primary)',
 fontSize,
 fontFamily: 'inherit',
 textAlign: 'left',
 cursor: 'pointer',
 position: 'relative',
 outline: 'none',
 transition: 'border-color 0.15s',
 }}
 >
 {selected ? selected.label : <span style={{ color: 'var(--text-tertiary)' }}>{placeholder}</span>}
 <span style={{
 position: 'absolute',
 right: 10, top: '50%',
 transform: `translateY(-50%) ${open ? 'rotate(180deg)' : 'rotate(0)'}`,
 transition: 'transform 0.15s',
 color: 'var(--text-tertiary)',
 fontSize: 10,
 pointerEvents: 'none',
 }}>▼</span>
 </button>
 {open && (
 <div style={{
 position: 'absolute',
 top: 'calc(100% + 4px)', left: 0, right: 0,
 background: 'var(--bg-primary)',
 border: '1px solid var(--border)',
 borderRadius: 'var(--radius-sm)',
 boxShadow: '0 8px 24px rgba(0,0,0,0.18)',
 zIndex: 100,
 maxHeight: 240,
 overflowY: 'auto', overscrollBehavior: 'contain',
 padding: 4,
 }}>
 {options.map((opt, idx) => {
 const isSelected = opt.value === value;
 const isHighlight = idx === highlightIdx;
 return (
 <button
 key={opt.value}
 type="button"
 onClick={() => { onChange(opt.value); setOpen(false); }}
 onMouseEnter={() => setHighlightIdx(idx)}
 style={{
 display: 'block', width: '100%',
 padding: '8px 12px',
 textAlign: 'left',
 border: 'none',
 background: isHighlight ? 'var(--bg-tertiary)' : (isSelected ? 'var(--bg-secondary)' : 'transparent'),
 color: isSelected ? 'var(--green-700)' : 'var(--text-primary)',
 fontSize, fontFamily: 'inherit',
 fontWeight: isSelected ? 700 : 400,
 borderRadius: 'var(--radius-sm)',
 cursor: 'pointer',
 transition: 'background 0.1s',
 }}
 >
 {opt.label}
 </button>
 );
 })}
 </div>
 )}
 </div>
 );
}

// ─────────────────────────────────────────────────────────────
// 타이틀 이미지 알파 추출 — 검은 배경 제거 후 깨끗한 PNG dataURL 반환
// 미리보기와 합성에서 동일한 결과를 보장하기 위해 모듈 레벨 함수로 분리
// ─────────────────────────────────────────────────────────────
async function extractCleanTitleDataUrl(imageUrl) {
 return new Promise((resolve, reject) => {
 fetch(imageUrl, { mode: 'cors' })
 .then(r => r.blob())
 .then(blob => {
 const img = new globalThis.Image();
 const objUrl = URL.createObjectURL(blob);
 img.onload = () => {
 try {
 const c = document.createElement('canvas');
 c.width = img.naturalWidth;
 c.height = img.naturalHeight;
 const cx = c.getContext('2d');
 cx.drawImage(img, 0, 0);
 const data = cx.getImageData(0, 0, c.width, c.height);
 const d = data.data;
 // 임계값 — 압축 인공물 제거
 // 어두운 픽셀(밝기 40 이하)은 완전 투명
 // 밝은 픽셀(밝기 180 이상)은 완전 불투명
 // 중간은 선형 매핑 (가장자리 부드러움)
 const TH_LOW = 40;
 const TH_HIGH = 180;
 for (let i = 0; i < d.length; i += 4) {
 const brightness = (d[i] + d[i + 1] + d[i + 2]) / 3;
 let alpha;
 if (brightness <= TH_LOW) alpha = 0;
 else if (brightness >= TH_HIGH) alpha = 255;
 else alpha = Math.round(((brightness - TH_LOW) / (TH_HIGH - TH_LOW)) * 255);
 d[i + 3] = alpha;
 // 색상은 원본 유지 (글자 자체는 흰색이거나 그래픽 색상)
 // 단, 너무 어두운 픽셀은 화이트로 강제 (가장자리 보호)
 if (alpha < 255 && alpha > 0) {
 d[i] = 255; d[i + 1] = 255; d[i + 2] = 255;
 }
 }
 cx.putImageData(data, 0, 0);
 URL.revokeObjectURL(objUrl);
 resolve(c.toDataURL('image/png'));
 } catch (e) { URL.revokeObjectURL(objUrl); reject(e); }
 };
 img.onerror = (e) => { URL.revokeObjectURL(objUrl); reject(e); };
 img.crossOrigin = 'anonymous';
 img.src = objUrl;
 })
 .catch(reject);
 });
}

// ─────────────────────────────────────────────────────────────
// v870: 로고의 단색 배경을 투명하게 만든다 (책자 디자인의 로고 등록용).
//
// v865 는 모서리에서 flood fill 로 번져 들어갔다. 그래서 '바깥과 이어진' 배경만
// 지워지고, 로고 안쪽에 갇힌 배경은 남았다 — 원형 로고의 원 안쪽, 글자 'o' 의
// 구멍 같은 곳이다. 실제로 그 안쪽도 배경이라 지워져야 맞다.
// 그래서 전역 색 매칭으로 바꿨다: 배경색과 같은 색이면 위치를 따지지 않고 지운다.
//
// 배경색은 테두리 픽셀의 최빈색으로 잡는다 (모서리 4점 평균보다 견고하다 —
// 모서리에 로고가 걸쳐 있거나 압축 잡티가 있어도 흔들리지 않는다).
// 단색 배경만 지원한다. 테두리 색이 흩어져 있으면 사진 배경으로 보고 손대지 않는다.
//
// 반환: { dataUrl, width, height, removed, note }
// ─────────────────────────────────────────────────────────────
const LOGO_BG_TOL_HARD = 40;   // 이 안쪽은 완전 투명 (v865 의 26 은 압축 잡티를 놓쳤다)
const LOGO_BG_TOL_SOFT = 96;   // 이 사이는 부분 투명 (안티에일리어싱 경계)
const LOGO_EDGE_SPREAD_MAX = 46; // 테두리 색이 이보다 흩어지면 단색 배경이 아니다

async function makeLogoTransparent(imageUrl) {
 const img = await new Promise((res, rej) => {
 const im = new globalThis.Image();
 im.onload = () => res(im);
 im.onerror = rej;
 im.crossOrigin = 'anonymous';
 im.src = imageUrl;
 });
 const W = img.naturalWidth, H = img.naturalHeight;
 if (!W || !H) throw new Error('로고 이미지를 읽지 못했습니다.');
 const c = document.createElement('canvas');
 c.width = W; c.height = H;
 const cx = c.getContext('2d', { willReadFrequently: true });
 cx.drawImage(img, 0, 0);
 const idata = cx.getImageData(0, 0, W, H);
 const d = idata.data;

 const trimTo = (canvas) => {
 const g = canvas.getContext('2d', { willReadFrequently: true });
 const src = g.getImageData(0, 0, canvas.width, canvas.height).data;
 let minX = canvas.width, minY = canvas.height, maxX = -1, maxY = -1;
 for (let y = 0; y < canvas.height; y++) for (let x = 0; x < canvas.width; x++) {
 if (src[(y * canvas.width + x) * 4 + 3] < 12) continue;
 if (x < minX) minX = x;
 if (x > maxX) maxX = x;
 if (y < minY) minY = y;
 if (y > maxY) maxY = y;
 }
 if (maxX < 0) return null;
 const cw = maxX - minX + 1, ch = maxY - minY + 1;
 const out = document.createElement('canvas');
 out.width = cw; out.height = ch;
 out.getContext('2d').drawImage(canvas, minX, minY, cw, ch, 0, 0, cw, ch);
 return { canvas: out, width: cw, height: ch };
 };

 // 이미 투명 배경이면(내장 로고 등) 자르기만 한다
 let transparentPx = 0;
 for (let i = 3; i < d.length; i += 4) if (d[i] < 250) transparentPx++;
 if (transparentPx > (W * H) * 0.02) {
 const t = trimTo(c);
 return t
 ? { dataUrl: t.canvas.toDataURL('image/png'), width: t.width, height: t.height, removed: false, note: 'already-alpha' }
 : { dataUrl: c.toDataURL('image/png'), width: W, height: H, removed: false, note: 'already-alpha' };
 }

 // ── 배경색 추정: 테두리 한 겹의 최빈색 ──
 const bucket = new Map();
 const addEdge = (x, y) => {
 const i = (y * W + x) * 4;
 // 16단위로 양자화해 잡티를 뭉갠다
 const key = `${d[i] >> 4},${d[i + 1] >> 4},${d[i + 2] >> 4}`;
 const cur = bucket.get(key) || { n: 0, r: 0, g: 0, b: 0 };
 cur.n++; cur.r += d[i]; cur.g += d[i + 1]; cur.b += d[i + 2];
 bucket.set(key, cur);
 };
 for (let x = 0; x < W; x++) { addEdge(x, 0); addEdge(x, H - 1); }
 for (let y = 0; y < H; y++) { addEdge(0, y); addEdge(W - 1, y); }
 let top = null;
 let edgeTotal = 0;
 for (const v of bucket.values()) { edgeTotal += v.n; if (!top || v.n > top.n) top = v; }
 if (!top) return { dataUrl: c.toDataURL('image/png'), width: W, height: H, removed: false, note: 'no-edge' };
 const bg = [top.r / top.n, top.g / top.n, top.b / top.n];

 // 테두리의 최빈색 점유율이 낮으면 단색 배경이 아니다 (사진·그라디언트)
 const share = top.n / Math.max(1, edgeTotal);
 const dist = (i) => Math.max(
 Math.abs(d[i] - bg[0]), Math.abs(d[i + 1] - bg[1]), Math.abs(d[i + 2] - bg[2]));
 // 테두리 픽셀이 배경색에서 얼마나 벗어나는지도 함께 본다
 let edgeOff = 0, edgeN = 0;
 const checkEdge = (x, y) => { edgeOff += dist((y * W + x) * 4); edgeN++; };
 for (let x = 0; x < W; x += 2) { checkEdge(x, 0); checkEdge(x, H - 1); }
 for (let y = 0; y < H; y += 2) { checkEdge(0, y); checkEdge(W - 1, y); }
 const edgeAvgOff = edgeOff / Math.max(1, edgeN);
 if (share < 0.5 || edgeAvgOff > LOGO_EDGE_SPREAD_MAX) {
 return { dataUrl: c.toDataURL('image/png'), width: W, height: H, removed: false, note: 'not-solid' };
 }

 // ── 전역 매칭: 위치를 따지지 않고 배경색과 같은 픽셀을 지운다 ──
 //   이래야 원형 로고 안쪽이나 글자 구멍에 갇힌 배경도 사라진다.
 for (let p = 0; p < W * H; p++) {
 const i = p * 4;
 const dd = dist(i);
 if (dd <= LOGO_BG_TOL_HARD) d[i + 3] = 0;
 else if (dd < LOGO_BG_TOL_SOFT) {
 d[i + 3] = Math.round(((dd - LOGO_BG_TOL_HARD) / (LOGO_BG_TOL_SOFT - LOGO_BG_TOL_HARD)) * d[i + 3]);
 }
 }
 cx.putImageData(idata, 0, 0);

 // 안전장치: 거의 다 지워졌으면 로고까지 날린 것이다 (배경과 같은 색의 로고)
 let leftPx = 0;
 for (let i = 3; i < d.length; i += 4) if (d[i] > 24) leftPx++;
 if (leftPx < W * H * 0.004) {
 const plain = document.createElement('canvas');
 plain.width = W; plain.height = H;
 plain.getContext('2d').drawImage(img, 0, 0);
 return { dataUrl: plain.toDataURL('image/png'), width: W, height: H, removed: false, note: 'would-erase-all' };
 }

 const t = trimTo(c);
 return t
 ? { dataUrl: t.canvas.toDataURL('image/png'), width: t.width, height: t.height, removed: true, note: 'removed' }
 : { dataUrl: c.toDataURL('image/png'), width: W, height: H, removed: true, note: 'removed' };
}

// ─────────────────────────────────────────────────────────────
// v865: 책자 표지 합성 — 1772×1240 캔버스에 직접 그린다.
//
// AI 는 배경만 만든다. 크레딧·로고·타이틀·'귀하' 는 전부 여기서 좌표대로 올린다.
// 이미지 모델에 한글을 그리게 하면 글자가 깨지기 때문이다.
//
// 라벨 자간: 참조 시안처럼 '기    획' / '제 작 총 괄' 이 같은 폭에 맞춰지도록,
//   라벨이 칼럼보다 좁으면 글자를 칼럼 폭에 균등 분산한다 (공백은 빼고 계산).
//   칼럼보다 넓은 라벨('책임 프로듀서')은 그대로 왼쪽 정렬한다.
// ─────────────────────────────────────────────────────────────
const BOOKLET_FONT = "'Pretendard Variable','Pretendard','Apple SD Gothic Neo','Malgun Gothic','Noto Sans KR',sans-serif";
const BOOKLET_MARGIN = 85;          // 우측/좌측 기본 여백
const BOOKLET_LABEL_COL = 103;      // 라벨 칼럼 폭 (시안 실측: 940→1043)
const BOOKLET_LABEL_GAP = 20;       // 라벨 ↔ 이름 사이 (시안 실측)
const BOOKLET_FONT_SIZE = 15.5;     // 시안 실측 — 20자 이름이 262px 에 들어간다
const BOOKLET_LINE_H = 32;
const BOOKLET_GAP_LINE = 20;        // gapAfter 로 띄우는 높이
// v867: 라벨은 글자수와 무관하게 전부 같은 칼럼 폭에 균등 분산한다.
//   '기 획'(2자)과 '책 임 프 로 듀 서'(6자)의 왼쪽·오른쪽 끝이 맞아야
//   이름 열이 한 줄로 정렬된 것처럼 읽힌다. 칼럼 폭은 가장 긴 라벨에 맞춰
//   자동으로 넓혀서, 긴 라벨이 이름 칸을 밀어내지 않게 한다.

// v872: 디코드된 이미지를 주소로 캐시한다.
//   배치 조정 미리보기는 프레임마다 배경(4.5MP)·로고·타이틀을 다시 디코드하고 있었다.
//   같은 주소면 같은 픽셀이라 재사용해도 안전하다. 24장까지만 들고 FIFO 로 버린다.
const IMG_CACHE_MAX = 12;   // 2.2MP 배경이 쌓이면 커진다 — 작업 한 벌이면 충분하다
const _imgElCache = new Map();
const loadImageElCached = (url) => {
 const hit = _imgElCache.get(url);
 if (hit) return hit;
 const pr = loadImageEl(url).catch(e => { _imgElCache.delete(url); throw e; });
 _imgElCache.set(url, pr);
 while (_imgElCache.size > IMG_CACHE_MAX) _imgElCache.delete(_imgElCache.keys().next().value);
 return pr;
};

const loadImageEl = (url) => new Promise((res, rej) => {
 if (!url) { rej(new Error('이미지 주소가 없습니다.')); return; }
 const done = (im) => { im.crossOrigin = 'anonymous'; };
 if (/^(data|blob):/.test(url)) {
 const im = new globalThis.Image();
 im.onload = () => res(im);
 im.onerror = rej;
 im.src = url;
 return;
 }
 fetch(url, { mode: 'cors' })
 .then(r => r.blob())
 .then(blob => {
 const im = new globalThis.Image();
 const objUrl = URL.createObjectURL(blob);
 im.onload = () => { URL.revokeObjectURL(objUrl); res(im); };
 im.onerror = (e) => { URL.revokeObjectURL(objUrl); rej(e); };
 done(im);
 im.src = objUrl;
 })
 .catch(rej);
});

// v868: 알파를 그림자 색으로 채운 레이어를 만든다 (포스터 작업과 같은 방식).
//   투명 배경 PNG(타이틀·로고)를 그대로 써서 모양만 뽑는다.
function makeShadowLayer(img, color) {
 const w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
 const c = document.createElement('canvas');
 c.width = w; c.height = h;
 const cx = c.getContext('2d');
 cx.drawImage(img, 0, 0);
 cx.globalCompositeOperation = 'source-in';
 cx.fillStyle = color || '#000000';
 cx.fillRect(0, 0, w, h);
 return c;
}

// 그림자를 먼저 깔고 본체를 그린다. sh = { enabled, color, opacity, blur, offsetX, offsetY }
function drawWithShadow(cx, img, x, y, w, h, sh) {
 if (sh && sh.enabled) {
 const blur = Math.max(0, Number(sh.blur) || 0);
 const pad = blur * 2;
 const layer = makeShadowLayer(img, sh.color || '#000000');
 const tmp = document.createElement('canvas');
 tmp.width = Math.round(w + pad * 2);
 tmp.height = Math.round(h + pad * 2);
 const tctx = tmp.getContext('2d');
 if (blur > 0) tctx.filter = `blur(${blur}px)`;
 tctx.drawImage(layer, pad, pad, w, h);
 tctx.filter = 'none';
 cx.save();
 cx.globalAlpha = Math.max(0, Math.min(1, (sh.opacity ?? 60) / 100));
 cx.drawImage(tmp, x + (Number(sh.offsetX) || 0) - pad, y + (Number(sh.offsetY) || 0) - pad);
 cx.restore();
 }
 cx.drawImage(img, x, y, w, h);
}

// 배경을 캔버스에 꽉 채워 그린다 (비율 유지 · 중앙 크롭)
function drawCover(cx, img, W, H) {
 const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
 const scale = Math.max(W / iw, H / ih);
 const dw = iw * scale, dh = ih * scale;
 cx.drawImage(img, (W - dw) / 2, (H - dh) / 2, dw, dh);
}

// 글자를 주어진 폭에 균등 분산해 그린다. 반환: 실제로 쓴 폭
function drawSpread(cx, text, x, y, colW) {
 const raw = String(text || '');
 const chars = [...raw.replace(/\s+/g, '')];
 if (!chars.length) return 0;
 const natural = cx.measureText(chars.join('')).width;
 if (chars.length === 1) { cx.fillText(chars[0], x, y); return natural; }
 // 칼럼이 좁으면(폰트 대체 등) 억지로 겹치지 않게 자연 폭으로 둔다
 if (natural >= colW) { cx.fillText(chars.join(''), x, y); return natural; }
 const extra = (colW - natural) / (chars.length - 1);
 let cur = x;
 for (const ch of chars) {
 cx.fillText(ch, cur, y);
 cur += cx.measureText(ch).width + extra;
 }
 return colW;
}

// 우측 상단 '____귀하' — 참조 시안의 네모 박스 대신 얇은 규칙선으로 정리했다
function drawRecipient(cx, W, opts = {}) {
 const right = Math.min(W - BOOKLET_ZONE_PAD, BOOKLET_SAFE_FRONT_X1); // 안전 영역 오른쪽
 const top = bkClamp(opts.y ?? 104, 24, BOOKLET_SAFE_Y0 + 18, BOOKLET_SAFE_Y1);
 const ruleW = 170;
 const size = 17;
 cx.save();
 cx.font = `500 ${size}px ${BOOKLET_FONT}`;
 cx.textAlign = 'left';
 cx.textBaseline = 'alphabetic';
 const suffix = '귀하';
 const sufW = cx.measureText(suffix).width;
 const ruleRight = right - sufW - 11;
 // 규칙선 — 손으로 이름을 적는 자리
 cx.strokeStyle = 'rgba(255,255,255,0.46)';
 cx.lineWidth = 1.4;
 cx.beginPath();
 cx.moveTo(ruleRight - ruleW, top + 1);
 cx.lineTo(ruleRight, top + 1);
 cx.stroke();
 cx.fillStyle = 'rgba(255,255,255,0.93)';
 cx.fillText(suffix, ruleRight + 11, top - 2);
 cx.restore();
}

// 크레딧 블록이 차지할 높이 — 그리기 전에 안전 영역 안으로 밀어 넣으려면 먼저 알아야 한다
function measureCreditsHeight(credits, scale) {
 const fs = BOOKLET_FONT_SIZE * scale;
 const lh = BOOKLET_LINE_H * scale;
 let h = 0, any = false;
 for (const row of credits) {
 if (String(row.label || '').trim() || String(row.names || '').trim()) { h += lh; any = true; }
 if (row.gapAfter) h += BOOKLET_GAP_LINE * scale;
 }
 return any ? h + fs : 0;
}

// 크레딧 블록. 반환: 그린 높이. maxRight 를 넘는 이름 줄은 그 줄만 폰트를 줄여 맞춘다
function drawCredits(cx, credits, x, y, scale, maxRight) {
 const fs = BOOKLET_FONT_SIZE * scale;
 const lh = BOOKLET_LINE_H * scale;
 const gap = BOOKLET_LABEL_GAP * scale;
 cx.save();
 // 칼럼 폭 = max(기본값, 가장 긴 라벨의 자연 폭). 모든 라벨이 이 폭에 맞춰 분산되고
 // 이름 열도 한 지점에서 시작한다.
 cx.font = `500 ${fs}px ${BOOKLET_FONT}`;
 let colW = BOOKLET_LABEL_COL * scale;
 for (const row of credits) {
 const w = cx.measureText(String(row.label || '').replace(/\s+/g, '')).width;
 if (w > colW) colW = w;
 }
 cx.textAlign = 'left';
 cx.textBaseline = 'alphabetic';
 let cy = y + fs;
 for (const row of credits) {
 const label = String(row.label || '').trim();
 const names = String(row.names || '').trim();
 if (label || names) {
 cx.font = `500 ${fs}px ${BOOKLET_FONT}`;
 cx.fillStyle = 'rgba(255,255,255,0.90)';
 drawSpread(cx, label, x, cy, colW);
 if (names) {
 const nx = x + colW + gap;
 cx.font = `400 ${fs}px ${BOOKLET_FONT}`;
 // 이름이 길어 안전 영역을 넘으면 그 줄만 줄인다 (잘려 나가는 것보다 낫다)
 if (maxRight) {
 const avail = maxRight - nx;
 const w = cx.measureText(names).width;
 if (w > avail && avail > 0) cx.font = `400 ${Math.max(fs * 0.6, fs * (avail / w))}px ${BOOKLET_FONT}`;
 }
 cx.fillStyle = 'rgba(255,255,255,0.97)';
 cx.fillText(names, nx, cy);
 }
 cy += lh;
 }
 if (row.gapAfter) cy += BOOKLET_GAP_LINE * scale;
 }
 cx.restore();
 return cy - y;
}

// 로고 목록을 세로로 쌓아 그린다 (가로 중앙 기준)
function drawLogoStack(cx, logos, centerX, centerY, itemW0, gap0, sh, bounds) {
 const items = logos.filter(Boolean);
 if (!items.length) return;
 const bx0 = bounds?.x0, bx1 = bounds?.x1, by0 = bounds?.y0, by1 = bounds?.y1;
 let itemW = bounds ? Math.min(itemW0, bx1 - bx0) : itemW0;
 let gap = gap0;
 // 세로가 긴 로고(2줄형 등)는 높이를 제한한다 — 안 하면 한 장이 스택을 다 먹는다
 const heightsFor = (w, g) => {
 const hs = items.map(l => Math.min(w / (l.ratio || 1), w * 0.62));
 return { hs, total: hs.reduce((a, b) => a + b, 0) + g * (items.length - 1) };
 };
 let { hs: heights, total } = heightsFor(itemW, gap);
 // 안전 영역 높이를 넘으면 간격부터 줄이고, 그래도 넘으면 로고를 함께 줄인다
 if (bounds && total > by1 - by0) {
 gap = Math.max(12, gap * 0.4);
 ({ hs: heights, total } = heightsFor(itemW, gap));
 if (total > by1 - by0) {
 const k = (by1 - by0 - gap * (items.length - 1)) / Math.max(1, total - gap * (items.length - 1));
 itemW = Math.max(30, itemW * k);
 ({ hs: heights, total } = heightsFor(itemW, gap));
 }
 }
 let cy = bounds ? bkClamp(centerY - total / 2, total, by0, by1) : centerY - total / 2;
 items.forEach((l, i) => {
 const h = heights[i];
 const w = Math.min(itemW, h * (l.ratio || 1));
 drawWithShadow(cx, l.img, centerX - w / 2, cy, w, h, sh);
 cy += h + gap;
 });
}

// 로고 목록을 가로로 배열해 그린다 (세로 중앙 기준)
function drawLogoRow(cx, logos, centerX, centerY, itemW0, gap0, sh, bounds) {
 const items = logos.filter(Boolean);
 if (!items.length) return;
 let itemW = itemW0, gap = gap0;
 // 가로 총폭이 안전 영역을 넘으면 간격을 먼저 줄이고, 그래도 넘으면 로고를 줄인다
 if (bounds) {
 const avail = bounds.x1 - bounds.x0;
 if (itemW * items.length + gap * (items.length - 1) > avail) {
 gap = Math.max(16, gap * 0.35);
 const room = avail - gap * (items.length - 1);
 itemW = Math.max(30, Math.min(itemW, room / items.length));
 }
 itemW = Math.min(itemW, (bounds.y1 - bounds.y0) / 0.62);
 }
 const maxH = itemW * 0.62;
 const total = itemW * items.length + gap * (items.length - 1);
 let cxPos = bounds ? bkClamp(centerX - total / 2, total, bounds.x0, bounds.x1) : centerX - total / 2;
 const rowTop = bounds ? bkClamp(centerY - maxH / 2, maxH, bounds.y0, bounds.y1) : centerY - maxH / 2;
 items.forEach((l) => {
 const h = Math.min(itemW / (l.ratio || 1), maxH);
 const w = Math.min(itemW, h * (l.ratio || 1));
 drawWithShadow(cx, l.img, cxPos + (itemW - w) / 2, rowTop + (maxH - h) / 2, w, h, sh);
 cxPos += itemW + gap;
 });
}

// ─────────────────────────────────────────────────────────────
// v873: 이미지가 도착하기 전에 자리를 먼저 잡는 썸네일.
//
// 생성이 끝나면 <img> 가 로드되는 순간 높이가 생겨 아래 요소가 밀렸다.
// 비율로 자리를 먼저 확보하고, 로드될 때까지 '불러오는 중' 을 띄운다.
// ─────────────────────────────────────────────────────────────
const LoadingImage = ({ src, ratio = '3 / 2', radius = 10, borderColor, label = '불러오는 중…',
 compact = false, width, height, objectFit = 'cover', borderWidth = 2 }) => {
 // v874: 상태를 effect 로 되돌리면 안 된다.
 //   useEffect(passive) 는 페인트 뒤로 밀리는데, data: URL 은 load 이벤트가
 //   그보다 먼저 오는 경우가 있다. 그러면 onLoad 의 'ok' 를 effect 가 다시
 //   'loading' 으로 덮어써 영원히 '불러오는 중' 에 머문다(결과 창에서 실제로 그랬다).
 //   → 상태를 src 에서 유도한다. 되돌릴 일 자체가 없어진다.
 const [loadedSrc, setLoadedSrc] = useState(null);
 const [failedSrc, setFailedSrc] = useState(null);
 const state = !src ? 'loading' : (failedSrc === src ? 'error' : (loadedSrc === src ? 'ok' : 'loading'));
 return (
 <div style={{
 position: 'relative', width: width ?? '100%', height,
 aspectRatio: height ? undefined : ratio,
 borderRadius: radius, overflow: 'hidden', flexShrink: 0,
 border: `${borderWidth}px solid ${borderColor || 'var(--border)'}`, background: 'var(--bg-tertiary)',
 }}>
 {src && (
 <img src={src} alt=""
 // 이미 캐시에 있어 load 이벤트를 놓치는 경우까지 붙는 시점에 확인한다
 ref={(el) => { if (el && el.complete && el.naturalWidth > 0) setLoadedSrc(src); }}
 onLoad={() => setLoadedSrc(src)} onError={() => setFailedSrc(src)}
 style={{ width: '100%', height: '100%', objectFit, display: 'block',
 opacity: state === 'ok' ? 1 : 0, transition: 'opacity .18s ease' }} />
 )}
 {state !== 'ok' && (
 <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center',
 justifyContent: 'center', gap: 7, padding: 6, textAlign: 'center' }}>
 {state === 'error' ? (
 <span className="micro" style={{ color: 'var(--text-quaternary)' }}>{compact ? '실패' : '불러오지 못했습니다'}</span>
 ) : (<>
 <RefreshCw size={compact ? 11 : 13} className="spin" color="var(--green-500)" />
 {!compact && <span className="micro" style={{ color: 'var(--text-tertiary)' }}>{label}</span>}
 </>)}
 </div>
 )}
 </div>
 );
};

// v874: 배치 기본값 — 초기 상태 · 작업 초기화 · '기본값으로' 버튼이 같은 값을 쓴다.
//   세 곳에 흩어져 있으면 하나만 고쳐 놓고 나머지가 어긋난다.
const BOOKLET_LAYOUT_DEFAULTS = () => ({
 logoLayout: { sideY: 50, sideW: 44, bottomY: 92, bottomW: 30, showBottom: true },
 titleLayout: { y: 55, w: 74 },
 creditsLayout: { y: 6, size: 100 },
 show: { title: true, logos: true, credits: true, recipient: true },
 titleShadow: { enabled: false, color: '#000000', opacity: 60, blur: 18, offsetX: 0, offsetY: 6 },
 logoShadow: { enabled: false, color: '#000000', opacity: 60, blur: 18, offsetX: 0, offsetY: 6 },
});

// ─────────────────────────────────────────────────────────────
// v879: 프로젝트 워크플로우 — 로드맵과 데이터 모델
//
// 흐름: 시나리오 → 구간 나누기 → 검토·승인 → 프롬프트 → 레퍼런스·생성
//
// 용어. '구간(segment)' 은 시나리오를 잘라낸 한 덩어리이고,
//   '컷(cut)' 은 영상 1회 생성 단위다. 둘은 같지 않다 —
//   영상 모델이 한 번에 최대 15초라, 일반씬 30초 구간은 컷 2개가 된다.
//   v891: 이제 구간 1개 = 클립 1개다. 아래 PROJECT_SEC_MAX_FOR 주석 참고.
//   컷과 컷의 연결이 이 작업의 최우선 과제라, 컷은 항상 구간에 소속된 채로
//   앞뒤 컷을 알고 있어야 한다.
// ─────────────────────────────────────────────────────────────
// 최근 수정 시각 — 오늘이면 시각만, 아니면 날짜까지
const fmtProjectTime = (ts) => {
 const t = Number(ts) || 0;
 if (!t) return '—';
 const dt = new Date(t);
 const now = new Date();
 const hhmm = `${String(dt.getHours()).padStart(2, '0')}:${String(dt.getMinutes()).padStart(2, '0')}`;
 const sameDay = dt.getFullYear() === now.getFullYear() && dt.getMonth() === now.getMonth() && dt.getDate() === now.getDate();
 return sameDay ? `오늘 ${hhmm}`
 : `${dt.getFullYear()}.${String(dt.getMonth() + 1).padStart(2, '0')}.${String(dt.getDate()).padStart(2, '0')} ${hhmm}`;
};

// v881: 분량은 '상한선' 이다. 고정값이 아니다.
//   v1061: 두 종류 모두 최대 30초다(2.5 로 통일). 그 이하는 자유다.
//   고정으로 두면 시나리오를 15초 격자에 억지로 맞춰야 하고, 격자에 안 떨어지는
//   자투리를 어떻게 할지 규칙이 따로 필요해진다. 상한선으로 두면 구간을
//   시나리오의 호흡대로 자를 수 있어 그 문제가 사라진다.
//   컷 수는 고정이 아니라 ceil(구간초 / 모델의 1회 생성 상한) 으로 계산한다.
// 프로젝트 하나 = 에피소드 한 편(5분 이내). 시나리오 전체는 볼륨이 너무 크다.
//   v886: 코드로 검사하지는 않는다. 예전에는 글자수 추정치로 5분 초과를 경고했는데,
//   그 추정(1분 500자)에 근거가 없어서 걷어냈다. 실제 컷 길이가 나오면
//   그때 진짜 값으로 다시 붙일 자리다. 지금은 기준을 적어두는 용도.
const PROJECT_EPISODE_MAX_SEC = 300;
// v891: 구간 하나가 영상 생성 한 번이다. 1:1 이라 개수를 셀 것이 없다.
//   생성물을 '컷' 이라 부르지 않는다 — 컷은 편집에서 끊기지 않은 화면 한 토막을
//   뜻하는데, 생성된 영상 안에는 컷이 여러 개 들어 있다(멀티컷 생성).
//   타임라인에 놓는 영상 한 조각을 뜻하는 '클립' 을 쓴다. 구간 1개 = 클립 1개.
// v1061: 액션씬 상한이 15초였던 건 2.0 이 15초까지만 뽑아서다. 2.5 로 통일하면서
//   그 제약이 사라져 30초로 맞췄다. 종류에 따른 길이 차이는 이제 없다.
const PROJECT_SEC_MAX_NORMAL = 30;   // 일반씬 구간 상한
const PROJECT_SEC_MAX_ACTION = 30;   // 액션씬 구간 상한
const PROJECT_SEC_MAX_FOR = (kind) => (kind === 'action' ? PROJECT_SEC_MAX_ACTION : PROJECT_SEC_MAX_NORMAL);

const PROJECT_STEPS = [
 { n: 1, key: 'episode', label: '에피소드', desc: '한 편(5분 이내)을 첨부하거나 붙여넣기' },
 { n: 2, key: 'segment', label: '구간 나누기', desc: '일반씬 · 액션씬으로 분류해 분량대로 자르기' },
 // v932: 검토·피드백 단계를 없앴다. 2단계에서 구간을 직접 고칠 수 있으니
 //   따로 훑어보는 화면이 필요없다 — 거기서 검토하고 바로 승인한다.
 { n: 3, key: 'shoot', label: '레퍼런스 · 생성', desc: '씬마다 레퍼런스를 걸고 클립을 뽑는다' },
 { n: 4, key: 'result', label: '생성 결과', desc: '클립을 넘겨보며 확인하고 피드백으로 고친다' },
];

// v975: 단계 번호를 상수로 박지 않는다. v932 에서 3단계(검토·피드백)를 없앨 때
//   '레퍼런스 자동 추출' 이 step === 4 를 보고 있어서, 촬영 단계가 3으로 내려간
//   뒤로는 한 번도 돌지 않았다 — 레퍼런스가 하나도 안 걸리던 원인이다.
const PROJECT_STEP_OF = (key) => (PROJECT_STEPS.find(x => x.key === key) || {}).n || 0;
const PROJECT_STEP_SHOOT = PROJECT_STEP_OF('shoot');

// 대본에서 레퍼런스로 걸 대상만 뽑는다. 1단계 '내용 정리' 를 건너뛰면 씬 정보가
//   없어서 자동 추출이 조용히 아무 일도 안 했다 — 그때 이 경로로 직접 뽑는다.
const PROJECT_REF_EXTRACT_SYS = `당신은 대본에서 '영상 레퍼런스로 걸 대상' 을 뽑는 스크립트 슈퍼바이저입니다.
씬 몇 개의 본문을 받아, 씬마다 인물 · 장소 · 소품을 뽑습니다.

※★ 이 지침의 예시에 나오는 대괄호 표기([남자1] · [여자1] · [실내장소] ·
   [실외장소])는 자리표시자입니다. 이름이 아니고, 설명을 위한 빈칸입니다.
   출력에 이 표기를 그대로 적어서는 절대 안 됩니다 — 대괄호도, 그 안의 글자도
   나가지 않습니다. 언제나 받은 대본에 적힌 실제 이름을 그대로 쓰십시오.

[대본 형식 — 콜론이 없을 수도 있습니다]
대사는 \`이름 : 대사\` 일 수도 있고, 콜론 없이 \`이름 대사\` 이거나
\`이름 (연기 지시) 대사\` 일 수도 있습니다. 줄 앞머리에 사람 이름이 있고 그 뒤에
말이 이어지면 그 사람은 이 씬에 있는 인물입니다.
  [남자1] (한쪽 입꼬리를 올리며) 찾았다.   → 인물: [남자1]
  야쿠자1 침입자다! 금고 쪽을 막아!      → 인물: 야쿠자1

[인물]
- 이 씬에서 말하거나 움직이는 인물의 이름만. 말로만 언급된 사람은 넣지 마십시오.
- 대본에 적힌 이름 그대로. '야쿠자1' 처럼 번호가 붙은 이름도 그대로 씁니다.
- 이름이 없는 무리(행인들, 손님들)는 넣지 마십시오.

[장소]
- 그 씬이 벌어지는 곳 하나. 씬 머리글이 있으면 그 말을 그대로 씁니다.
  없으면 지문에서 읽어 짧은 이름으로 적으십시오 ("금고실", "[실외장소]").

[소품]
- 인물이 집거나 들거나 놓거나 던지거나 건네거나 받거나 열거나 닫거나 꺼내거나
  넣거나 켜거나 끄거나 입거나 벗거나 마시거나 쓰거나 겨누거나 부수는 물건은
  전부 넣으십시오. 한 번만 나와도 넣습니다.
- 이야기에서 뜻을 갖는 물건(증거물, 유품, 사진, 편지, 열쇠), 탈것,
  그 인물을 알아보게 하는 착용물(특정 마스크, 목걸이, 제복)도 넣으십시오.
- 빼는 것: 문 · 창문 · 벽 · 바닥 · 천장 · 계단 · 조명처럼 공간에 붙박인 것,
  아무도 손대지 않는 흔한 가구. 단 인물이 그것을 쓰거나 부수면 넣습니다.
- 대본에 적힌 말 그대로. '물건' 처럼 뭉뚱그리지 마십시오.
- ★★ 인물의 고유 소품은 따로 뽑으십시오. 같은 종류의 물건을 여러 인물이 쓰는데
  그중 한 인물의 것이 이야기상 구별된다면 '<인물 이름>의 <소품>' 으로 따로 넣습니다.
      주인공은 개조한 권총, 조직원들은 똑같은 권총 → ["권총", "[남자1]의 권총"]
  구별 신호 — 대본이 그 물건만 따로 묘사한다(각인 · 개조 · 색 · 흠집) ·
  그 인물이 계속 같은 물건을 쓴다 · 그 물건이 이야기에서 뜻을 갖는다.
  일반형('권총')도 함께 남기십시오. 둘은 다른 이미지를 붙일 다른 소품입니다.
  겹치는 것이 없으면 이름을 붙이지 말고 그냥 '권총' 으로 두십시오.

[출력 — JSON 하나만]
{ "scenes": [ { "key": "2", "characters": ["[남자1]", "야쿠자1"], "place": "창고 내의 비밀 금고",
                "objects": ["USB", "흑색 상자", "마스크", "금괴"] } ] }
- key 는 입력에 적힌 그 씬의 key 를 그대로 돌려주십시오.
- 설명·머리말·코드펜스 없이 JSON 만 출력하십시오.`;

// v994: 분량이 꽉 차서 연기·대사에 여유가 없다는 지적(정진님). 저장본 47구간을
//   재보니 대사 기준 평균은 초당 4.2자로 무리가 없었는데, 꽉 찬 구간이 7~8.4자/초
//   였다 — 뉴스 읽는 속도다. 그래서 전부 늘리지 않고 '하한선' 만 둔다.
//   (이 상수는 모델이 sec 을 안 줬을 때의 폴백이다. 본체는 구간 나누기 지시문.)
// 대략적인 발화·진행 속도. 전체 글자수 기준 — 예전 8.3자/초는 너무 빡빡했다.
//   실측 근거가 없는 추정치다 — 나중에 실제 생성물과 비교해 조정할 자리.
const PROJECT_CHARS_PER_SEC = 7.0;

// ─────────────────────────────────────────────────────────────
// v1002: 대본 언어. 대본은 한국어로 들어오고, 화면에서 말하는 대사만 고른 언어로
//   나간다. 지문 · 씬 정보 · 레퍼런스 이름은 한국어 그대로다 — 그건 프롬프트를
//   쓰는 쪽이 읽는 글이고, 소리로 나가지 않는다.
//   번역은 구간 나누기 직후 한 번 돌려 구간에 붙여 둔다. 클립을 뽑을 때마다
//   번역하면 같은 대사가 클립마다 다르게 나올 수 있다.
// ─────────────────────────────────────────────────────────────
const PROJECT_LANGS = [
 { id: 'ko', label: '한국어', en: 'Korean', note: 'standard Seoul Korean' },
 { id: 'en', label: '영어', en: 'English', note: 'natural conversational English' },
 { id: 'zh', label: '중국어', en: 'Mandarin Chinese', note: 'standard Mandarin (普通话)' },
 { id: 'ja', label: '일본어', en: 'Japanese', note: 'standard Tokyo Japanese',
 pace: '★ 일본어는 같은 뜻을 말하는 데 한국어보다 모라가 1.5~1.6배 늘어납니다(실측).'
 + ' 구간 길이는 한국어 대본으로 정해져 있으므로, 늘어난 만큼 대사가 클립을 넘칩니다.'
 + ' 뜻을 지키면서 문장을 짧게 잡으십시오 — 없어도 통하는 조사 · 수식어 · 군더더기'
 + ' 어미를 덜어내고, 긴 문장은 끊으십시오. 원문보다 길어지면 안 됩니다.' },
{ id: 'de', label: '독일어', en: 'German', note: 'standard High German (Hochdeutsch)',
 pace: '★ 독일어는 같은 뜻을 담는 데 한국어보다 음절이 늘어나기 쉽습니다(합성어 · 긴 어미).'
 + ' 구간 길이는 한국어 대본으로 정해져 있으므로 늘어난 만큼 대사가 클립을 넘칩니다.'
 + ' 뜻을 지키면서 짧게 잡고, 긴 문장은 끊으십시오. 원문보다 길어지면 안 됩니다.' },
{ id: 'fr', label: '프랑스어', en: 'French', note: 'standard Parisian French',
 pace: '★ 프랑스어는 같은 뜻을 담는 데 한국어보다 음절이 늘어나기 쉽습니다(관사 · 전치사 · 우언법).'
 + ' 구간 길이는 한국어 대본으로 정해져 있으므로 늘어난 만큼 대사가 클립을 넘칩니다.'
 + ' 뜻을 지키면서 짧게 잡고, 긴 문장은 끊으십시오. 원문보다 길어지면 안 됩니다.' },
];
const PROJECT_LANG_OPTIONS = PROJECT_LANGS.map(x => ({ id: x.id, label: x.label }));
const projectLangInfo = (id) => PROJECT_LANGS.find(x => x.id === id) || PROJECT_LANGS[0];
const projectLangOf = (d) => (PROJECT_LANGS.some(x => x.id === d?.lang) ? d.lang : 'ko');

// 대사 줄 — `이름 : 말` 한 줄. 이름에 (NA) 같은 표기가 붙기도 한다.
//   판정은 기존 코드와 같은 형태를 쓴다(콜론 앞 24자 이내).
const projectDlgLines = (text) => String(text || '').split('\n')
 .map(x => x.trim()).filter(x => /^[^:]{1,24}\s*:/.test(x))
 .map(x => {
 const i = x.indexOf(':');
 return { who: x.slice(0, i).trim(), said: x.slice(i + 1).trim() };
 })
 .filter(x => !!x.said);

// v1009: 역번역은 반드시 한국어여야 한다. 한글이 한 글자라도 있는지로 판정한다 —
//   중국어 · 일본어 · 영어에는 한글 음절이 없으므로 이것으로 갈린다.
const projectHasHangul = (t) => /[가-힣ㄱ-ㅎㅏ-ㅣ]/.test(String(t || ''));

// 번역문·역번역에서 괄호(연기 지시)를 걷어낸다. 지시문으로도 막지만 코드로
//   한 번 더 막는다 — 따옴표 안에 남으면 영상 모델이 그걸 소리 내어 읽는다.
//   연기 지시는 [이 구간의 대본] 으로 프롬프트 쓰는 쪽에 그대로 전달된다.
const projectTrClean = (t) => String(t == null ? '' : t)
 .replace(/[（(][^)）]*[)）]/g, ' ')
 .replace(/\s{2,}/g, ' ')
 .trim()
 .replace(/^[「『"'“”]+|[」』"'“”]+$/g, '')
 .trim();

// 액션으로 볼 신호. 지금은 낱말 사전이다 — 나중에 LLM 분류로 바꿀 자리.
const PROJECT_ACTION_WORDS = [
 '싸움', '싸운다', '몸싸움', '격투', '난투', '주먹', '발차기', '멱살', '밀친다', '밀어',
 '추격', '쫓는다', '쫓아', '달린다', '뛴다', '뛰어', '도망', '질주',
 '총', '총성', '발사', '칼', '칼날', '휘두른다', '찌른다', '베어',
 '폭발', '충돌', '부딪', '넘어진다', '쓰러진다', '굴러', '던진다', '피한다', '막아',
 '유리', '깨진다', '부순다', '차량', '급브레이크', '핸들',
];

// 씬 머리글 — 한국 시나리오에서 흔한 형태들
const PROJECT_SCENE_HEAD = /^\s*(?:S\s*#\s*\d+|씬\s*\d+|#\s*\d+|\d+\s*[.)]\s*(?:내부|외부|낮|밤|INT|EXT)|(?:INT|EXT)\s*[.．]?)/i;

const projectEstimateSec = (text) => {
 const n = String(text || '').replace(/\s+/g, ' ').trim().length;
 if (!n) return 0;
 return Math.max(2, Math.round(n / PROJECT_CHARS_PER_SEC));
};

const projectClassifyKind = (text) => {
 const t = String(text || '');
 let hits = 0;
 for (const w of PROJECT_ACTION_WORDS) if (t.includes(w)) hits++;
 // 짧은 글에 액션 낱말이 두 개 이상 몰려 있으면 액션으로 본다
 return hits >= 2 ? 'action' : 'normal';
};

// ─────────────────────────────────────────────────────────────
// v882: 로컬 구간 분할. API 를 쓰지 않는다.
//
// UI 를 보려면 결과물이 있어야 해서 먼저 로컬 규칙으로 만든다.
// 나중에 LLM 분류·분할로 바꿀 때 이 함수만 갈아끼우면 되도록,
// 입력(시나리오 텍스트)과 출력(구간 배열) 모양을 고정해 둔다.
//
// 규칙: 씬 머리글로 씬을 가르고(없으면 빈 줄로 문단을 가른다),
//   씬마다 액션/일반을 판정하고, 상한을 넘으면 줄 단위로 더 쪼갠다.
//   상한은 상한일 뿐이라 짧은 구간은 그대로 둔다(억지로 합치지 않는다).
// ─────────────────────────────────────────────────────────────
const projectSplitEpisode = (rawText) => {
 const text = String(rawText || '').replace(/\r\n?/g, '\n').trim();
 if (!text) return [];
 const lines = text.split('\n');

 // 1) 씬 단위로 모은다
 const scenes = [];
 let cur = null;
 for (const line of lines) {
 if (PROJECT_SCENE_HEAD.test(line)) {
 if (cur) scenes.push(cur);
 cur = { head: line.trim(), lines: [] };
 } else if (cur) {
 cur.lines.push(line);
 } else {
 // 머리글 앞에 있는 내용 — 이름 없는 첫 씬으로 담는다
 cur = { head: '', lines: [line] };
 }
 }
 if (cur) scenes.push(cur);

 // 머리글이 하나도 없었으면 빈 줄로 문단을 가른다
 const blocks = scenes.length > 1 || scenes[0]?.head
 ? scenes
 : text.split(/\n\s*\n/).map(b => ({ head: '', lines: b.split('\n') }));

 // 2) 씬을 상한에 맞춰 구간으로 자른다
 const out = [];
 let seq = 0;
 for (const b of blocks) {
 const body = b.lines.join('\n').trim();
 if (!body && !b.head) continue;
 const kind = projectClassifyKind(`${b.head}\n${body}`);
 const cap = PROJECT_SEC_MAX_FOR(kind);

 // 줄을 순서대로 담다가 상한을 넘으면 끊는다
 const src = body ? body.split('\n') : [];
 let bucket = [];
 let bucketSec = 0;
 const flush = () => {
 const t = bucket.join('\n').trim();
 if (!t && !(out.length === 0 && b.head)) { bucket = []; bucketSec = 0; return; }
 seq += 1;
 out.push({
 id: `sg_${Date.now().toString(36)}_${seq}`,
 kind,
 ...(({ no, place, time }) => ({ sceneNo: no, place, time }))(projectParseHead(b.head)),
 why: '',
 text: t,
 sec: Math.min(cap, Math.max(2, bucketSec || projectEstimateSec(t))),
 prompt: '', clipUrl: '',
 });
 bucket = []; bucketSec = 0;
 };
 for (const line of src) {
 const ls = projectEstimateSec(line);
 // 한 줄만으로도 상한을 넘으면 그 줄은 혼자 한 구간이 된다
 if (bucketSec + ls > cap && bucket.length) flush();
 bucket.push(line);
 bucketSec += ls;
 }
 flush();
 }
 return out;
};

// ─────────────────────────────────────────────────────────────
// v882: 구간 편집 연산. 순수 함수로 둔다 —
//   상태 훅 안에 묻어 두면 검증할 수가 없다. (list, …) → list.
// ─────────────────────────────────────────────────────────────
const projectSegOps = {
 // 종류를 바꾸면 상한이 달라진다 → 초가 새 상한을 넘으면 함께 줄인다
 kind: (list, id, kind) => list.map(g => (g.id === id
 ? { ...g, kind, sec: Math.min(g.sec, PROJECT_SEC_MAX_FOR(kind)) } : g)),

 sec: (list, id, sec) => list.map(g => {
 if (g.id !== id) return g;
 const cap = PROJECT_SEC_MAX_FOR(g.kind);
 return { ...g, sec: Math.max(1, Math.min(cap, Math.round(Number(sec) || 0))) };
 }),

 patch: (list, id, patch) => list.map(g => (g.id === id ? { ...g, ...patch } : g)),

 remove: (list, id) => list.filter(g => g.id !== id),

 // 줄 수 절반에서 둘로 가른다. 초는 글자 수 비율로 나눈다.
 split: (list, id, stamp) => {
 const i = list.findIndex(g => g.id === id);
 if (i < 0) return list;
 const g = list[i];
 const lines = String(g.text || '').split('\n');
 if (lines.length < 2) return list;   // 한 줄은 가를 수 없다
 const half = Math.ceil(lines.length / 2);
 const aText = lines.slice(0, half).join('\n').trim();
 const bText = lines.slice(half).join('\n').trim();
 const cap = PROJECT_SEC_MAX_FOR(g.kind);
 const total = aText.length + bText.length || 1;
 const aSec = Math.max(1, Math.min(cap, Math.round(g.sec * (aText.length / total))));
 const bSec = Math.max(1, Math.min(cap, g.sec - aSec));
 const next = [...list];
 next.splice(i, 1,
 { ...g, id: `${g.id}_a${stamp}`, text: aText, sec: aSec },
 { ...g, id: `${g.id}_b${stamp}`, text: bText, sec: bSec, why: '' },
 );
 return next;
 },

 // 위 구간과 합친다. 종류는 위 구간을 따르고, 초는 그 상한까지만.
 //   v942: 씬이 다르면 합치지 않는다. 씬이 곧 장소·시간이라, 합쳐 놓으면 한 클립에
 //   서로 다른 장소가 들어가고 레퍼런스도 어느 씬 것을 붙일지 정할 수 없게 된다.
 mergeUp: (list, id) => {
 if (!id) return list;
 const i = list.findIndex(g => g.id === id);
 if (i <= 0) return list;
 const a = list[i - 1], b = list[i];
 if (!projectSameScene(a, b)) return list;
 const cap = PROJECT_SEC_MAX_FOR(a.kind);
 const next = [...list];
 next.splice(i - 1, 2, {
 ...a,
 text: [a.text, b.text].filter(Boolean).join('\n').trim(),
 sec: Math.max(1, Math.min(cap, a.sec + b.sec)),
 });
 return next;
 },

 add: (list, id) => [...list, { id, kind: 'normal', sceneNo: '', place: '', time: '', why: '', text: '', sec: 10, prompt: '', clipUrl: '' }],
};

// ─────────────────────────────────────────────────────────────
// v889: 대본 구조화 (프롬프트)
//
// PDF 에서 긁어온 텍스트를 그대로 쓰면 안 된다. 페이지 번호, 머리말·꼬리말,
// 반복되는 작품명, 줄이 중간에 끊긴 대사가 섞여 들어온다. 그걸 그대로 구간
// 나누기에 넘기면 쓰레기가 구간이 된다.
//
// 그래서 한 번 읽고 정리한다. 실제 내용(대사·지문)만 남기고,
// 제목·씬넘버·장소·시간은 메타데이터로 따로 뽑는다.
// 장소와 시간은 나중에 레퍼런스를 붙일 때 쓸 값이라 씬 단위로 남겨 둔다.
// ─────────────────────────────────────────────────────────────
const PROJECT_SCRIPT_PARSE_SYS = `당신은 한국 드라마 대본을 정리하는 스크립트 슈퍼바이저입니다.
PDF·워드에서 기계적으로 긁어낸 지저분한 텍스트를 받아, 실제 대본 내용만 남기고 정리합니다.

※★ 이 지침의 예시에 나오는 대괄호 표기([남자1] · [여자1] · [실내장소] ·
   [실외장소])는 자리표시자입니다. 이름이 아니고, 설명을 위한 빈칸입니다.
   출력에 이 표기를 그대로 적어서는 절대 안 됩니다 — 대괄호도, 그 안의 글자도
   나가지 않습니다. 언제나 받은 대본에 적힌 실제 이름을 그대로 쓰십시오.

[버릴 것 — 대본 내용이 아닌 것]
- 페이지 번호, 쪽수 표기 ("- 12 -", "12/48")
- 페이지마다 반복되는 머리말·꼬리말, 작품 제목, 방송사·제작사 이름, 날짜, 회차 표기
- 저작권 문구, 워터마크 문구, 파일명, "대본 유출 금지" 류의 경고문
- 초고/수정고 표기, 검토용 도장 문구
- 목차, 등장인물 소개표(따로 뽑지 말고 그냥 버립니다)
- 의미 없이 반복되는 공백·구분선 (=====, -----)

[살릴 것 — 그대로 옮길 것]
- 지문(행동 묘사)과 대사. 인물 이름표도 함께.
- 원문의 표현을 고치지 마십시오. 요약·윤문·의역 금지입니다.
- PDF 때문에 한 문장이 여러 줄로 끊긴 경우에는 원래 한 줄로 이어 붙이십시오.

★ 대사 형식 — 반드시 이 모양으로 통일하십시오 ★
대사는 한 줄에 \`이름 : 대사내용\` 으로 씁니다. 이름과 콜론 사이, 콜론과 대사 사이에 각각 공백 하나.
  [남자1] : 여기가... 어디야.
  간호사 : 깨어나셨네요. 3년 만이에요.
이름 뒤 괄호 표기(NA, E, F, V.O., O.S., 소리, 필터 등)는 이름에 붙입니다.
  [남자1](NA) : 그날 이후로 시간이 멈춰 있었다.
  지훈(E) : 문 열어!
원문에서 이름과 대사가 서로 다른 줄에 있어도 한 줄로 합치십시오.
대사가 길어도 줄을 나누지 마십시오 — 대사 하나는 언제나 한 줄입니다.
대사 앞에 붙은 연기 지시 괄호는 대사 안에 그대로 두십시오.
  수현 : (작게) 오빠, 이거 봤어?

지문은 이름표 없이 그대로 씁니다. 지문 줄에는 콜론 형식을 쓰지 마십시오.
즉 콜론 형식으로 시작하는 줄은 전부 대사이고, 나머지는 전부 지문입니다.

[씬 단위로 나눌 것]
씬 머리글(S#1, 씬 1, #1, INT./EXT. 등)을 찾아 씬마다 다음을 뽑습니다.
- no    : 씬 번호. 원문 표기를 그대로 (예: "S#1", "12"). 없으면 순서대로 번호를 매기십시오.
- place : 장소. 원문의 말을 그대로 (예: "[남자1]의 [실내장소]", "[실외장소]").
          내부/외부(INT/EXT) 표기가 있으면 place 뒤에 붙이지 말고 int 에 따로 담으십시오.
- int   : "내부" | "외부" | "" (알 수 없으면 빈 문자열)
- time  : 시간대. "낮" | "밤" | "새벽" | "아침" | "저녁" | "" 중 하나로 정리하십시오.
          원문이 "D"/"N" 이면 각각 낮/밤입니다. 알 수 없으면 빈 문자열.
- characters : 이 씬에 대사나 행동이 있는 인물 이름 배열. 언급만 된 인물은 넣지 마십시오.
- objects : 이 씬에 나오는 소품 이름 배열. 놓치기 쉬우니 지문을 한 줄씩 훑으며 뽑으십시오.

  ★ 반드시 넣을 것 — 인물의 손을 타는 물건은 예외 없이 ★
  인물이 집거나 들거나 놓거나 던지거나 건네거나 받거나 열거나 닫거나 꺼내거나
  넣거나 켜거나 끄거나 입거나 벗거나 마시거나 먹거나 쓰거나 휘두르거나 겨누거나
  부수는 물건은 전부 넣으십시오. 한 번만 쓰여도 넣습니다.
  지문의 서술어가 단서입니다 — '~를 집는다 / 든다 / 꺼낸다 / 건넨다 / 내민다 /
  던진다 / 휘두른다 / 연다 / 켠다 / 확인한다' 의 목적어가 곧 소품입니다.
  대사로만 언급되더라도 그 자리에 실제로 있고 인물이 쓰는 물건이면 넣으십시오.

  그 밖에 넣을 것
  · 이야기에서 뜻을 갖는 물건 (증거물, 선물, 유품, 사진, 편지, 열쇠)
  · 탈것 (승용차, 오토바이, 구급차) — 차종·색이 적혀 있으면 함께 적으십시오
  · 그 인물을 알아보게 하는 착용물 (특정 목걸이, 시계, 안경, 제복)

  뺄 것
  · 공간에 원래 있는 붙박이 (문, 창문, 벽, 바닥, 천장, 계단, 조명)
  · 아무도 손대지 않고 배경으로만 있는 흔한 가구 (책상, 의자, 침대)
    — 단 인물이 그것을 쓰거나 옮기거나 부수면 넣으십시오.

  이름은 대본에 적힌 말 그대로 쓰십시오. '물건' 처럼 뭉뚱그리지 마십시오.

  ★★ 인물의 고유 소품은 따로 뽑으십시오 ★★
  같은 종류의 물건을 여러 인물이 쓰는데 그중 한 인물의 것이 이야기상 구별된다면,
  그것은 별개의 소품입니다. '<인물 이름>의 <소품>' 으로 따로 넣으십시오.
      총격씬에서 주인공은 개조한 권총을, 조직원들은 똑같이 생긴 권총을 쓴다
      → objects: ["권총", "지설의 권총"]
  구별해야 하는 신호는 이렇습니다.
  · 대본이 그 인물의 물건만 따로 묘사한다 (각인 · 개조 · 색 · 흠집 · 이름)
  · 그 인물이 씬마다 같은 물건을 계속 쓴다 (그 사람을 알아보게 하는 물건)
  · 그 물건이 이야기에서 뜻을 갖는다 (유품 · 증거물 · 상징)
  일반형도 함께 남기십시오 — 조연들이 쓰는 것은 '권총' 으로, 주인공 것은
  '지설의 권총' 으로. 둘은 다른 이미지를 붙일 다른 소품입니다.
  한 인물만 쓰는 물건이고 겹치는 것이 없으면 굳이 이름을 붙이지 마십시오.
  그냥 '권총' 이면 됩니다.
- body  : 그 씬의 지문과 대사 원문. 씬 머리글 줄은 body 에 넣지 마십시오.

[제목]
- title : 작품 제목. 텍스트에서 찾을 수 있으면 그대로, 없으면 빈 문자열.
- episode : 회차 표기 (예: "1화", "3부"). 없으면 빈 문자열.

[출력 — JSON 하나만]
{
  "title": "",
  "episode": "",
  "scenes": [
    { "no": "S#1", "place": "[남자1]의 [실내장소]", "int": "내부", "time": "낮",
      "characters": ["[남자1]", "간호사"], "objects": ["링거대", "환자 차트"],
      "body": "[남자1]이 눈을 뜬다. 링거 소리만 들린다.\n[남자1] : 여기가... 어디야.\n간호사 : 깨어나셨네요. 3년 만이에요.\n[남자1](NA) : 그날 이후로 시간이 멈춰 있었다." }
  ]
}
- 설명·머리말·코드펜스 없이 JSON 만 출력하십시오.
- 대본 내용을 빠뜨리지 마십시오. 버릴 것 목록에 없는 것은 모두 어느 씬의 body 엔가 들어가야 합니다.`;

const PROJECT_TIME_SET = ['낮', '밤', '새벽', '아침', '저녁'];
// 모델이 지침을 어기고 원문 표기로 답할 수 있다 — 확실한 것만 옮긴다
const PROJECT_TIME_ALIAS = { d: '낮', day: '낮', n: '밤', night: '밤', 데이: '낮', 나이트: '밤' };
const PROJECT_INT_ALIAS = { 실내: '내부', int: '내부', 내부: '내부', 실외: '외부', 야외: '외부', ext: '외부', 외부: '외부' };
// 'S#1' · '씬 1' · '#1' 처럼 이미 접두어가 붙어 온 번호에서 숫자만 남긴다
const projectSceneNo = (raw, fallback) => {
 const t = String(raw == null ? '' : raw).trim();
 if (!t) return String(fallback ?? '');
 // v892: 앞쪽의 번호를 집는다. 예전에는 '끝의 숫자' 를 찾아서
 //   'S#1. 내부 / 병실 / 낮' 같은 머리글 전체가 씬번호로 들어갔다.
 const m = t.match(/^\s*(?:S\s*#|씬|#|SCENE)?\s*(\d+(?:\s*[-–]\s*\d+)?)/i);
 if (m) return m[1].replace(/\s+/g, '');
 return t.replace(/^(S\s*#|씬|#)\s*/i, '').trim() || String(fallback ?? '');
};

// 씬 머리글 한 줄 → { no, int, place, time }
//   'S#1. 내부 / 민수의 병실 / 낮' · '12. 카페 (낮)' 같은 형태를 받는다.
const projectParseHead = (raw) => {
 const t = String(raw == null ? '' : raw).trim();
 if (!t) return { no: '', int: '', place: '', time: '' };
 const no = projectSceneNo(t, '');
 const rest = t.replace(/^\s*(?:S\s*#|씬|#|SCENE)?\s*\d+(?:\s*[-–]\s*\d+)?\s*[.)]?\s*/i, '').trim();
 const parts = rest.split(/[/·|,()]+/).map(x => x.trim()).filter(Boolean);
 let int = '', place = '', time = '';
 for (const part of parts) {
 const low = part.toLowerCase();
 if (!int && PROJECT_INT_ALIAS[low]) { int = PROJECT_INT_ALIAS[low]; continue; }
 if (!time && (PROJECT_TIME_SET.includes(part) || PROJECT_TIME_ALIAS[low])) {
 time = PROJECT_TIME_SET.includes(part) ? part : PROJECT_TIME_ALIAS[low];
 continue;
 }
 if (!place) place = part;
 }
 return { no, int, place, time };
};

// v892: 구간에서 보여줄 메타. 프롬프트를 바꾸기 전에 나눈 구간은 sceneNo·place·time
//   없이 slug 만 갖고 있다. 그런 옛 구간도 머리글을 파싱해 살려 읽는다.
const projectSegMeta = (g) => {
 if (g?.sceneNo || g?.place || g?.time) {
 return { no: g.sceneNo || '', place: g.place || '', time: g.time || '' };
 }
 const head = g?.slug || (String(g?.text || '').split('\n')[0] || '');
 if (!PROJECT_SCENE_HEAD.test(head)) return { no: '', place: '', time: '' };
 const h = projectParseHead(head);
 return { no: h.no, place: h.place, time: h.time };
};

// v942: 두 구간이 같은 씬인가. 씬 번호가 있으면 그것으로, 없으면 장소+시간으로 본다
//   (구간 나누기가 씬 번호를 못 붙인 저장본도 있다).
const projectSameScene = (a, b) => {
 const x = projectSegMeta(a), y = projectSegMeta(b);
 if (x.no || y.no) return String(x.no || '') === String(y.no || '');
 return `${x.place}|${x.time}` === `${y.place}|${y.time}`;
};

// 모델 응답 → 구조화된 대본. 구간 나누기에 넘길 text 도 여기서 만든다.
const projectNormalizeScript = (raw) => {
 const scenes = [];
 const list = Array.isArray(raw?.scenes) ? raw.scenes : [];
 list.forEach((sc, i) => {
 const body = String(sc?.body == null ? '' : sc.body).replace(/\r\n?/g, '\n').trim();
 if (!body) return;
 const t = String(sc?.time || '').trim();
 const it = String(sc?.int || '').trim();
 scenes.push({
 no: projectSceneNo(sc?.no, scenes.length + 1),
 place: String(sc?.place || '').trim(),
 int: PROJECT_INT_ALIAS[it.toLowerCase()] || '',
 time: PROJECT_TIME_SET.includes(t) ? t : (PROJECT_TIME_ALIAS[t.toLowerCase()] || ''),
 characters: Array.isArray(sc?.characters)
 ? [...new Set(sc.characters.map(c => String(c || '').trim()).filter(Boolean))].slice(0, 20)
 : [],
 objects: Array.isArray(sc?.objects)
 ? [...new Set(sc.objects.map(c => String(c || '').trim()).filter(Boolean))].slice(0, 20)
 : [],
 body,
 });
 });
 // 구간 나누기에 넘길 본문 — 씬 머리글을 사람이 읽는 형태로 되살려 붙인다
 const text = scenes.map(sc => {
 const tail = [sc.int, sc.place, sc.time].filter(Boolean).join(' / ');
 const head = tail ? `S#${sc.no}. ${tail}` : `S#${sc.no}`;
 return `${head}\n${sc.body}`;
 }).join('\n\n');
 return {
 title: String(raw?.title || '').trim(),
 episodeNo: String(raw?.episode || '').trim(),
 scenes,
 text,
 };
};

// ─────────────────────────────────────────────────────────────
// v888: 구간 나누기 하네스 (프롬프트)
//
// 낱말 사전으로 하던 판정을 모델에 넘긴다. 낱말 사전이 못 하던 것 둘:
//  · 액션 판정 — '극적인 장면' 과 '실제로 몸이 부딪히는 장면' 을 가른다.
//  · 끊는 자리 — 대사와 행동의 호흡이 끊기지 않는 지점에서 자른다.
//
// 출력은 JSON 고정. 이 파일의 parseJsonFromResponse 가 3단 복구를 갖고 있다.
// ─────────────────────────────────────────────────────────────
const PROJECT_SEGMENT_SYS = `당신은 한국 드라마의 영상화 콘티를 짜는 연출자입니다.
에피소드 대본을 받아 '구간' 으로 나눕니다. 구간은 영상으로 만들 한 덩어리입니다.

※★ 이 지침의 예시에 나오는 대괄호 표기([남자1] · [여자1] · [실내장소] ·
   [실외장소])는 자리표시자입니다. 이름이 아니고, 설명을 위한 빈칸입니다.
   출력에 이 표기를 그대로 적어서는 절대 안 됩니다 — 대괄호도, 그 안의 글자도
   나가지 않습니다. 언제나 받은 대본에 적힌 실제 이름을 그대로 쓰십시오.

[구간 종류]
- action : 액션씬
- normal : 그 밖의 모든 것

★ action 판정 기준 — 여기서 틀리면 전체가 틀립니다 ★
action 은 화면에서 물리적인 사건이 실제로 벌어지는 구간만입니다.
  · 인물이 서로 때리거나 붙잡거나 밀치거나 무기를 쓴다
  · 쫓고 쫓기며 달린다, 차량이 부딪힌다
  · 무엇이 터지거나 부서지거나 무너진다, 총을 쏜다
  · 떨어지거나 넘어져 몸이 상한다

다음은 action 이 아닙니다. 모두 normal 입니다.
  · 긴장되거나 극적이거나 분위기가 험악한 장면
  · 소리치며 다투는 장면, 협박하는 장면, 울며 매달리는 장면
  · 급하게 걷거나 뛰어들어오는 정도의 움직임
  · 사건을 말로 전하는 장면, 회상으로 언급되는 장면
  · 액션이 곧 벌어질 것 같은 직전의 대치
"극적이다" 는 판단은 쓰지 마십시오. 몸이 실제로 부딪히는지만 보십시오.
헷갈리면 normal 로 두십시오.

[분량 상한]
- normal · action 모두 구간은 최대 30초.
- 상한일 뿐이라 짧아도 됩니다. 억지로 채우지 마십시오.
- 상한을 넘겨야 할 것 같으면 그 씬을 여러 구간으로 나누십시오.

[대본 형식]
- 대사는 \`이름 : 대사내용\` 한 줄로 되어 있습니다 (\`[남자1](NA) : …\` 처럼 괄호 표기가 붙기도 합니다).
- 콜론 형식이 아닌 줄은 전부 지문입니다.

[끊는 자리]
- 대사 한 줄을 반으로 자르지 마십시오.
- 한 인물의 말이 이어지는 동안에는 끊지 마십시오.
- 행동이 시작되고 끝나는 단위로 끊으십시오 (일어선다 → 걸어간다 → 문을 연다).
- 씬이 바뀌면 반드시 끊으십시오.

[초 추정 — 연기할 여유를 두십시오]
빡빡하게 잡으면 대사가 쉴 틈 없이 이어지고 연기가 들어갈 자리가 없습니다.
실제로 나온 구간들을 재보니 대사가 초당 7~8자로 몰린 곳이 있었습니다. 그건
뉴스 읽는 속도이고, 드라마의 호흡은 초당 4~5자입니다.

- 먼저 그 구간에 실제로 걸리는 시간을 재십시오. 대사를 소리내어 읽는 시간과
  지문의 행동에 걸리는 시간을 더합니다.
    걸어 들어오기 2~3초 · 앉기 1~2초 · 무엇을 꺼내 보기 2초 · 서로 바라보기 1~2초
    망설임 · 눈물 · 침묵은 그 자체로 2초 이상
- ★ 그렇게 잡은 값이 아래 하한보다 작으면 하한으로 올리십시오.
      하한 = (대사 글자수 ÷ 4.5) + (대사 줄 수 × 1초)
  줄마다 붙는 1초는 말을 받기 전의 한 박자와 말끝의 여운입니다.
    예) 대사 4줄 90자 → 90 ÷ 4.5 = 20초, 줄마다 1초 = 4초 → 하한 24초
  지문이 많아 이미 하한보다 크게 나왔다면 그 값을 그대로 두십시오. 하한은
  '이보다 짧으면 안 된다' 는 선이고, 모든 구간을 늘리라는 뜻이 아닙니다.
- 1 이상의 정수. 상한을 넘기지 마십시오. 하한이 상한을 넘으면 억지로 줄이지 말고
  그 구간을 둘로 나누십시오 — 짧고 여유 있는 구간 둘이 꽉 찬 하나보다 낫습니다.

[출력 — JSON 하나만]
{
  "segments": [
    {
      "kind": "normal",
      "sceneNo": "1",
      "place": "[남자1]의 [실내장소]",
      "time": "낮",
      "text": "이 구간에 들어가는 대본 원문. 줄바꿈 유지.",
      "sec": 18,
      "why": "kind 를 그렇게 정한 이유 한 줄"
    }
  ]
}
- sceneNo · place · time 은 그 구간이 속한 씬의 머리글(S#N. 내부 / 장소 / 시간)에서 가져오십시오.
  머리글이 없으면 빈 문자열로 두십시오.
- text 는 대본 원문을 그대로 옮기십시오. 요약하거나 고쳐 쓰지 마십시오.
  씬 머리글 줄은 text 에 넣지 마십시오.
- 원문의 모든 내용이 어느 구간엔가 한 번씩 들어가야 합니다. 빠뜨리거나 겹치지 마십시오.
- 설명·머리말·코드펜스 없이 JSON 만 출력하십시오.`;

// 모델 응답 → 구간 배열. 상한을 넘긴 초는 여기서 깎는다(모델을 믿지 않는다).
const projectNormalizeSegments = (raw) => {
 const list = Array.isArray(raw?.segments) ? raw.segments : [];
 const out = [];
 list.forEach((r, i) => {
 const text = String(r?.text == null ? '' : r.text).replace(/\r\n?/g, '\n').trim();
 if (!text) return;
 // 모델이 'ACTION' 이나 '액션' 으로 답할 수도 있다 — 관대하게 받는다
 const k = String(r?.kind == null ? '' : r.kind).trim().toLowerCase();
 const kind = (k === 'action' || k === '액션') ? 'action' : 'normal';
 const cap = PROJECT_SEC_MAX_FOR(kind);
 const sec = Math.max(1, Math.min(cap, Math.round(Number(r?.sec) || 0) || projectEstimateSec(text)));
 const tm = String(r?.time || '').trim();
 // v892: 한 씬이 여러 구간으로 쪼개지면 두 번째부터는 머리글이 없다.
 //   모델이 메타를 비워 보내면 앞 구간에서 이어받는다 — 같은 씬이니 같은 장소·시간이다.
 const prev = out[out.length - 1];
 const carry = (v, key) => (String(v || '').trim() || (prev ? prev[key] : '') || '');
 out.push({
 id: `sg_${Date.now().toString(36)}_${i + 1}`,
 kind,
 sceneNo: projectSceneNo(r?.sceneNo ?? r?.slug, '') || (prev ? prev.sceneNo : ''),
 place: carry(String(r?.place || '').slice(0, 40), 'place'),
 time: (PROJECT_TIME_SET.includes(tm) ? tm : (PROJECT_TIME_ALIAS[tm.toLowerCase()] || '')) || (prev ? prev.time : ''),
 text,
 sec,
 why: String(r?.why || '').trim().slice(0, 120),
 prompt: '', clipUrl: '',
 });
 });
 return out;
};

