// ─────────────────────────────────────────────────────────────
// 한국어 이름 조사 처리 — 챗봇 펫 이름에 받침 유무 / 끝글자에 따라 자연스러운 조사 적용
// 예: "초코" → "초코는" (받침 없음, "이" 생략)
// "땅콩" → "땅콩이는" (받침 있음, "이" 추가)
// "복실이" → "복실이는" (이미 "이"로 끝남, "이" 중복 안 함)
// "초코" → "초코야" / "땅콩" → "땅콩아"
// ─────────────────────────────────────────────────────────────

// 한글 마지막 글자에 받침이 있는지 체크
const hasBatchim = (name) => {
 if (!name) return false;
 const last = name.charCodeAt(name.length - 1);
 // 한글 가-힣 범위
 if (last < 0xAC00 || last > 0xD7A3) return false;
 return (last - 0xAC00) % 28 !== 0;
};

// 이름이 "이"로 끝나는지
const endsWithI = (name) => !!name && name.charAt(name.length - 1) === '이';

// "이"는/이가 패턴 — 챗봇이 자기 자신 지칭할 때
// 받침 있으면 "이는/이가" (예: 땅콩이는, 땅콩이가)
// 받침 없으면 "는/가" (예: 초코는, 초코가)
// 이미 "이"로 끝나면 그대로 "는/가" (예: 복실이는, 복실이가) — "이" 중복 안 함
const withNeun = (name) => {
 if (!name) return '';
 if (endsWithI(name)) return `${name}는`;
 if (hasBatchim(name)) return `${name}이는`;
 return `${name}는`;
};

const withGa = (name) => {
 if (!name) return '';
 if (endsWithI(name)) return `${name}가`;
 if (hasBatchim(name)) return `${name}이가`;
 return `${name}가`;
};

// "이에요" / "예요" 분기 — 받침 있으면 "이에요", 없으면 "예요"
const withYeyo = (name) => {
 if (!name) return '';
 if (hasBatchim(name)) return `${name}이에요`;
 return `${name}예요`;
};

