const pickRandomLunch = (excludeList = []) => {
 const pool = LUNCH_MENU_POOL.filter(m => !excludeList.includes(m));
 return pool[Math.floor(Math.random() * pool.length)];
};

const pickRandomDelivery = (excludeList = []) => {
 const pool = LUNCH_DELIVERY_POOL.filter(m => !excludeList.includes(m));
 return pool[Math.floor(Math.random() * pool.length)];
};

// 배달 추천 여부 결정 — 10% 확률
const shouldRecommendDelivery = () => Math.random() < 0.1;

const pickRandomLunches = (count = 3, excludeList = []) => {
 const pool = LUNCH_MENU_POOL.filter(m => !excludeList.includes(m));
 // 셔플 후 앞 N개
 const shuffled = [...pool].sort(() => Math.random() - 0.5);
 return shuffled.slice(0, Math.min(count, pool.length));
};

// 점심 시간대 체크 (11:00 ~ 12:30) — 자발적 추천은 12시 30분까지만
const isLunchTime = () => {
 const now = new Date();
 const totalMinutes = now.getHours() * 60 + now.getMinutes();
 // 11:00 = 660분, 12:30 = 750분
 return totalMinutes >= 660 && totalMinutes <= 750;
};

// 점심 관련 키워드 매칭 (사용자 메시지)
const isLunchQuery = (text) => {
 if (!text) return false;
 const lower = text.toLowerCase();
 return /점심|뭐\s*먹|뭐먹|메뉴|배고프|배\s*고프|food|lunch|먹을것|먹을\s*것|추천.*먹|먹.*추천|뭘\s*먹/i.test(lower);
};

