// v753: 커스텀 이미지 워크스페이스의 비율 선택 → size 문자열. 생성부와 미리보기가 같은 로직을 쓰도록 모듈 스코프로 승격.
//   반환값은 화면비 힌트로만 쓰이고, 실제 픽셀 크기는 falImageSize(size, tier)가 결정한다.
const customAspectToSize = (aspect) => {
 const m = String(aspect || '').trim().match(/^(\d+(?:\.\d+)?)\s*[:xX]\s*(\d+(?:\.\d+)?)$/);
 if (!m) return null;
 const rw = parseFloat(m[1]), rh = parseFloat(m[2]);
 if (!rw || !rh) return null;
 // 화면비만 담은 기준 크기 (긴 변 1920) — 실제 출력 크기는 falImageSize(size, tier)가 결정
 return rw >= rh ? `1920x${Math.round(1920 * rh / rw)}` : `${Math.round(1920 * rw / rh)}x1920`;
};

// 음악 생성 비용 — 곡 수 기반
const estimateMusicCost = (numSongs) => numSongs * MODEL_PRICING['music'].per_request;

