 const [customRefSuggest, setCustomRefSuggest] = useState(null);
 const customPromptTaRef = useRef(null); // v636: 자동완성 적용 후 캐럿 위치 지정용

 // 커스텀 이미지 생성 — callFalImage 하네스 재사용, 샘플 모드 지원
 // v759: 캐릭터 디자인 (Realism) 생성 — Seedream 5.0 전용 (ModelArk)
 //   비차단 생성: 생성기록에 로딩 항목을 먼저 넣고 완료 시 교체한다 (커스텀 이미지와 동일 패턴)
 // v759: 캐릭터 시트 다운로드 — 커스텀 이미지와 동일한 저장 흐름(확인 팝업 + 아카이브 보관)
 const handleDownloadCharacter = async (url) => {
 const gen = (characterWsData?.generations || []).find(g => (g.urls || []).includes(url));
 const nm = (gen?.params?.name || characterWsData?.name || '').trim();
 // v764: FFS_캐릭터_이름_v001 형식 (이름 미입력 시 키워드로 폴백)
 const namePart = nm || await ffsKeyword(characterWsData?.features);
 const fileName = (await ffsBuildName({ type: '캐릭터', parts: [namePart] })) + '.png';
 setConfirmDialog({
 title: '이미지 저장',
 message: `"${fileName}"\n\n다운로드 폴더에 저장되고, 아카이브(이미지)에도 보관됩니다.`,
 confirmLabel: '저장',
 onConfirm: async () => {
 setConfirmDialog(null);
 try {
 const res = await fetch(url);
 const blob = await res.blob();
 const objUrl = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = objUrl; a.download = fileName;
 document.body.appendChild(a); a.click(); document.body.removeChild(a);
 URL.revokeObjectURL(objUrl);
 try { showToast('이미지를 저장했습니다.', 'load'); } catch {}
 } catch (err) {
 setCharacterWsData(p => ({ ...p, error: `다운로드 실패: ${err.message}` }));
 }
 },
 });
 };

// v776: 아카이브 캐릭터 팝업 다운로드 — 저장된 엔트리에서 직접 이름/이미지를 얻는다.
 //   handleDownloadCharacter는 워크스페이스의 generations를 뒤지므로 저장본에는 쓸 수 없다.
 //   ARK 원본 URL(24h)이 만료됐으면 보관된 원본 바이트를 그대로 저장한다.
 // v967: 그림판 저장 — dataURL 을 그대로 blob 으로 바꿔 다운로드. 이름은 앱 규칙을 따른다.
 const handlePaintSave = async (dataUrl) => {
 if (!dataUrl) return;
 try {
 const fileName = (await ffsBuildName({ type: '그림' })) + '.png';
 window.electronAPI?.setDownloadCategory?.('image');
 const res = await fetch(dataUrl);
 const blob = await res.blob();
 const objUrl = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = objUrl; a.download = fileName;
 document.body.appendChild(a); a.click(); document.body.removeChild(a);
 URL.revokeObjectURL(objUrl);
 // 토스트(zIndex 999)는 그림판 오버레이(10100) 밑에 깔려 안 보인다 — 결과는 팝업 안에서 알린다
 return fileName;
 } catch {
 return null;
 }
 };

 const handleDownloadSavedCharacter = async (c) => {
 if (!c) return;
 const src = characterRefSrc(c);
 if (!src) { setCharVoiceError('이 캐릭터에는 저장된 이미지 데이터가 없습니다.'); return; }
 const fileName = (await ffsBuildName({ type: '캐릭터', parts: [String(c.name || '캐릭터').trim()] })) + '.png';
 setConfirmDialog({
 title: '이미지 저장',
 message: `"${fileName}"\n\n다운로드 폴더에 저장되고, 아카이브(이미지)에도 보관됩니다.`,
 confirmLabel: '저장',
 onCancel: () => setConfirmDialog(null),
 onConfirm: async () => {
 setConfirmDialog(null);
 try {
 // 아카이브 화면에서 내려받으므로 분류를 이미지로 명시한다
 window.electronAPI?.setDownloadCategory?.('image');
 // v974: 원본이 userData 파일이면 fetch 가 못 읽는다 — 읽어서 data URL 로 바꾼다
 const readable = await assetSrcForModel(src);
 if (!readable) throw new Error('보관된 원본을 읽지 못했습니다.');
 const res = await fetch(readable);
 const blob = await res.blob();
 const objUrl = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = objUrl; a.download = fileName;
 document.body.appendChild(a); a.click(); document.body.removeChild(a);
 URL.revokeObjectURL(objUrl);
 try { showToast('이미지를 저장했습니다.', 'load'); } catch {}
 } catch (err) {
 setCharVoiceError(`다운로드 실패: ${err.message}`);
 }
 },
 });
 };

  const handleGenerateCharacter = async (feedbackText = '') => {
 const d = characterWsData;
 const up = (patch) => setCharacterWsData(p => typeof patch === 'function' ? patch(p) : ({ ...p, ...patch }));
 if (!d.features.trim()) { up({ error: '외적 특징을 입력해주세요.' }); return; }
 // ModelArk 키가 없으면 생성 자체가 불가 — 명확히 안내
 try { arkKey(); } catch (e) { up({ error: e.message }); return; }

 const isFeedback = !!feedbackText.trim();
 // v767: 피드백 재생성은 기존 이름 뒤에 버전을 붙인다 (김서준 → 김서준_v002 → _v003 …)
 //   레퍼런스 이미지는 넣지 않는다 — Seedream은 text-to-image 출력만 신뢰 자산이 되므로
 //   이미지를 레퍼런스로 넣으면 결과가 신뢰 밖으로 나가 Seedance 레퍼런스로 못 쓰게 된다.
 const baseName = String(d.name || '').trim();
 const nextVersionName = (nm) => {
 if (!nm) return nm;
 const m = nm.match(/^(.*)_v(\d{3})$/);
 if (m) return `${m[1]}_v${String(Math.min(999, parseInt(m[2], 10) + 1)).padStart(3, '0')}`;
 return `${nm}_v002`;
 };
 const genName = isFeedback ? nextVersionName(baseName) : baseName;
 const basePrompt = buildCharacterPrompt({ ...d, name: genName });
 const prompt = isFeedback
 ? `${basePrompt}\n\n[REVISION — apply this change while keeping everything else identical]\n${feedbackText.trim()}`
 : basePrompt;

 const jobNum = d.numOutputs;
 characterJobSeq.current += 1;
 const jobId = `ch_${Date.now()}_${characterJobSeq.current}`;
 const params = {
 name: genName, gender: d.gender, age: String(d.age || '').trim(),
 height: String(d.height || '').trim(), features: d.features.trim(),
 numOutputs: jobNum, feedback: feedbackText.trim() || null,
 voice: d.voice || null, // v773: 보이스는 이미지 생성에는 영향 없고, 캐릭터 저장 시 함께 보관된다
 };
 // v767: 비차단 생성 — 입력을 잠그지 않고 생성기록에 로딩 항목만 추가 (다른 작업과 동일)
 up(p => ({ ...p, error: '', feedback: '', feedbackOpen: false,
 generations: [{ id: jobId, loading: true, params, ts: Date.now(), estSec: estSecFor(durKeyArkImage(ARK_MODELS.image, CHARACTER_SHEET_SIZE, jobNum), estImageGenSeconds('medium', jobNum)) }, ...p.generations] }));

 try {
 const raw = await callArkImage(prompt, { size: CHARACTER_SHEET_SIZE, model: ARK_MODELS.image, numOutputs: jobNum });
 const urls = (raw || []).map(x => (x && typeof x === 'object' && x.url) ? x.url : x).filter(Boolean);
 if (!urls.length) throw new Error('생성 결과가 비어있습니다.');
 // v976: 앱 데이터 폴더에 받아 둔다
 const chKept = await genKeepAll('character', urls.map((u, i) => ({ id: `${jobId}_${i}`, url: u })));
 const keptUrls = chKept.map(x => x.url).filter(Boolean);
 const keptFiles = chKept.map(x => x.file || '');
 setCharacterWsData(p => ({
 ...p,
 generations: p.generations.map(g => g.id === jobId ? { id: jobId, urls: keptUrls, files: keptFiles, srcUrls: urls, params, ts: g.ts } : g),
 selectedUrl: p.selectedUrl || keptUrls[0],
 }));
 } catch (e) {
 setCharacterWsData(p => ({
 ...p, error: `캐릭터 생성 실패: ${e.message}`,
 generations: p.generations.map(g => g.id === jobId ? { ...g, loading: false, error: e.message } : g),
 }));
 }
 };

 // v759: 생성된 캐릭터를 라이브러리에 저장 — 추후 Seedance 레퍼런스로 사용.
 //   ModelArk 결과 URL은 24시간만 유효하므로 썸네일을 base64로 즉시 내려받아 보관한다.
 const handleSaveCharacter = async (url, params) => {
 const up = (patch) => setCharacterWsData(p => typeof patch === 'function' ? patch(p) : ({ ...p, ...patch }));
 if (!url) return;
 const nameRaw = (params?.name || '').trim();
 if (!nameRaw) { up({ error: '캐릭터를 저장하려면 이름을 입력해주세요.' }); return; }
 // v767: 동명 캐릭터가 있으면 '기존 갱신' / '이름 변경 후 저장' 중 선택
 const exists = characterLibrary.some(c => c.name === nameRaw && !c.deletedAt);
 let saveName = nameRaw;
 if (exists) {
 const choice = await new Promise((resolve) => {
 setCharacterSaveChoice({
 name: nameRaw,
 onUpdate: () => { setCharacterSaveChoice(null); resolve('update'); },
 onRename: (nm) => { setCharacterSaveChoice(null); resolve({ rename: nm }); },
 onCancel: () => { setCharacterSaveChoice(null); resolve(null); },
 });
 });
 if (!choice) return;
 if (choice !== 'update') saveName = choice.rename;
 } else {
 const ok = await new Promise((resolve) => {
 setConfirmDialog({
 title: '캐릭터 저장',
 message: `"${nameRaw}"\n\n아카이브 > 캐릭터에 저장됩니다. 이후 영상 작업의 레퍼런스로 사용할 수 있어요.`,
 confirmLabel: '저장',
 onConfirm: () => { setConfirmDialog(null); resolve(true); },
 onCancel: () => { setConfirmDialog(null); resolve(false); },
 });
 });
 if (!ok) return;
 }
 try {
 // 원본 URL이 만료되기 전에 썸네일 확보 (라이브러리 목록 표시용)
 const thumb = await imageUrlToRef(url, 'character').catch(() => null);
 // v974: 원본 바이트는 userData 파일로. 실패하면 base64 를 그대로 담는다.
 const charId = `char_${Date.now()}_${Math.round(performance.now())}`;
 const thumbFile = await characterStoreBytes(charId, thumb?.base64, thumb?.mimeType);
 const entry = {
 id: charId,
 name: saveName,
 gender: params?.gender || 'male',
 age: params?.age || '',
 height: params?.height || '',
 features: params?.features || '',
 url, // 원본(24시간) — 만료 후에는 보관한 원본 파일로 대체
 thumbFile: thumbFile || null,
 thumbBase64: thumbFile ? null : (thumb?.base64 || null),
 thumbMime: thumb?.mimeType || null,
 // v773: 보이스 레퍼런스 — 영상 생성 시 Seedance 2.0 reference_audio로 함께 전달된다
 voice: params?.voice || null,
 savedAt: Date.now(),
 };
 // 같은 이름이 이미 있으면 최신으로 교체
 const next = [entry, ...characterLibrary.filter(c => c.name !== saveName)];
 persistCharacterLibrary(next);
 up({ error: '' });
 sendSystemNotification('캐릭터 저장 완료', `${saveName} — 아카이브 > 캐릭터에서 확인할 수 있습니다.`);
 } catch (e) {
 up({ error: `캐릭터 저장 실패: ${e.message}` });
 }
 };

 // v764: 캐릭터 삭제는 휴지통으로 (deletedAt 소프트 삭제) — 복원·영구삭제 지원
 const handleTrashCharacter = (id) => {
 persistCharacterLibrary(characterLibrary.map(c => c.id === id ? { ...c, deletedAt: Date.now() } : c));
 };
 const handleRestoreCharacter = (id) => {
 persistCharacterLibrary(characterLibrary.map(c => {
 if (c.id !== id) return c;
 const { deletedAt, ...rest } = c;
 return rest;
 }));
 };
 const handlePurgeCharacter = (id) => {
 const c = characterLibrary.find(x => x.id === id);
 setConfirmDialog({
 title: '캐릭터 영구 삭제',
 message: `"${c?.name || '캐릭터'}"를 영구적으로 삭제할까요?\n삭제하면 되돌릴 수 없습니다.`,
 confirmLabel: '영구 삭제', danger: true,
 onConfirm: () => {
 // v974: 보관해 둔 원본 파일도 같이 지운다 — 안 지우면 디스크에 남는다
 if (c?.thumbFile) {
 window.electronAPI?.assetDelete?.({ path: c.thumbFile })
 ?.catch?.(() => { /* 파일이 없으면 그만 */ });
 }
 persistCharacterLibrary(characterLibrary.filter(x => x.id !== id));
 setConfirmDialog(null);
 setCharacterPreview(null);
 },
 });
 };
 // 캐릭터 이름 변경 — 같은 이름이 이미 있으면 거부
 const handleRenameCharacter = (id, nextName) => {
 const nm = sanitizeNameInput(nextName || '').trim();
 if (!nm) return { ok: false, msg: '이름을 입력해주세요.' };
 if (characterLibrary.some(c => c.id !== id && c.name === nm && !c.deletedAt)) {
 return { ok: false, msg: '같은 이름의 캐릭터가 이미 있습니다.' };
 }
 persistCharacterLibrary(characterLibrary.map(c => c.id === id ? { ...c, name: nm } : c));
 setCharacterPreview(p => (p && p.id === id ? { ...p, name: nm } : p));
 return { ok: true };
 };

 const handleGenerateCustomImage = async (feedbackText = '') => {
 const d = customImageData;
 const basePrompt = d.prompt.trim();
 const isFeedback = !!feedbackText.trim();
 // 피드백 재생성은 피드백 텍스트만으로 진행(이전 이미지가 레퍼런스). 일반 생성은 프롬프트 필요.
 if (!isFeedback && !basePrompt) {
 setCustomImageData(p => ({ ...p, error: '프롬프트를 먼저 입력해주세요.' }));
 return;
 }

 // 비율 → size 문자열 (실제 픽셀 크기는 해상도 등급과 함께 falImageSize가 결정)
 const size = customAspectToSize(d.aspect);
 if (!size) {
 setCustomImageData(p => ({ ...p, error: '사용자설정 비율을 "가로:세로" 형식으로 입력해주세요. (예: 21:9, 4:5)' }));
 return;
 }
 const aspectLabel = d.aspect;

 // 피드백 재생성이면 '피드백 텍스트'만 프롬프트로 사용(기존 프롬프트 미포함). 일반 생성이면 프롬프트 사용.
 const activeText = isFeedback ? feedbackText.trim() : basePrompt;
 // v838: 프롬프트 조립을 함수로 뽑았다 — 다듬은 뒤(아래 try 안)에 다시 조립해야 하기 때문.
 //   @이름 → "이름" 치환은 반드시 다듬기 다음이어야 한다. 먼저 치환하면 @토큰이 사라져
 //   polishGenPrompt 의 토큰 보존 검증이 무의미해진다.
 const assembleImgPrompt = (text) => {
 // @레퍼런스이름 매칭 — 텍스트의 @이름을 참조 이미지와 연결하고, 매핑 정보를 프롬프트에 첨부
 let promptWithRefs = text;
 if (d.refImages.length > 0) {
 const mappingLines = d.refImages.map((r, i) => {
 const nm = (r.refName || `Image${String(i + 1).padStart(2, '0')}`).trim();
 if (nm && promptWithRefs.includes(`@${nm}`)) {
 promptWithRefs = promptWithRefs.split(`@${nm}`).join(`"${nm}"`);
 }
 return `- ${i + 1}번째 참조 이미지 = "${nm}"`;
 });
 promptWithRefs += `\n\n[참조 이미지 매핑 — 프롬프트에서 "이름"으로 지칭된 이미지는 해당 참조 이미지를 사용]\n${mappingLines.join('\n')}`;
 }
 // 피드백: 이전 이미지가 레퍼런스로 첨부되며, 피드백 텍스트가 곧 수정 지시(기존 프롬프트는 섞지 않음)
 return isFeedback
 ? `Reference image attached: the previously generated image. Keep the same overall composition, subject, and style. Apply ONLY the change described here:\n\n${promptWithRefs}`
 : promptWithRefs;
 };
 // v582: 파라미터 스냅샷 (생성기록 클릭 시 '적용된 설정' 표시용)
 const params = { prompt: isFeedback ? (basePrompt || '(피드백 재생성)') : basePrompt, aspect: aspectLabel, quality: d.quality, numOutputs: d.numOutputs, refImages: d.refImages.map(r => ({ refName: r.refName, base64: r.base64, mimeType: r.mimeType })), feedback: feedbackText.trim() || null };
 const jobRefs = d.refImages;
 const jobFeedbackUrl = feedbackText.trim() ? d.selectedUrl : null; // v584: 피드백 시 선택 이미지를 레퍼런스로
 const jobQuality = d.quality;
 const jobTier = d.resolution || '1080p'; // v753: 워크스페이스에서 고른 해상도 등급
 const jobNum = d.numOutputs;
 customImgJobSeq.current += 1;
 const genId = `cg_${Date.now()}_${customImgJobSeq.current}`;
 const genVersion = customImgJobSeq.current; // v703: 생성 순번 = 파일명 버전
 // v582: 로딩 플레이스홀더를 생성기록에 추가 (미리보기는 잠기지 않음 → 즉시 다른 생성 가능)
 setCustomImageData(p => ({ ...p, error: '', feedback: '', generations: [{ id: genId, version: genVersion, loading: true, count: jobNum, params, ts: Date.now(), estSec: estSecFor(durKeyImage(imageModel, d.quality, jobNum), estImageGenSeconds(d.quality, jobNum)) }, ...p.generations] }));
 try {
 let urls;
 if (SAMPLE_MODE) {
 await new Promise(r => setTimeout(r, 1600));
 const [aw, ah] = size.split('x').map(Number);
 const scale = 640 / Math.max(aw, ah);
 const w = Math.round(aw * scale); const h = Math.round(ah * scale);
 urls = Array.from({ length: jobNum }, (_, i) => {
 const hue = (Date.now() / 100 + i * 47) % 360;
 const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${w}' height='${h}'><rect width='100%' height='100%' fill='hsl(${hue},42%,86%)'/><rect x='4%' y='4%' width='92%' height='92%' fill='none' stroke='hsl(${hue},45%,55%)' stroke-width='3' stroke-dasharray='14 10' rx='16'/><text x='50%' y='47%' font-size='${Math.round(w / 9)}' text-anchor='middle' fill='hsl(${hue},45%,32%)' font-family='sans-serif' font-weight='bold'>SAMPLE</text><text x='50%' y='58%' font-size='${Math.round(w / 18)}' text-anchor='middle' fill='hsl(${hue},35%,42%)' font-family='sans-serif'>${aspectLabel} · ${jobQuality === 'high' ? '고품질' : jobQuality === 'medium' ? '표준' : '경량'} · #${i + 1}</text></svg>`;
 return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
 });
 } else {
 // v584: 피드백 재생성 시 이전 이미지를 레퍼런스 맨 앞에 첨부
 let refsForGen = jobRefs;
 if (jobFeedbackUrl) {
 try {
 const res = await fetch(jobFeedbackUrl); const blob = await res.blob();
 const dataUrl = await new Promise((rs2, rj) => { const rd = new FileReader(); rd.onload = () => rs2(rd.result); rd.onerror = rj; rd.readAsDataURL(blob); });
 const m = /^data:([^;]+);base64,(.+)$/.exec(dataUrl);
 if (m) refsForGen = [{ name: '이전_이미지', base64: m[2], mimeType: m[1] }, ...jobRefs];
 } catch {}
 }
 // v838: 사용자 프롬프트를 모델이 알아듣기 쉽게만 다듬는다(의도 불변, 결과는 비노출).
 //   로딩 카드가 이미 떠 있는 시점이라 몇 초 지연이 '먹통'처럼 보이지 않는다.
 //   피드백 재생성은 대상이 '수정 지시'라서 건드리지 않는다.
 const polished = isFeedback ? activeText : await polishGenPrompt(activeText, { model: adaptModel, workCat: 'image' });
 const finalPrompt = assembleImgPrompt(polished);
 const raw = await callFalImage(finalPrompt, size, jobQuality, refsForGen, jobNum, undefined, undefined, jobTier);
 // callFalImage는 [{url}] 객체 배열 반환 → URL 문자열로 정규화
 urls = (raw || []).map(x => (x && typeof x === 'object' && x.url) ? x.url : x).filter(Boolean);
 try { recordCreditUsage(estimateImageCost(imageModel, jobQuality, urls.length, falImageSize(size, jobTier)), 'image', { workCat: 'image' }); } catch {}
 }
 // 로딩 플레이스홀더를 결과로 교체
 // v976: 앱 데이터 폴더에 받아 둔다 — 다시 켰을 때 생성 내역이 남는다
 const ciKept = await genKeepAll('image', urls.map((u, i) => ({ id: `${genId}_${i}`, url: u })));
 const ciUrls = ciKept.map(x => x.url).filter(Boolean);
 const ciFiles = ciKept.map(x => x.file || '');
 setCustomImageData(p => ({ ...p, generations: p.generations.map(g => g.id === genId
 ? { id: genId, version: genVersion, urls: ciUrls, files: ciFiles, srcUrls: urls, params, ts: Date.now() }
 : g), selectedUrl: p.selectedUrl || ciUrls[0] }));
 // v741: 완료 알람은 중앙(progressItems 상태 전이)에서 발송 — 중복 제거
 } catch (e) {
 // 실패한 플레이스홀더 제거 + 오류 표시
 setCustomImageData(p => ({ ...p, error: `생성 실패: ${e.message}`, generations: p.generations.filter(g => g.id !== genId) }));
 }
 };

 // 커스텀 이미지 레퍼런스 업로드 (최대 10장) — 이름 미설정 시 Image01, Image02... 자동 부여
 const handleCustomRefUpload = (files) => {
 const list = Array.from(files || []).filter(f => f.type.startsWith('image/'));
 if (!list.length) return;
 list.slice(0, 10).forEach((file) => {
 const reader = new FileReader();
 reader.onload = () => {
 const base64 = String(reader.result).split(',')[1];
 setCustomImageData(p => {
 if (p.refImages.length >= 10) return p;
 // 기존 ImageNN 중 최댓값 + 1 (삭제 후에도 중복 없이)
 const maxN = p.refImages.reduce((mx, r) => {
 const m = String(r.refName || '').match(/^Image(\d+)$/);
 return m ? Math.max(mx, parseInt(m[1])) : mx;
 }, 0);
 const refName = `Image${String(maxN + 1).padStart(2, '0')}`;
 return { ...p, refImages: [...p.refImages, { refName, fileName: file.name, base64, mimeType: file.type }] };
 });
 };
 reader.readAsDataURL(file);
 });
 };

 // 생성 이미지 다운로드 — will-download 훅을 타고 다운로드 폴더 + 아카이브(image)로
 // 파일명: [사용자이름_mmdd_imageNN].png · 인앱 확인 팝업 후 저장
 const handleDownloadCustomImage = async (url) => {
 // v852: 생성 당시 프롬프트로 이름을 만든다 — 프롬프트를 바꿔 다시 생성하면
 //   현재 화면 값과 어긋나고, 입력을 비웠으면 '무제'가 된다.
 const _g = (customImageData?.generations || []).find(g => (g.urls || []).includes(url));
 const kw = await ffsKeyword(_g?.params?.prompt ?? customImageData?.prompt);
 const fileName = (await ffsBuildName({ type: '커스텀', parts: [kw], version: _g?.version })) + '.png';
 setConfirmDialog({
 title: '이미지 저장',
 message: `"${fileName}"\n\n다운로드 폴더에 저장되고, 아카이브(이미지)에도 보관됩니다.`,
 confirmLabel: '저장',
 onConfirm: async () => {
 setConfirmDialog(null);
 try {
 const res = await fetch(url);
 const blob = await res.blob();
 const objUrl = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = objUrl;
 a.download = fileName;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(objUrl);
 try { showToast('이미지를 저장했습니다.', 'load'); } catch {}
 } catch (err) {
 setCustomImageData(p => ({ ...p, error: `다운로드 실패: ${err.message}` }));
 }
 },
 });
 };

 // v580: 타이틀 컨셉 레퍼런스 업로드 (최대 6장)
 const handleTitleConceptRefUpload = (files) => {
 const list = Array.from(files || []).filter(f => f.type.startsWith('image/'));
 if (!list.length) return;
 list.slice(0, 6).forEach((file) => {
 const reader = new FileReader();
 reader.onload = () => {
 const base64 = String(reader.result).split(',')[1];
 setTitleDesignData(p => {
 if ((p.conceptRefs || []).length >= 6) return p;
 return { ...p, conceptRefs: [...(p.conceptRefs || []), { name: file.name, base64, mimeType: file.type }] };
 });
 };
 reader.readAsDataURL(file);
 });
 };

 // v580: 타이틀 이미지 다운로드 — 원본(검정배경) 또는 투명 PNG · 인앱 확인 팝업
 const handleDownloadTitleImage = async (url, transparent) => {
 // v852: 생성 당시 타이틀로 이름을 만든다 — 항목이 title 을 그대로 들고 있다.
 //   현재 입력값을 쓰면 제목을 바꾼 뒤 예전 버전을 저장할 때 이름이 어긋난다.
 const _h = (titleDesignData?.history || []).find(h => (h.images || []).some(im => im.url === url));
 const fileName = (await ffsBuildName({ type: '타이틀', parts: [_h?.title || titleDesignData?.title || '무제', ...(transparent ? ['투명'] : [])], version: _h?.version })) + '.png';
 setConfirmDialog({
 title: transparent ? '투명 배경 PNG 저장' : '이미지 저장',
 message: `"${fileName}"\n\n${transparent ? '검정 배경을 제거해 타이틀만 남긴 투명 PNG로 저장합니다.\n' : ''}다운로드 폴더에 저장되고, 아카이브(이미지)에도 보관됩니다.`,
 confirmLabel: '저장',
 onConfirm: async () => {
 setConfirmDialog(null);
 try {
 let href;
 if (transparent) {
 href = await extractCleanTitleDataUrl(url);
 } else {
 const res = await fetch(url);
 const blob = await res.blob();
 href = URL.createObjectURL(blob);
 }
 const a = document.createElement('a');
 a.href = href;
 a.download = fileName;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 if (!transparent) URL.revokeObjectURL(href);
 try { showToast('이미지를 저장했습니다.', 'load'); } catch {}
 } catch (err) {
 setTitleDesignData(p => ({ ...p, error: `다운로드 실패: ${err.message}` }));
 }
 },
 });
 };

