 const [translateSourceLangOpen, setTranslateSourceLangOpen] = useState(false);
 const [translateTargetLangOpen, setTranslateTargetLangOpen] = useState(false);
 const copyPromptText = async (text, key) => {
 if (!text) return;
 try {
 await navigator.clipboard.writeText(text);
 setPromptCopiedKey(key);
 setTimeout(() => setPromptCopiedKey(prev => prev === key ? null : prev), 1500);
 } catch (e) {
 console.warn('클립보드 복사 실패:', e.message);
 // fallback: textarea로 복사
 try {
 const ta = document.createElement('textarea');
 ta.value = text;
 document.body.appendChild(ta);
 ta.select();
 document.execCommand('copy');
 document.body.removeChild(ta);
 setPromptCopiedKey(key);
 setTimeout(() => setPromptCopiedKey(prev => prev === key ? null : prev), 1500);
 } catch (e2) {
 showNotice('복사 실패', '클립보드 복사에 실패했습니다. 텍스트를 직접 선택해서 복사해주세요.');
 }
 }
 };
