 useEffect(() => {
 setCharPreviewView({ scale: 1, tx: 0, ty: 0 });
 setCharVoicePickOpen(false);
 setCharVoiceError('');
 setCharRenameDraft(null);
 setCharRenameError('');
 }, [characterPreview?.id]);


