 const isFeedback = !!feedbackText.trim();
 const actorList = (d.actors || []).filter(a => a.photo || (a.name && a.name.trim())).map((a, i) => ({ name: (a.name && a.name.trim()) ? a.name.trim() : `주연${i + 1}`, photo: a.photo }));
