 // 재개 가능 작업 (앱 시작 시 또는 새로고침 후 자동 감지)
 const [availableResumes, setAvailableResumes] = useState({});
 const [showResumeBanner, setShowResumeBanner] = useState(false);

 // online/offline 이벤트 리스너
 useEffect(() => {
 const handleOnline = () => {
 setNetworkToast({ type: 'online', timestamp: Date.now() });
 setTimeout(() => setNetworkToast((t) => t?.type === 'online' ? null : t), 4000);
 };
 const handleOffline = () => {
 setNetworkToast({ type: 'offline', timestamp: Date.now() });
 // 오프라인 토스트는 자동 사라지지 않음 (복구 시 사라짐)
 };
 window.addEventListener('online', handleOnline);
 window.addEventListener('offline', handleOffline);
 return () => {
 window.removeEventListener('online', handleOnline);
 window.removeEventListener('offline', handleOffline);
 };
 }, []);

 // 앱 시작 시 재개 가능 작업 확인
