 // v618: 페이지(body/html) 스크롤 잠금 — 단일작업 화면 또는 설정 모달일 때만.
 // 두 조건을 한 곳에서 '최종 상태'로 계산해 매번 덮어씀 → 잠금 겹침 시 복원 순서가 꼬여
 //  overflow:hidden 이 남던 leak(메인화면 스크롤 불가) 근본 차단.
 useEffect(() => {
 const de = document.documentElement;
 const lock = (appScreen === 'single') || showSettings;
 if (lock) {
 document.body.style.overflow = 'hidden';
 de.style.overflow = 'hidden';
 de.style.scrollbarGutter = 'auto';
 } else {
 document.body.style.overflow = '';
 de.style.overflow = '';
 de.style.scrollbarGutter = '';
 }
 }, [appScreen, showSettings]);

 // 선택된 타이틀 버전이 바뀌면 검은 배경 제거된 미리보기용 dataURL 캐싱
 // 미리보기에서 그림자가 정확히 글자 모양으로 보이도록
 useEffect(() => {
 const sel = posterComposeData.selectedTitleVersion;
 if (!sel) return;
 if (cleanedTitleCache[sel]) return; // 이미 캐시됨
 const entry = (titleDesignData.history || []).find(h => h.version === sel);
 if (!entry || !imgUrlOf(entry.images?.[0])) return;
 let cancelled = false;
 extractCleanTitleDataUrl(imgUrlOf(entry.images[0]))
 .then(dataUrl => {
 if (!cancelled) setCleanedTitleCache(prev => ({ ...prev, [sel]: dataUrl }));
 })
 .catch(err => console.warn('타이틀 알파 추출 실패:', err));
 return () => { cancelled = true; };
 }, [posterComposeData.selectedTitleVersion, titleDesignData.history]);
