 // ─── 공용 설정 ───
 // API 키는 localStorage에 영구 저장 — 앱 업데이트 후에도 유지됨
 // .trim()으로 복사 시 따라오는 공백/줄바꿈 제거
 // v582: 빌드 내장 키 폴백 — 배포 빌드는 .env.local의 VITE_* 값이 번들에 주입됨.
 // 우선순위: 사용자가 앱에서 입력한 localStorage 값 > 빌드에 내장된 env 값
 const ENV_KEYS = (typeof import.meta !== 'undefined' && import.meta.env) ? import.meta.env : {};
 const bakedKey = (lsKey, envKey) => {
 try { return sanitizeApiKey(localStorage.getItem(lsKey) || ENV_KEYS[envKey] || ''); } catch { return sanitizeApiKey(ENV_KEYS[envKey] || ''); }
 };
 const [claudeApiKey, setClaudeApiKey] = useState(() => bakedKey('oxyzn_claude_api_key', 'VITE_CLAUDE_API_KEY'));
 // fal.ai API 키 — 이미지(GPT Image 2) · BGM · TTS · 보이스 클로닝 · 영상 업스케일(Topaz)용.
 //   v746 에는 영상 생성도 여기였지만 v763 에 ModelArk 직결로 옮겨갔다.
 const [falApiKey, setFalApiKey] = useState(() => {
 const v = bakedKey('oxyzn_fal_api_key', 'VITE_FAL_API_KEY');
 if (typeof window !== 'undefined' && v) window.__OXYZN_FAL_API_KEY__ = v;
 return v;
 });
 // v756: BytePlus ModelArk API 키 (Seedance 2.0 / Seedream 5.0 직접 연동)
 const [arkApiKey, setArkApiKey] = useState(() => {
 const v = bakedKey('oxyzn_ark_api_key', 'VITE_ARK_API_KEY');
 if (typeof window !== 'undefined' && v) window.__OXYZN_ARK_API_KEY__ = v;
 return v;
 });
 // ModelArk 연결 테스트 상태 — { state: 'idle'|'testing'|'ok'|'fail', msg }
 const [arkTest, setArkTest] = useState({ state: 'idle', msg: '' });
 // v832: BytePlus Access Key (AK/SK) — Assets API 전용.
 //   위의 arkApiKey(Bearer)로는 Assets API 를 호출할 수 없다. 문서 명시:
 //   "To call the Assets API interface, you must use Access Key authentication."
 //   발급: 콘솔 → 계정명 → IAM → Key management → Create access key
 //   해당 계정은 프로젝트에 ArkFullAccess 권한이 있어야 한다.
 const [arkAccessKeyId, setArkAccessKeyId] = useState(() => {
 const v = bakedKey('oxyzn_ark_access_key_id', 'VITE_ARK_ACCESS_KEY_ID');
 if (typeof window !== 'undefined' && v) window.__OXYZN_ARK_AK__ = v;
 return v;
 });
 const [arkSecretKey, setArkSecretKey] = useState(() => {
 const v = bakedKey('oxyzn_ark_secret_key', 'VITE_ARK_SECRET_KEY');
 if (typeof window !== 'undefined' && v) window.__OXYZN_ARK_SK__ = v;
 return v;
 });
