 // 완료된 영상 목록 반환 (선택된 컷 우선, 없으면 전체)
 // 반환: [{ cut, ep, idx, url, version }]
 const getDownloadableVideos = (onlySelected = false) => {
 const result = [];
 for (const ep of episodes) {
 for (let idx = 0; idx < ep.cuts.length; idx++) {
 const cut = ep.cuts[idx];
 if (onlySelected && !selectedCuts[cut.id]) continue;
 const job = videoJobs[cut.id];
 if (!job) continue;
 const history = job.history || [];
 const selectedVer = job.selectedVersion || job.version;
 const selectedEntry = history.find(h => h.version === selectedVer) || history[history.length - 1];
 const url = selectedEntry?.url || job.url;
 if (!url) continue;
 result.push({ cut, ep, idx, url, version: selectedVer });
 }
 }
 return result;
 };

 // 완료된 영상 N개 일괄 다운로드 (브라우저가 순차 다운로드)


 const copyToClipboard = async (text) => {
 if (!text) return false;
 // 1차: 최신 Clipboard API
 try {
 if (navigator.clipboard && window.isSecureContext !== false) {
 await navigator.clipboard.writeText(text);
 return true;
 }
 } catch (e) {
 console.warn('Clipboard API 실패, 폴백 시도:', e);
 }
 // 2차: 임시 textarea + execCommand 폴백 (iframe sandbox 등)
 try {
 const ta = document.createElement('textarea');
 ta.value = text;
 ta.setAttribute('readonly', '');
 ta.style.position = 'fixed';
 ta.style.top = '0';
 ta.style.left = '0';
 ta.style.opacity = '0';
 ta.style.pointerEvents = 'none';
 document.body.appendChild(ta);
 ta.select();
 ta.setSelectionRange(0, text.length);
 const ok = document.execCommand('copy');
 document.body.removeChild(ta);
 return ok;
 } catch (e) {
 console.error('execCommand 폴백도 실패:', e);
 return false;
 }
 };




 const totalCuts = episodes.reduce((sum, ep) => sum + ep.cuts.length, 0);

 // 시간 포맷: 초 → "약 2분 30초" 또는 "약 45초"
 const formatDuration = (seconds) => {
 if (!seconds || seconds < 0) return '계산 중';
 const s = Math.round(seconds);
 if (s < 60) return `약 ${s}초`;
 const m = Math.floor(s / 60);
 const rem = s % 60;
 if (rem === 0) return `약 ${m}분`;
 return `약 ${m}분 ${rem}초`;
 };

 // ── 안전한 백분율 계산 (모든 진행률 표시에 사용) ──
 // 음수·NaN·Infinity·null/undefined를 모두 막아 비정상 % 표시 방지
 // (시계 변동, 일시정지, 데이터 누락 등 어떤 케이스에서도 0~99 범위로 클램프)
 const safePct = (numerator, denominator, max = 99) => {
 const n = Number(numerator);
 const d = Number(denominator);
 if (!isFinite(n) || !isFinite(d) || d <= 0 || n < 0) return 0;
 const raw = (n / d) * 100;
 if (!isFinite(raw)) return 0;
 return Math.min(max, Math.max(0, Math.round(raw)));
 };

 // ── 공통 진행 시간 계산 (각색 / 시나리오 공용) ──
 const getBatchProgressInfo = (progressData, defaultSec = 35) => {
 if (!progressData?.startTime) return null;
 const { batch, totalBatches, startTime, estimatedSecPerBatch = defaultSec } = progressData;
 const currentPausedMs = pausedAtRef.current ? Date.now() - pausedAtRef.current : 0;
 const elapsed = Math.max(0, (Date.now() - startTime - pausedDurationRef.current - currentPausedMs) / 1000);
 const totalEst = estimatedSecPerBatch * totalBatches;
 const percent = safePct(batch, totalBatches, 100);
 let remaining;
 if (batch >= 2 && elapsed > 0) {
 const avg = elapsed / batch;
 const clipped = Math.min(Math.max(avg, estimatedSecPerBatch * 0.3), estimatedSecPerBatch * 3);
 remaining = clipped * (totalBatches - batch);
 } else {
 remaining = Math.max(0, totalEst - elapsed);
 }
 return { batch, totalBatches, percent, totalEstimated: formatDuration(totalEst), remaining: formatDuration(Math.max(0, remaining)), elapsed: formatDuration(elapsed) };
 };

