 // 슬롯에서 불러오기
 const handleLoadSlot = (slot, toolKey = 'scenario') => {
 try {
 if (toolKey === 'poster') {
 setPosterToolData((prev) => ({ ...prev, ...slot.data, isGeneratingPrompt: false, isGeneratingImage: false, error: '' }));
 } else if (toolKey === 'translate') {
 // v369: 번역 불러오기 — 진행 중 상태는 초기화
 setTranslateToolData((prev) => ({ ...prev, ...slot.data, isProcessing: false, progress: '', error: '' }));
 } else if (toolKey === 'tts') {
 setTtsToolData((prev) => ({ ...prev, ...slot.data, isGenerating: false, progress: '', error: '' }));
 } else if (toolKey === 'music') {
 setMusicToolData((prev) => ({ ...prev, ...slot.data, isGeneratingPrompt: false, isGeneratingMusic: false, progress: '', error: '' }));
 } else if (toolKey === 'sheet') {
 setSheetToolData((prev) => ({ ...prev, ...slot.data, isProcessing: false, progress: '', error: '' }));
 } else if (toolKey === 'adapt') {
 setAdaptToolData((prev) => ({ ...prev, ...slot.data, isProcessing: false, progress: null, error: '' }));
 } else if (toolKey === 'scenarioAnalyze') {
 setScenarioAnalyzeData((prev) => ({ ...prev, ...slot.data, isAnalyzing: false, progress: '', error: '' }));
 } else if (toolKey === 'videoAnalyze') {
 setVideoAnalyzeData((prev) => ({ ...prev, ...slot.data, isAnalyzing: false, progress: '', error: '' }));
 } else {
 setScenarioToolData((prev) => ({ ...prev, ...slot.data, isProcessing: false, progress: null, treatmentProgress: null, isGeneratingTreatment: false }));
 }
 setShowSaveList(false);
 showToast(`"${slot.name}" 불러오기 완료`, 'load');
 } catch { showToast('불러오기 실패', 'error'); }
 };

