 // 이미지 base64를 캔버스로 압축 (최대 1024px, JPEG 80%)
 // Replicate JSON 페이로드 크기 줄이기 위함 — 인물 식별엔 1024px이면 충분
 // 이미지 모델별 예상 단가 (Replicate 기준, USD)

 // 영상 모델별 예상 단가 (Replicate 기준, USD per second)
 // Seedance 2.0: video_in (image 입력 있음) vs non_video_in (텍스트만)
 // Kling 3.0: mode별 + 오디오 여부에 따라 단가가 달라짐
 const getVideoCostPerSec = (model, resolution, hasImageInput, hasAudio = false) => {
 if (model.includes('seedance')) {
 const res = (resolution || '1080p').toLowerCase();
 if (hasImageInput) {
 if (res === '480p') return 0.10;
 if (res === '720p') return 0.22;
 if (res === '1080p') return 0.55;
 } else {
 if (res === '480p') return 0.08;
 if (res === '720p') return 0.18;
 if (res === '1080p') return 0.45;
 }
 return 0.55;
 }
 if (model.includes('kling')) {
 const res = (resolution || '1080p').toLowerCase();
 // standard = 720p, pro = 1080p, 4k = 4K
 if (res === '720p') return hasAudio ? 0.252 : 0.168; // standard
 if (res === '1080p') return hasAudio ? 0.336 : 0.224; // pro
 if (res === '4k') return 0.42; // 4k (오디오 유무 동일)
 return hasAudio ? 0.336 : 0.224;
 }
 return null;
 };

 const compressBase64Image = async (base64, mimeType, maxSize = 1024, quality = 0.82) => {
 return new Promise((resolve) => {
 try {
 const img = new globalThis.Image();
 img.onload = () => {
 let w = img.naturalWidth, h = img.naturalHeight;
 if (w <= maxSize && h <= maxSize) {
 resolve({ base64, mimeType }); // 이미 작음 — 그대로
 return;
 }
 if (w > h) { h = Math.round(h * maxSize / w); w = maxSize; }
 else { w = Math.round(w * maxSize / h); h = maxSize; }
 const canvas = document.createElement('canvas');
 canvas.width = w; canvas.height = h;
 const ctx = canvas.getContext('2d');
 ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h);
 ctx.drawImage(img, 0, 0, w, h);
 const newDataUri = canvas.toDataURL('image/jpeg', quality);
 const newBase64 = newDataUri.split(',')[1];
 resolve({ base64: newBase64, mimeType: 'image/jpeg' });
 };
 img.onerror = () => resolve({ base64, mimeType });
 img.src = `data:${mimeType};base64,${base64}`;
 } catch {
 resolve({ base64, mimeType });
 }
 });
 };

 // 포스터(배경) + 타이틀 이미지를 합성하는 함수
 // 포스터의 일관된 이미지를 유지하고 타이틀의 디자인을 정확히 보존
 // titleImg는 검정 배경 + 흰색 그래픽 (기본 형태)
 // opts: {
 // position: 'top'|'center'|'bottom', size: 10-200(%),
 // verticalOffset: 0-50(%), horizontalOffset: -50~50(%),
 // blendMode: 'normal'|'screen', color: 'white'|'black',
 // shadow: { enabled, color, opacity (0-100), blur (px), offsetX (px), offsetY (px) }
 // }
 const compositePosterWithTitle = async (posterUrl, titleUrl, opts = {}) => {
 const position = opts.position || 'top';
 const sizePct = Math.max(10, Math.min(200, opts.size ?? 35));
 const vOffset = Math.max(0, Math.min(50, opts.verticalOffset ?? 8));
 const hOffset = Math.max(-50, Math.min(50, opts.horizontalOffset ?? 0));
 const blendMode = opts.blendMode || 'normal';
 const color = opts.color || 'white';
 const shadow = opts.shadow || { enabled: false };

 return new Promise((resolve, reject) => {
 const loadImg = (url) => new Promise((res, rej) => {
 fetch(url, { mode: 'cors' })
 .then(r => r.blob())
 .then(blob => {
 const img = new globalThis.Image();
 const objUrl = URL.createObjectURL(blob);
 img.onload = () => { URL.revokeObjectURL(objUrl); res(img); };
 img.onerror = (e) => { URL.revokeObjectURL(objUrl); rej(e); };
 img.crossOrigin = 'anonymous';
 img.src = objUrl;
 })
 .catch(rej);
 });

 // 타이틀 이미지에서 검정 배경을 제거하고 흰 글자만 알파 채널로 추출
 // 결과: 글자 영역은 흰색, 배경은 완전 투명한 canvas
 // 임계값 — extractCleanTitleDataUrl과 동일한 값 사용 (미리보기/합성 일치)
 const extractTitleAlpha = (img) => {
 const c = document.createElement('canvas');
 c.width = img.naturalWidth;
 c.height = img.naturalHeight;
 const cx = c.getContext('2d');
 cx.drawImage(img, 0, 0);
 const data = cx.getImageData(0, 0, c.width, c.height);
 const d = data.data;
 const TH_LOW = 40;
 const TH_HIGH = 180;
 for (let i = 0; i < d.length; i += 4) {
 const brightness = (d[i] + d[i + 1] + d[i + 2]) / 3;
 let alpha;
 if (brightness <= TH_LOW) alpha = 0;
 else if (brightness >= TH_HIGH) alpha = 255;
 else alpha = Math.round(((brightness - TH_LOW) / (TH_HIGH - TH_LOW)) * 255);
 d[i + 3] = alpha;
 d[i] = 255; d[i + 1] = 255; d[i + 2] = 255;
 }
 cx.putImageData(data, 0, 0);
 return c;
 };

 // 알파 마스크에 색상을 입혀서 그림자 레이어 생성
 const createShadowLayer = (alphaCanvas, color) => {
 const c = document.createElement('canvas');
 c.width = alphaCanvas.width;
 c.height = alphaCanvas.height;
 const cx = c.getContext('2d');
 // 알파 마스크 복사
 cx.drawImage(alphaCanvas, 0, 0);
 // 색상 채우기 (source-in: 기존 알파만 유지)
 cx.globalCompositeOperation = 'source-in';
 cx.fillStyle = color;
 cx.fillRect(0, 0, c.width, c.height);
 return c;
 };

 Promise.all([loadImg(posterUrl), loadImg(titleUrl)])
 .then(([posterImg, titleImg]) => {
 const canvas = document.createElement('canvas');
 canvas.width = posterImg.naturalWidth;
 canvas.height = posterImg.naturalHeight;
 const ctx = canvas.getContext('2d');

 // 1. 포스터 배경 그리기
 ctx.drawImage(posterImg, 0, 0);

 // 2. 타이틀 크기 계산 — 포스터 너비의 sizePct%
 const targetWidth = Math.round(canvas.width * (sizePct / 100));
 const scale = targetWidth / titleImg.naturalWidth;
 const targetHeight = Math.round(titleImg.naturalHeight * scale);

 // 3. 위치 계산
 // x = 중앙 정렬 + 좌우 오프셋 (포스터 너비의 hOffset%)
 const x = Math.round((canvas.width - targetWidth) / 2 + canvas.width * (hOffset / 100));
 let y;
 const vOffsetPx = Math.round(canvas.height * (vOffset / 100));
 if (position === 'top') {
 y = vOffsetPx;
 } else if (position === 'center') {
 y = Math.round((canvas.height - targetHeight) / 2);
 } else { // bottom
 y = canvas.height - targetHeight - vOffsetPx;
 }

 // 4. 그림자 처리 (옵션) — 타이틀 본체보다 먼저 그림
 if (shadow.enabled) {
 // 타이틀에서 알파 채널 추출 (검정 배경 제거)
 const titleAlpha = extractTitleAlpha(titleImg);
 // 그림자 색으로 채우기
 const shadowLayer = createShadowLayer(titleAlpha, shadow.color || '#000000');

 // 그림자를 별도 캔버스에 그려서 blur 적용 (메인 canvas에 blur 영향 안 가도록)
 // blur가 잘리지 않게 여유 공간(padding) 확보
 const padding = Math.max(0, shadow.blur || 0) * 2;
 const sw = targetWidth;
 const sh = targetHeight;
 const shadowCanvas = document.createElement('canvas');
 shadowCanvas.width = sw + padding * 2;
 shadowCanvas.height = sh + padding * 2;
 const sctx = shadowCanvas.getContext('2d');

 // blur 필터 적용
 if (shadow.blur && shadow.blur > 0) {
 sctx.filter = `blur(${shadow.blur}px)`;
 }
 // 그림자 레이어를 padding만큼 안쪽으로 그림
 sctx.drawImage(shadowLayer, padding, padding, sw, sh);
 sctx.filter = 'none';

 // 그림자를 메인 canvas에 합성
 const sx = x + (shadow.offsetX || 0) - padding;
 const sy = y + (shadow.offsetY || 0) - padding;

 ctx.save();
 ctx.globalAlpha = Math.max(0, Math.min(1, (shadow.opacity || 60) / 100));
 ctx.drawImage(shadowCanvas, sx, sy);
 ctx.restore();
 }

 // 5. 타이틀 본체 합성 모드별 처리
 if (blendMode === 'screen') {
 ctx.globalCompositeOperation = 'screen';
 if (color === 'black') {
 const tmp = document.createElement('canvas');
 tmp.width = titleImg.naturalWidth;
 tmp.height = titleImg.naturalHeight;
 const tctx = tmp.getContext('2d');
 tctx.drawImage(titleImg, 0, 0);
 const imageData = tctx.getImageData(0, 0, tmp.width, tmp.height);
 const d = imageData.data;
 for (let i = 0; i < d.length; i += 4) {
 d[i] = 255 - d[i];
 d[i+1] = 255 - d[i+1];
 d[i+2] = 255 - d[i+2];
 }
 tctx.putImageData(imageData, 0, 0);
 ctx.globalCompositeOperation = 'multiply';
 ctx.drawImage(tmp, x, y, targetWidth, targetHeight);
 } else {
 ctx.drawImage(titleImg, x, y, targetWidth, targetHeight);
 }
 } else {
 ctx.globalCompositeOperation = 'source-over';
 ctx.drawImage(titleImg, x, y, targetWidth, targetHeight);
 }

 ctx.globalCompositeOperation = 'source-over'; // 복구
 resolve(canvas.toDataURL('image/png'));
 })
 .catch(reject);
 });
 };

 // 포스터 합성 실행 핸들러

 // ─── Tool 4: 포스터 디자인 핸들러 ───

 // GPT Image 2 API 호출
 // Replicate 이미지 생성 API (polling 방식)
 // v749: 이미지 생성 — fal. 레퍼런스 이미지가 있으면 부분수정(edit) 엔드포인트로 라우팅한다.
 //   fal의 텍스트→이미지 엔드포인트에는 레퍼런스 입력 파라미터가 없으므로 이 분기는 필수다.
 //   시그니처는 기존 callReplicateImage와 동일하게 유지 (호출부 7곳 무변경)
 const callFalImage = async (prompt, size = '1080x1920', quality = 'high', refImages = [], numOutputs = 1, retryCount, modelOverride, tier = '1080p') => {
 const apiKey = falKey();
 const _t0 = Date.now(); // v791: 실측 소요시간
 const ep = falImageEndpoint(modelOverride || imageModel);
 const safeNum = Math.max(1, Math.min(3, Number(numOutputs) || 1));
 const safeQuality = ['auto', 'low', 'medium', 'high'].includes(quality) ? quality : 'high';

 // 레퍼런스 → fal CDN 업로드 (edit 엔드포인트는 URL 배열만 받음)
 const refs = (refImages || []).filter(r => r && r.base64 && r.mimeType);
 const imageUrls = [];
 for (const r of refs) imageUrls.push(await falUploadFile(`data:${r.mimeType};base64,${r.base64}`, apiKey));
 const useEdit = imageUrls.length > 0;
 const endpoint = useEdit ? ep.edit : ep.base;

 // 모델 계열별 입력 구성
 let input;
 if (ep.family === 'nano') {
 input = {
 prompt,
 aspect_ratio: falNanoAspect(size),
 resolution: safeQuality === 'high' ? '4K' : (safeQuality === 'low' ? '1K' : '2K'),
 num_images: safeNum,
 output_format: 'png',
 };
 } else {
 input = {
 prompt,
 quality: safeQuality,
 num_images: safeNum,
 output_format: 'png',
 image_size: falImageSize(size, tier),
 };
 }
 if (useEdit) input.image_urls = imageUrls;

 try {
 console.group(`Image API Call — ${endpoint}`);
 console.log('Prompt:', prompt.slice(0, 200) + (prompt.length > 200 ? '...' : ''));
 console.log('Size:', size, '/ Quality:', safeQuality, '/ 장수:', safeNum);
 console.log('레퍼런스:', imageUrls.length, useEdit ? '→ edit(부분수정) 경로' : '→ 텍스트→이미지 경로');
 console.groupEnd();
 } catch {}

 try {
 const out = await falRun(endpoint, input, {
 apiKey,
 kind: 'image',
 pollMs: 2000,
 maxPolls: 150,
 // 명시 크기가 거부되면 auto로 1회 재시도
 on422: (inp) => (inp.image_size && inp.image_size !== 'auto') ? { ...inp, image_size: 'auto' } : null,
 });
 const arr = Array.isArray(out?.images) ? out.images : [];
 const urls = arr.map(x => (x && typeof x === 'object' ? x.url : x)).filter(Boolean).map(url => ({ url }));
 if (urls.length === 0) throw new Error(`이미지 결과가 비어있습니다: ${JSON.stringify(out).slice(0, 200)}`);
 // v791: 실측 소요시간 기록 (재시도로 되돌아온 경로는 총 소요로 잡히는 게 맞다)
 try { recordJobDuration(durKeyImage(modelOverride || imageModel, safeQuality, safeNum), (Date.now() - _t0) / 1000); } catch {}
 return urls.slice(0, safeNum);
 } catch (e) {
 // 일시적 인프라 오류는 최대 2회 백오프 재시도 (기존 동작 유지)
 const msg = String(e.message || '');
 const isTransient = /upstream connect|connection termination|reset reason|temporarily unavailable|timeout|초과|ECONNRESET|50[234]/i.test(msg);
 if (isTransient && (typeof retryCount === 'undefined' || retryCount < 2)) {
 const next = (typeof retryCount === 'undefined' ? 0 : retryCount) + 1;
 console.warn(`[callFalImage] 일시적 오류 감지, ${next}/2 재시도... (${msg.slice(0, 100)})`);
 await new Promise(r => setTimeout(r, next * 2000 + 1000));
 return callFalImage(prompt, size, safeQuality, refImages, numOutputs, next, modelOverride, tier);
 }
 throw e;
 }
 };

 // v916: 이미 만들어진 태스크를 이어받는다. 폴링이 끊긴 뒤(시간 초과·앱 종료)
 //   결과를 되찾는 유일한 길이다. 새로 만들지 않으므로 비용이 또 나가지 않는다.
 const resumeArkVideoTask = async (taskId, { onStatus, maxPolls = ARK_VIDEO_POLL_MAX } = {}) => {
 const apiKey = arkKey();
 let status = 'queued', last = null;
 for (let i = 0; i < maxPolls; i++) {
 try {
 const pr = await fetch(`${ARK_BASE}/contents/generations/tasks/${taskId}`, {
 headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
 });
 const pt = await pr.text().catch(() => '');
 if (pr.ok) { last = JSON.parse(pt); status = last.status || status; }
 else if (pr.status === 404) throw new Error('그 작업을 찾을 수 없습니다 (만료되었을 수 있습니다).');
 } catch (e) {
 if (/찾을 수 없습니다/.test(e.message)) throw e;
 /* 일시적 오류 — 다음 주기 */
 }
 try { onStatus?.(status, i, taskId); } catch {}
 if (['succeeded', 'failed', 'cancelled', 'expired'].includes(status)) break;
 await new Promise(r => setTimeout(r, ARK_VIDEO_POLL_MS));
 }
 if (status !== 'succeeded') {
 const e = new Error(status === 'failed' || status === 'cancelled' || status === 'expired'
 ? arkErrorMessage(status, JSON.stringify({ error: last?.error }))
 : '아직 만드는 중입니다. 조금 뒤에 다시 눌러주세요.');
 e.pending = !['failed', 'cancelled', 'expired'].includes(status);
 throw e;
 }
 const url = last?.content?.video_url || null;
 if (!url) throw new Error('영상 URL을 받지 못했습니다.');
 return url;
 };

 // v633: Seedance 2.0 영상 생성 (멀티모달 레퍼런스 — 이미지≤9, 비디오≤3·합15초)
 // refs: { images: [dataURI...], videos: [dataURI...] }. 스키마 동적조회로 입력 키 탐색.
 // v746: fal CDN 업로드 — data URL을 공개 URL로 바꾼다.
 //   data URL을 그대로 본문에 넣으면 영상 레퍼런스에서 요청이 수십 MB로 커져 실패하기 쉽다.
 // v756: ModelArk API 키 조회 — 향후 모든 ARK 호출의 단일 진입점
 const arkKey = () => {
 const k = (arkApiKey || (typeof window !== 'undefined' ? window.__OXYZN_ARK_API_KEY__ : '') || '').trim();
 if (!k) throw new Error(apiKeyHelp('BytePlus ModelArk API'));
 return k;
 };

 // v832: Assets API 호출 — AK/SK 서명은 메인 프로세스가 만든다.
 //   렌더러에서 하지 않는 이유는 electron/main.js 의 'ark-openapi' 주석에 정리해뒀다.
 //   반환: { result } 또는 throw. 오류 메시지는 사람이 읽고 조치할 수 있게 다듬는다.
 const arkOpenapiCall = async (action, body) => {
 const ak = (arkAccessKeyId || (typeof window !== 'undefined' ? window.__OXYZN_ARK_AK__ : '') || '').trim();
 const sk = (arkSecretKey || (typeof window !== 'undefined' ? window.__OXYZN_ARK_SK__ : '') || '').trim();
 if (!ak || !sk) throw new Error(apiKeyHelp('ModelArk Access Key ID · Secret Key'));
 if (!window.electronAPI?.arkOpenapi) throw new Error('이 기능은 데스크톱 앱에서만 동작합니다.');

 const r = await window.electronAPI.arkOpenapi({
 ak, sk, action, version: ARK_OPENAPI_VERSION, region: ARK_OPENAPI_REGION,
 body: { ...(body || {}), ProjectName: ARK_ASSET_PROJECT },
 });
 if (!r) throw new Error('응답이 없습니다. 앱을 재시작한 뒤 다시 시도해주세요.');
 if (r.success) return r.result || {};

 // 자주 나오는 실패를 원인별로 바꿔준다 — 원문만 보면 무엇을 고쳐야 할지 알기 어렵다
 const code = String(r.code || '');
 const msg = String(r.error || '알 수 없는 오류');
 // v834: 호출부가 Action 맥락에 맞는 문구를 만들 수 있게 구조화된 정보를 실어 보낸다.
 //   같은 404 라도 '토큰 없음'과 '자산 없음'은 사용자에게 전혀 다른 이야기다.
 const fail = (m) => { const e = new Error(m); e.status = r.status; e.code = code; e.raw = msg; return e; };
 if (r.status === 403 || /AccessDenied|NoPermission|Forbidden/i.test(code)) {
 // v1051: 403 을 IAM 권한 문제로만 안내하다가 사람을 엉뚱한 곳으로 보냈다.
 //   BytePlus 는 '구독 플랜이 없음' 도 403 으로 돌려준다. 그때 IAM 을 뒤지면
 //   아무리 봐도 권한은 멀쩡해서 원인을 못 찾는다. 원문을 보고 갈라준다.
 if (/subscription|subscribe|plan/i.test(msg)) {
 throw fail(`이 계정에는 배우 인증을 쓸 자격이 없습니다 (403). 키나 IAM 권한 문제가 아닙니다 — 계정에 붙은 등급 문제입니다.\n\n실인물 인증(Assets API)은 BytePlus 의 Advanced Creation Rights 가 있어야 열립니다. 기업용 유료 권한이라 법인 인증과 별도 계약이 필요하고, 선불 리소스 팩을 사둔 것과는 무관합니다(팩은 사용량, 이건 자격).\n\n같은 앱에서 되던 계정이 있다면 그쪽에 이 권한이 있는 것입니다. BytePlus 콘솔에서 두 계정의 Advanced Creation Rights 상태를 비교해보세요.\n\n원본: ${msg}`);
 }
 throw fail(`권한이 없습니다 (403). Access Key 계정에 해당 프로젝트(${ARK_ASSET_PROJECT})의 ArkFullAccess 권한이 있는지, 그리고 Advanced Creation Rights가 Entry 이상인지 확인해주세요.\n\n원본: ${msg}`);
 }
 if (r.status === 401 || /SignatureDoesNotMatch|InvalidAccessKey|InvalidCredential/i.test(code)) {
 throw fail(`인증 실패 (${r.status || 401}). Access Key ID와 Secret Key를 다시 확인해주세요. Secret Key는 발급 시 한 번만 표시되므로, 값이 확실하지 않으면 새로 발급받는 편이 빠릅니다.\n\n원본: ${msg}`);
 }
 if (r.status === 429 || /Throttl|LimitExceeded|QuotaExceeded/i.test(code)) {
 throw fail(`호출 한도를 넘었습니다 (${code || 429}). 이 API는 초당 3회 제한입니다. 잠시 후 다시 시도해주세요.`);
 }
 throw fail(code ? `${msg} (${code})` : msg);
 };

 // v841: 인증된 배우와 그 자산을 ModelArk 에서 읽어온다.
 //   그룹 목록과 자산 목록을 따로 받아 GroupId 로 묶는다 (한 번에 주는 API 가 없다).
 //   Active 가 아닌 자산은 영상 생성에 쓸 수 없으므로 걸러낸다.
 const loadActorAssets = async () => {
 setActorAssetLib(p => ({ ...p, loading: true, err: '' }));
 try {
 // v844: 두 조회를 병렬로 보낸다. 자산 목록은 그룹 결과에 의존하지 않고
 //   GroupId 로 나중에 묶기만 하므로 순서를 지킬 이유가 없다.
 //   실측: 순차 225~240ms → 병렬 약 120ms. (첫 호출은 TLS 핸드셰이크로 700ms 대)
 //   그룹이 0개면 자산 조회가 헛수고지만, 계정이 빈 경우에만 그렇고 비용도 없다.
 const [gr, as] = await Promise.all([
 arkOpenapiCall('ListAssetGroups', {
 Filter: { GroupType: ARK_ASSET_GROUP_TYPE_REAL }, PageNumber: 1, PageSize: 100,
 }),
 // v853: Active 만 받으면 실패한 자산이 화면에서 조용히 사라진다.
 //   영상 2개를 올렸는데 1개만 보이고 이유를 알 수 없는 상태가 됐다(실제 발생).
 //   전부 받아서 아카이브에는 실패 사유까지 보여주고, 선택기에서만 Active 로 거른다.
 arkOpenapiCall('ListAssets', {
 Filter: { GroupType: ARK_ASSET_GROUP_TYPE_REAL },
 PageNumber: 1, PageSize: 100, SortBy: 'CreateTime', SortOrder: 'Desc',
 }),
 ]);
 const groups = ((gr && gr.Items) || []).map(g => ({
 id: String(g.Id || ''), name: String(g.Name || ''), description: String(g.Description || ''),
 createTime: String(g.CreateTime || ''), assets: [],
 })).filter(g => g.id);

 {
 const byId = new Map(groups.map(g => [g.id, g]));
 for (const it of ((as && as.Items) || [])) {
 const g = byId.get(String(it.GroupId || ''));
 if (!g) continue; // 다른 계정이 권한을 준 자산 등 — 그룹 목록에 없으면 건너뛴다
 g.assets.push({
 id: String(it.Id || ''), name: String(it.Name || ''),
 url: String(it.URL || ''), // 공개 URL — 문서상 12시간 유효. 썸네일 표시용으로만 쓴다
 status: String(it.Status || ''), assetType: String(it.AssetType || 'Image'),
 // v853: 실패 사유 (Status 가 Failed 일 때만 온다)
 errCode: String(it.Error?.Code || ''), errMsg: String(it.Error?.Message || ''),
 });
 }
 }
 setActorAssetLib({ loading: false, err: '', loadedAt: Date.now(), groups });
 return groups;
 } catch (e) {
 // v844: 이전 목록은 남긴다 — 새로고침이 한 번 실패했다고 화면이 비면 더 나쁘다
 setActorAssetLib(p => ({ ...p, loading: false, err: e.message || '배우 자산을 불러오지 못했습니다.' }));
 return null;
 }
 };

 // v844: 배우 탭을 누르는 순간 네트워크를 가면, 다른 탭과 달리 빈 화면이 잠깐 떠서
 //   '화면이 멈춘' 느낌이 난다. 그래서 랜딩에 들어오면 미리 받아둔다.
 //   ref 로 한 번만 시도한다 — 실패 시 loadedAt 이 0 이라 상태 의존 effect 로 짜면
 //   loading true→false 가 deps 를 다시 흔들어 무한 재시도가 된다.
 const actorPrefetchTried = useRef(false);
 useEffect(() => {
 // v845: 랜딩뿐 아니라 단일 작업 화면에서도 받는다 — VFX·내러티브로 바로 들어가는
 //   경로에서 목록이 비어 '인증된 배우가 없습니다' 로 잘못 보이는 걸 막는다.
 if (appScreen !== 'landing' && appScreen !== 'single') return;
 if (actorPrefetchTried.current) return;
 // 키가 없으면 호출이 무조건 실패한다 — 굳이 시도해서 오류를 남기지 않는다
 if (!(arkAccessKeyId || '').trim() || !(arkSecretKey || '').trim()) return;
 actorPrefetchTried.current = true;
 // 랜딩 첫 페인트를 방해하지 않게 살짝 미룬다
 const t = setTimeout(() => { loadActorAssets(); }, 700);
 return () => clearTimeout(t);
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [appScreen, arkAccessKeyId, arkSecretKey]);

 // v756: ModelArk 연결 테스트 — 영상 생성 태스크 "목록 조회"(읽기 전용)로 인증만 확인한다.
 //   생성 요청이 아니므로 크레딧이 소모되지 않는다.
 const handleTestArkConnection = async () => {
 let key;
 try { key = arkKey(); } catch (e) { setArkTest({ state: 'fail', msg: e.message }); return; }
 setArkTest({ state: 'testing', msg: '연결 확인 중…' });
 try {
 const res = await fetch(`${ARK_BASE}/contents/generations/tasks?page_num=1&page_size=1`, {
 headers: { 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
 });
 const body = await res.text().catch(() => '');
 if (res.ok) {
 setArkTest({ state: 'ok', msg: '연결 성공 — 키가 정상 동작합니다.' });
 return;
 }
 if (res.status === 401 || res.status === 403) {
 setArkTest({ state: 'fail', msg: `인증 실패 (${res.status}) — 키를 다시 확인해주세요.` });
 return;
 }
 if (res.status === 404) {
 // 엔드포인트/리전은 맞지만 계정에 모델이 활성화되지 않은 경우도 여기로 온다
 setArkTest({ state: 'fail', msg: `엔드포인트를 찾을 수 없습니다 (404). 리전 또는 모델 활성화 상태를 확인해주세요.` });
 return;
 }
 setArkTest({ state: 'fail', msg: `연결 실패 (${res.status}): ${body.slice(0, 160)}` });
 } catch (e) {
 setArkTest({ state: 'fail', msg: `네트워크 오류: ${String(e.message || e).slice(0, 160)}` });
 }
 };

 // v758: ModelArk 이미지 생성 — Seedream 5.0 (POST /images/generations, 동기 응답)
 //   size는 명시 WxH 사용 (총 픽셀 921,600~4,624,220 · 화면비 1/16~16 범위 내여야 함)
 //   watermark 기본값이 true이므로 false를 명시한다. 결과 URL은 24시간만 유효.
 const callArkImage = async (prompt, { size = ARK_IMG_SIZES['16:9'], model = ARK_MODELS.image, numOutputs = 1, refImages = [] } = {}) => {
 const apiKey = arkKey();
 const _t0 = Date.now(); // v791: 실측 소요시간
 const results = [];
 // ARK 이미지 API는 1회 1장 기준 — 요청 장수만큼 순차 호출
 for (let i = 0; i < Math.max(1, Math.min(3, Number(numOutputs) || 1)); i++) {
 const input = {
 model,
 prompt,
 size,
 response_format: 'url',
 output_format: 'png',
 watermark: false,
 };
 // 프롬프트 재작성 폭을 줄여 레이아웃 일관성을 높인다 (지원 모델에만 전달)
 if (ARK_SUPPORTS_FAST_OPTIMIZE(model)) input.optimize_prompt_options = { mode: 'fast' };
 // 레퍼런스 이미지(선택) — data URI 또는 공개 URL. 단일/다중 모두 지원
 const refs = (refImages || []).filter(r => r && r.base64 && r.mimeType)
 .map(r => `data:${r.mimeType};base64,${r.base64}`);
 if (refs.length === 1) input.image = refs[0];
 else if (refs.length > 1) input.image = refs;

 const res = await fetch(`${ARK_BASE}/images/generations`, {
 method: 'POST',
 headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
 body: JSON.stringify(input),
 });
 const body = await res.text().catch(() => '');
 if (!res.ok) {
 if (res.status === 401 || res.status === 403) throw new Error(`ModelArk 인증 실패 (${res.status}) — API 키를 확인해주세요.`);
 let msg = body.slice(0, 300);
 try { const j = JSON.parse(body); msg = j?.error?.message || j?.message || msg; } catch {}
 // 모델 미활성화(리소스 팩 미구매) 케이스를 구분해 안내
 if (/not activated|not enabled|not open|activate/i.test(msg)) {
 throw new Error(`모델이 활성화되지 않았습니다 — BytePlus 콘솔에서 리소스 팩 구매 후 모델을 활성화해주세요.\n(${msg.slice(0, 160)})`);
 }
 throw new Error(`이미지 생성 실패 (${res.status}): ${msg}`);
 }
 let out;
 try { out = JSON.parse(body); } catch { throw new Error('ModelArk 응답을 해석할 수 없습니다.'); }
 const first = Array.isArray(out?.data) ? out.data[0] : null;
 if (first?.error) throw new Error(`이미지 생성 실패: ${first.error.message || first.error.code}`);
 const url = first?.url || null;
 if (!url) throw new Error(`이미지 URL을 받지 못했습니다: ${JSON.stringify(out).slice(0, 200)}`);
 results.push({ url });
 // v777: 장당 정액 과금 — 실제 응답 크기(first.size)로 구간을 판정한다.
 //   레퍼런스 입력분은 첫 장에서만 합산(2장째부터 유료).
 try {
 const outSize = String(first.size || size);
 const refN = Array.isArray(refImages) ? refImages.length : 0;
 const isFirst = results.length === 1;
 recordCreditUsage(estimateArkImageCost(outSize, 1, model, isFirst ? refN : 0), 'image', { workCat: 'image' });
 } catch {}
 }
 // v791: 요청 장수 전체를 마친 시점 기준으로 기록 (워크스페이스 추정도 장수 단위)
 try { recordJobDuration(durKeyArkImage(model, size, numOutputs), (Date.now() - _t0) / 1000); } catch {}
 return results;
 };

 // v782: 업스케일 결과 저장 — 아카이브(비디오) 분류
 // v1071: 이름을 FFS 규칙에서 빼고 '원본이름_해상도' 로 둔다. 업스케일은 새로
 //   만든 것이 아니라 같은 영상의 다른 판이라, 원본과 나란히 놓였을 때 어느
 //   것의 몇 p 인지 바로 읽히는 편이 낫다. ffsBuildName 을 태우면 FFS_Upscale_
 //   접두어와 _v001 이 붙고, ffsToken 이 공백과 언더스코어를 지워 원본
 //   파일명이 뭉개진다 — 그래서 여기서는 직접 만든다.
 const handleDownloadUpscale = async (job) => {
 const url = job?.resultUrl;
 if (!url) return;
 const base = String(job.params?.name || '영상').replace(/\.[^.]+$/, '');
 const safe = base.replace(/[\\\\/:*?"<>|]/g, '').trim() || '영상';
 const h = Number(job.params?.outH) || 0;
 const fileName = safe + (h ? '_' + h : '') + '.mp4';
 setConfirmDialog({
 title: '영상 저장',
 message: `"${fileName}"\n\n다운로드 폴더에 저장되고, 아카이브(비디오)에도 보관됩니다.`,
 confirmLabel: '저장',
 onCancel: () => setConfirmDialog(null),
 onConfirm: async () => {
 setConfirmDialog(null);
 try {
 window.electronAPI?.setDownloadCategory?.('video');
 const res = await fetch(url);
 const blob = await res.blob();
 const objUrl = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = objUrl; a.download = fileName;
 document.body.appendChild(a); a.click(); document.body.removeChild(a);
 URL.revokeObjectURL(objUrl);
 try { showToast('영상을 저장했습니다.', 'load'); } catch {}
 } catch (err) {
 setUpscaleData(p => ({ ...p, error: `다운로드 실패: ${err.message}` }));
 }
 },
 });
 };

 // v782: Topaz 영상 업스케일 — fal-ai/topaz/upscale/video
 //   입력은 공개 URL만 받으므로 로컬 파일은 fal 스토리지에 올려 URL을 확보한다.
 //   비용은 '출력' 해상도(입력 높이 x 배율)와 길이로 정해진다 → 호출 후 실측값으로 기록.
 const callTopazUpscale = async ({ videoUrl, model, upscaleFactor = 2, targetFps = null, h264 = true, srcSec = null }) => {
 const apiKey = falKey();
 const _t0 = Date.now(); // v791: 실측 소요시간
 let src = videoUrl;
 if (!/^https?:\/\//i.test(String(src || ''))) {
 try { src = await falUploadFile(videoUrl, apiKey); }
 catch (e) { throw new Error(`영상 업로드 실패: ${e.message}`); }
 }
 const input = { video_url: src, model, upscale_factor: Number(upscaleFactor) || 2, H264_output: !!h264 };
 // target_fps를 넣으면 프레임 보간이 켜진다 (비용 2배 — 60fps 기준)
 if (targetFps) input.target_fps = Number(targetFps);
 // Gaia 2는 2배 고정
 if (/gaia 2/i.test(String(model))) input.upscale_factor = 2;
 const out = await falRun(FAL_MODELS.upscaleVideo, input, { apiKey, pollMs: 4000, maxPolls: 300, kind: 'video' });
 const url = out?.video?.url || null;
 if (!url) throw new Error(`업스케일 결과 URL을 받지 못했습니다: ${JSON.stringify(out).slice(0, 200)}`);
 try { recordJobDuration(durKeyUpscale(model, input.upscale_factor, srcSec), (Date.now() - _t0) / 1000); } catch {}
 return url;
 };

 // v749: fal API 키 조회 — 모든 fal 호출의 단일 진입점
 const falKey = () => {
 const k = (falApiKey || (typeof window !== 'undefined' ? window.__OXYZN_FAL_API_KEY__ : '') || '').trim();
 if (!k) throw new Error(apiKeyHelp('fal API'));
 return k;
 };

 // v749: fal 큐 API 공용 실행 — 제출 → 상태 폴링 → 결과 반환
 //   opts.on422(input, err) → 재시도할 새 input을 돌려주면 1회 재제출 (없으면 오류)
 //   opts.pollMs / opts.maxPolls 로 대기 주기·횟수 조절 (기본 3초 × 300 = 약 15분)
 const falRun = async (endpoint, input, opts = {}) => {
 const apiKey = opts.apiKey || falKey();
 const pollMs = opts.pollMs || 3000;
 const maxPolls = opts.maxPolls || 300;
 const submit = async (body) => fetch(`${FAL_QUEUE_BASE}/${endpoint}`, {
 method: 'POST',
 headers: { 'Authorization': `Key ${apiKey}`, 'Content-Type': 'application/json' },
 body: JSON.stringify(body),
 });

 let subRes = await submit(input);
 if (subRes.status === 422) {
 const body = await subRes.text().catch(() => '');
 const e = parseFalError(body);
 // 콘텐츠 정책 거부는 입력을 바꿔도 동일하게 막히므로 즉시 안내
 const alt = e.isPolicy ? null : (opts.on422 ? opts.on422(input, e) : null);
 if (!alt) throw new Error(falErrorMessage(422, body, opts.kind));
 console.warn(`[fal] ${endpoint} 입력 검증 실패 → 보정 후 재시도:`, e.raw);
 subRes = await submit(alt);
 }
 if (!subRes.ok) {
 const t = await subRes.text().catch(() => '');
 if (subRes.status === 401 || subRes.status === 403) throw new Error(`fal 인증 실패 (${subRes.status}) — API 키를 확인해주세요.`);
 throw new Error(falErrorMessage(subRes.status, t, opts.kind));
 }

 const queued = await subRes.json();
 const statusUrl = queued.status_url || `${FAL_QUEUE_BASE}/${endpoint}/requests/${queued.request_id}/status`;
 const resultUrl = queued.response_url || `${FAL_QUEUE_BASE}/${endpoint}/requests/${queued.request_id}`;

 let status = queued.status || 'IN_QUEUE';
 let failure = null;
 for (let i = 0; i < maxPolls && status !== 'COMPLETED' && !failure; i++) {
 await new Promise(r => setTimeout(r, pollMs));
 try {
 const sr = await fetch(statusUrl, { headers: { 'Authorization': `Key ${apiKey}` } });
 const sj = await sr.json().catch(() => ({}));
 if (sj.status) status = sj.status;
 if (status === 'FAILED' || status === 'ERROR') failure = sj.error || sj.detail || status;
 } catch { /* 일시적 네트워크 오류 — 다음 주기에 재시도 */ }
 }
 if (failure) {
 // v780: fal은 실패 상세를 status가 아니라 result 엔드포인트에 담아준다.
 //   status 응답만 보면 sj.error/sj.detail이 비어 failure가 문자열 'FAILED'로 남고,
 //   호출부의 사유별 안내(길이 부족·화자 다수 등) 정규식이 전부 빗나가 원인 불명이 됐다.
 let detailBody = '';
 try {
 const fr = await fetch(resultUrl, { headers: { 'Authorization': `Key ${apiKey}` } });
 detailBody = await fr.text().catch(() => '');
 } catch { /* 본문을 못 읽으면 status 정보만으로 안내 */ }
 const raw = detailBody || (typeof failure === 'string' ? failure : JSON.stringify({ detail: failure }));
 console.error(`[fal] ${endpoint} 실패 원문:`, raw.slice(0, 1200));
 throw new Error(falErrorMessage('생성 실패', raw, opts.kind));
 }
 if (status !== 'COMPLETED') throw new Error('생성 시간이 초과되었습니다. 잠시 후 다시 시도해주세요.');

 const rr = await fetch(resultUrl, { headers: { 'Authorization': `Key ${apiKey}` } });
 if (!rr.ok) throw new Error(falErrorMessage(rr.status, await rr.text().catch(() => ''), opts.kind));
 // v858: 입력 검증 실패는 status=FAILED 로 오지 않는다. status 는 COMPLETED, HTTP 는 200 인데
 //   본문이 { detail: [{ loc, msg, type: 'value_error' }] } 로 온다(FastAPI 형식).
 //   지금까지 이게 그대로 통과해서, 호출부가 '결과 형식 오류' 라며 JSON 조각을 그대로
 //   보여줬다. 실제로 만료된 보이스 클론으로 TTS 를 돌렸을 때 그렇게 묻혔다.
 const rtext = await rr.text();
 let rjson;
 try { rjson = JSON.parse(rtext); } catch { throw new Error(`${FAL_KIND_LABEL[opts.kind] || 'fal'} 응답을 해석할 수 없습니다: ${rtext.slice(0, 200)}`); }
 if (rjson && Array.isArray(rjson.detail)) throw new Error(falErrorMessage('입력 오류', rtext, opts.kind));
 return rjson;
 };

 //   v935: file:// 에서 읽은 blob 은 type 이 비어 있다. 확장자·Content-Type 이
 //   엉키면 받는 쪽이 영상으로 안 읽으므로 호출부가 지정할 수 있게 뒀다.
 const falUploadFile = async (src, apiKey, typeHint) => {
 if (!src) throw new Error('업로드할 파일이 없습니다.');
 if (/^https?:\/\//i.test(src)) return src; // 이미 공개 URL이면 그대로 사용
 const blob = await (await fetch(src)).blob();
 const contentType = typeHint || blob.type || 'application/octet-stream';
 const ext = ((contentType.split('/')[1] || 'bin').split(';')[0]) || 'bin';
 const initRes = await fetch(`${FAL_REST_BASE}/storage/upload/initiate?storage_type=fal-cdn-v3`, {
 method: 'POST',
 headers: { 'Authorization': `Key ${apiKey}`, 'Content-Type': 'application/json' },
 body: JSON.stringify({ content_type: contentType, file_name: `oxyzn_${Date.now()}.${ext}` }),
 });
 if (!initRes.ok) {
 // v984: 원문 JSON 을 그대로 던지면 '코드 오류' 처럼 보인다. 해석을 거친다.
 const t = await initRes.text().catch(() => '');
 throw new Error(falErrorMessage(initRes.status, t, 'upload'));
 }
 const { upload_url: uploadUrl, file_url: fileUrl } = await initRes.json();
 if (!uploadUrl || !fileUrl) throw new Error('fal 업로드 URL을 받지 못했습니다.');
 const putRes = await fetch(uploadUrl, { method: 'PUT', body: blob, headers: { 'Content-Type': contentType } });
 if (!putRes.ok) {
 // v985: 413 은 크기 거부다. 숫자를 같이 알려주지 않으면 무엇을 줄여야 하는지
 //   알 수가 없다 — 실제로 '업로드 실패 (413)' 만 보고 원인을 찾아야 했다.
 const mb = (blob.size / 1048576).toFixed(1);
 if (putRes.status === 413) {
 throw new Error(`파일이 너무 커서 fal 이 받지 않았습니다 (413).\n`
 + `이 파일 ${mb}MB — fal 스토리지 업로드 상한을 넘었습니다.\n\n`
 + `· 앱에서 만든 영상이라면 그 결과에서 바로 업스케일하십시오. 그때는 이미 공개된\n`
 + `  주소를 그대로 넘기므로 업로드 단계가 없습니다.\n`
 + `· 외부 파일이라면 길이를 자르거나 해상도를 낮춰 다시 시도하십시오.\n`
 + `  업스케일은 입력이 작아도 출력 배율로 화질이 올라갑니다.`);
 }
 throw new Error(`fal 파일 업로드 실패 (${putRes.status}) — ${mb}MB`);
 }
 return fileUrl;
 };

 // v1006: 원래 callSeedanceVideo 안에 있던 것을 꺼냈다. 프로젝트 쪽에서도 같은
 //   함수를 써야 같은 캐시를 타고, 무엇보다 '몇 번 Audio 인지' 를 프롬프트에 적기
 //   전에 미리 올려볼 수 있다 — 올리기가 실패한 것을 번호에서 빼야 하기 때문이다.
 // ★ 캐시 키는 내용 해시여야 한다. 처음에 '길이|앞 96자' 로 했다가 위험을 발견했다 —
 //   data URL 의 앞부분은 'data:image/png;base64,' + PNG 헤더라, 같은 규격으로 뽑은
 //   시트끼리 앞 96자가 그대로 같다(실측: 12장 중 5장이 동일). 길이까지 겹치면
 //   캐시가 다른 인물의 이미지를 돌려주고, 그건 조용한 콘티뉴이티 붕괴다.
 const falPublicUrl = async (src, what) => {
 const u = String(src || '');
 if (!u || /^https?:\/\//i.test(u) || /^asset:\/\//i.test(u)) return u;
 const key = await falCacheKey(u);
 if (FAL_UPLOAD_CACHE.has(key)) return FAL_UPLOAD_CACHE.get(key);
 const url = await falUploadFile(u, falKey());
 FAL_UPLOAD_CACHE.set(key, url);
 try { console.log(`[ark] ${what || '레퍼런스'} 업로드 — ${(u.length / 1048576).toFixed(1)}MB → 공개 주소`); } catch {}
 return url;
 };

 // v746: Seedance 2.0 영상 생성 — fal.ai (기존 Replicate 호출 대체)
 //   호출부 인자 형태는 그대로 유지하고, 입력 구성에 따라 엔드포인트를 자동 선택한다.
 //   · firstFrame 지정 → image-to-video (그 이미지를 첫 프레임으로 사용)
 //   · 영상/이미지 레퍼런스 있음 → reference-to-video (프롬프트의 @Image1/@Video1로 지칭)
 //   · 둘 다 없음 → text-to-video
 // v763: Seedance 2.0 영상 생성 — BytePlus ModelArk 직결 (fal 경유 폐지)
 //   호출부 인자 형태는 그대로 유지해 6개 워크스페이스를 무변경으로 태운다.
 //   · 이미지 레퍼런스: 공개 URL / base64 data URI / asset:// 모두 허용
 //   · 영상 레퍼런스: 공개 URL만 허용 (base64 미지원) → 로컬 파일은 업로드해 URL 확보
 //   · 프롬프트의 레퍼런스 토큰은 ModelArk 표기("Image 1")로 변환
 //   신뢰 출력(같은 계정의 ModelArk 생성물)이 그대로 통하도록, 원본 URL은 재인코딩 없이 전달한다.
 //   v936: tier 로 모델을 고른다('video' = 2.0 · 'video25' = 2.5). 길이·해상도
 //   상한도 티어를 따른다 — 2.5 는 30초까지, 2.0 은 15초까지다.
 // v997: onStatus 가 파라미터 목록에 없었다. 폴링 루프가 try/catch 안에서 부르고 있어서
 //   ReferenceError 가 삼켜지고, '대기열에서 기다리는 중 / 영상 만드는 중' 표시가
 //   한 번도 갱신되지 않았다. 호출부는 v916 부터 넘기고 있었다.
 const callSeedanceVideo = async ({ prompt, duration = 15, resolution = '1080p', aspectRatio = '16:9', generateAudio = false, images = [], videos = [], audios = [], firstFrame = null, endFrame = null, tier = 'video25', onStatus }) => {
 const apiKey = arkKey();
 const _t0 = Date.now(); // v791: 실제 소요시간 측정 (진행도 추정 학습용)

 // ── 입력 정리 ──
 // v944: tierKey 는 입력 정리(개수 상한)에서부터 쓰인다. 출력 스펙에 두면
 //   audioUrls 가 선언 전에 읽어 호출마다 TDZ 가 났다 — v939 에서 그랬다.
 const tierKey = ARK_MODELS[tier] ? tier : 'video25';
 const model = ARK_MODELS[tierKey];
 const asImageEntry = (src, role) => ({ type: 'image_url', image_url: { url: src }, role });
 const content = [];

 // 영상 레퍼런스는 공개 URL 필수 → data URL이면 업로드해서 URL 확보
 const videoUrls = [];
 for (const v of (videos || [])) {
 if (!v) continue;
 if (videoUrls.length >= arkRefMax(tierKey, 'videos')) break;
 if (/^https?:\/\//i.test(v) || /^asset:\/\//i.test(v)) { videoUrls.push(v); continue; }
 try {
 videoUrls.push(await falUploadFile(v, falKey())); // 공개 호스팅 확보용
 } catch (e) {
 throw new Error(`영상 레퍼런스 업로드 실패 (ModelArk는 공개 URL만 받습니다): ${e.message}`);
 }
 }

 // v1000: 이미지·오디오도 공개 URL 로 올려 보낸다.
 //   전에는 data URI 를 그대로 실었다. v974·v976 에서 캐릭터·시트 원본을 로컬
 //   파일로 옮긴 뒤로는 레퍼런스가 거의 다 data URL 이 되어, 요청 본문이
 //   27~33MB 까지 불어 ARK 가 413(Request Entity Too Large)로 거절했다.
 //   영상 레퍼런스가 이미 쓰는 방식 그대로 — 바이트를 손대지 않고 올린다.
 //   (재인코딩하면 ModelArk 의 '눈에 안 보이는 표시' 가 지워져 심의에 걸린다)
 const asPublicUrl = falPublicUrl;

 // 이미지 레퍼런스 — 원본 URL이면 그대로, data URL 이면 올려서 주소를 얻는다
 const imageUrls = [];
 for (const im of (images || []).filter(Boolean)) {
 if (imageUrls.length >= arkRefMax(tierKey, 'images')) break;
 try { imageUrls.push(await asPublicUrl(im, '이미지 레퍼런스')); }
 catch (e) {
 throw new Error(`이미지 레퍼런스 업로드 실패 (ModelArk 요청에 담기엔 너무 큽니다): ${e.message}`);
 }
 }

 // 프롬프트 토큰을 ModelArk 표기로 변환 (@Image1 / [Image1] → Image 1)
 content.push({ type: 'text', text: arkRefTokens(prompt) });

 if (firstFrame) {
 content.push(asImageEntry(firstFrame, 'first_frame'));
 if (endFrame) content.push(asImageEntry(endFrame, 'last_frame'));
 } else {
 for (const u of imageUrls) content.push(asImageEntry(u, 'reference_image'));
 }
 for (const u of videoUrls) content.push({ type: 'video_url', video_url: { url: u }, role: 'reference_video' });
 // v773: 오디오 레퍼런스 — 최대 3개, 이미지/영상이 하나도 없으면 단독 입력 불가라 생략
 const audioUrls = [];
 for (const au of (audios || []).filter(Boolean)) {
 if (audioUrls.length >= arkRefMax(tierKey, 'audios')) break;
 // v1006: 여기서 조용히 빠지면 프롬프트의 'Audio 1' 이 다른 사람의 목소리를
 //   가리킨다. 호출부가 미리 올려 넘기므로 보통 여기서 실패하지 않지만,
 //   실패하면 어느 번호가 비었는지 남긴다.
 try { audioUrls.push(await asPublicUrl(au, '보이스 레퍼런스')); }
 catch (e) { console.warn(`[ark] 보이스 레퍼런스 ${audioUrls.length + 1}번을 올리지 못했습니다 — 이 클립의 Audio 번호가 밀립니다.`, e?.message); }
 }
 if (audioUrls.length && (imageUrls.length || videoUrls.length || firstFrame)) {
 for (const u of audioUrls) content.push({ type: 'audio_url', audio_url: { url: u }, role: 'reference_audio' });
 } else if (audioUrls.length) {
 console.warn('[ark] 이미지·영상 레퍼런스가 없어 보이스 레퍼런스를 보내지 못했습니다 — 프롬프트의 Audio 번호는 가리킬 것이 없습니다.');
 }

 // ── 출력 스펙 ──
 // 티어가 못 내는 해상도를 달라고 하면 그 티어의 최대치로 내린다
 const maxRes = ARK_VIDEO_MAX_RES[tierKey] || '1080p';
 const wanted = ARK_VIDEO_RESOLUTIONS.includes(resolution) ? resolution : '720p';
 const res = ARK_VIDEO_RESOLUTIONS.indexOf(wanted) > ARK_VIDEO_RESOLUTIONS.indexOf(maxRes) ? maxRes : wanted;
 const ratio = ARK_VIDEO_RATIOS.includes(arkRatio(aspectRatio)) ? arkRatio(aspectRatio) : 'adaptive';
 const dur = Math.max(4, Math.min(ARK_VIDEO_MAX_SEC[tierKey] || 15, Math.round(Number(duration) || 5)));
 const body = {
 model,
 content,
 generate_audio: !!generateAudio,
 resolution: res,
 ratio,
 duration: dur,
 watermark: false,
 };
 // v1046: 영상을 레퍼런스로 붙이면 2.5 가 작업 유형을 스스로 판정한다(auto).
 //   '영상 이어붙이기' 로 잘못 잡으면 ratio 를 adaptive 로만 받아 태스크가 실패한다 —
 //   실제로 그랬다. 우리가 원하는 것은 언제나 '레퍼런스로 새 영상' 이므로 못 박는다.
 //   reference 는 ratio · duration 에 특별 제약이 없다(문서). 2.5 전용 파라미터이고,
 //   영상 레퍼런스가 없으면 애초에 이 분류가 일어나지 않으므로 그때만 보낸다.
 if (tierKey === 'video25' && videoUrls.length) body.omni_reference_task_type = 'reference';

 try {
 console.log(`[ark] ${model} — 이미지 ${imageUrls.length} / 영상 ${videoUrls.length} · ${res} ${ratio} ${dur}s`);
 } catch {}

 // ── 태스크 생성 ──
 const createRes = await fetch(`${ARK_BASE}/contents/generations/tasks`, {
 method: 'POST',
 headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
 body: JSON.stringify(body),
 });
 const createText = await createRes.text().catch(() => '');
 if (!createRes.ok) throw new Error(arkErrorMessage(createRes.status, createText));
 let task;
 try { task = JSON.parse(createText); } catch { throw new Error('ModelArk 응답을 해석할 수 없습니다.'); }
 const taskId = task?.id;
 if (!taskId) throw new Error(`태스크 ID를 받지 못했습니다: ${createText.slice(0, 200)}`);

 // ── 폴링 ──
 // v916: 상한이 15분이었는데 레퍼런스를 여러 장 붙이면 그보다 오래 걸린다.
 //   여기서 손을 놓아도 서버는 계속 만든다 — 결과만 잃고 비용은 나간다.
 //   상한을 40분으로 올리고, 그래도 안 끝나면 taskId 를 오류에 실어 보낸다.
 //   호출한 쪽이 그 id 로 나중에 이어받을 수 있다(resumeArkVideoTask).
 let status = task.status || 'queued';
 let last = task;
 for (let i = 0; i < ARK_VIDEO_POLL_MAX && !['succeeded', 'failed', 'cancelled', 'expired'].includes(status); i++) {
 await new Promise(r => setTimeout(r, ARK_VIDEO_POLL_MS));
 try {
 const pr = await fetch(`${ARK_BASE}/contents/generations/tasks/${taskId}`, {
 headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
 });
 const pt = await pr.text().catch(() => '');
 if (pr.ok) { last = JSON.parse(pt); status = last.status || status; }
 } catch { /* 일시적 네트워크 오류 — 다음 주기에 재시도 */ }
 try { onStatus?.(status, i, taskId); } catch { /* 알림 실패는 무시 */ }
 }

 if (status === 'failed' || status === 'cancelled' || status === 'expired') {
 throw new Error(arkErrorMessage(status, JSON.stringify({ error: last?.error })));
 }
 if (status !== 'succeeded') {
 const e = new Error(`영상 생성이 ${Math.round(ARK_VIDEO_POLL_MAX * ARK_VIDEO_POLL_MS / 60000)}분을 넘겼습니다.`
 + ' 서버에서는 계속 만들고 있을 수 있습니다 — 잠시 뒤 이어받기를 눌러보세요.');
 e.taskId = taskId;
 e.pending = true;
 throw e;
 }

 const url = last?.content?.video_url || null;
 if (!url) throw new Error(`영상 URL을 받지 못했습니다: ${JSON.stringify(last).slice(0, 200)}`);

 // v791: 실측 소요시간을 종류별로 남긴다 — 다음 생성의 진행도 추정이 실제에 수렴한다
 try { recordJobDuration(durKeyVideo(res, dur, videoUrls.length > 0), (Date.now() - _t0) / 1000); } catch {}
 // v778: 실제 소모 토큰(completion_tokens)에 문서 단가를 적용해 기록.
 //   단가는 출력 해상도와 '영상 입력 포함 여부'로 결정된다. 토큰이 안 오면 공식으로 추정.
 try {
 const tokens = Number(last?.usage?.completion_tokens) || 0;
 const hasVideoInput = videoUrls.length > 0;
 const aspForCost = ratio === 'adaptive' ? '16:9' : ratio;
 // v936: 단가는 모델마다 다르다. 2.5 는 2.0 보다 토큰당 53% 비싸다.
 const usd = tokens
 ? (tokens * arkVideoRate(res, hasVideoInput, tierKey)) / 1e6
 : estimateSeedance2Cost(dur, res, aspForCost, { tier: tierKey, hasVideoInput, inputSec: dur });
 recordCreditUsage(usd, 'video', { workCat: 'video' });
 } catch {}
 return url;
 };

 // ─────────────────────────────────────────────────────────────
 // v306: Replicate 음악 생성 (elevenlabs/music)
 // ─────────────────────────────────────────────────────────────
 // ─────────────────────────────────────────────────────────────
 // v310: 음악·가사 생성 예상 비용 계산
 // ─────────────────────────────────────────────────────────────
 // Claude API 단가 (per 1M tokens, USD)
 // Haiku 4.5: input $1.00, output $5.00
 // Sonnet 4.5: input $3.00, output $15.00
 // Opus 4.5: input $15.00, output $75.00
 // Replicate elevenlabs/music: 분당 약 $0.10~0.15 (1초당 ~$0.002, 추정)
 const CLAUDE_PRICING = {
 'claude-haiku-4-5': { input: 1.00, output: 5.00 },
 'claude-sonnet-4-5': { input: 3.00, output: 15.00 },
 'claude-opus-4-5': { input: 15.00, output: 75.00 },
 };
 const getClaudePrice = (model) => CLAUDE_PRICING[model] || CLAUDE_PRICING['claude-sonnet-4-5'];
 // 음악 비용: 길이(초) × $0.0025/초 (elevenlabs/music 추정치, 분당 ~$0.15)
 const MUSIC_COST_PER_SEC = 0.0025;

 // 가사 미리보기 비용 추정 (입력 ~1000토큰, 출력 ~1500토큰)
 const estimateLyricsCost = (model) => {
 const p = getClaudePrice(model);
 const inTokens = 1000;
 const outTokens = 1500;
 return (inTokens / 1_000_000) * p.input + (outTokens / 1_000_000) * p.output;
 };

 // 음악 프롬프트 생성 비용 (입력 ~800토큰, 출력 ~500~1500토큰, 가사 포함 시 더 많음)
 const estimatePromptGenCost = (model, hasLyrics) => {
 const p = getClaudePrice(model);
 const inTokens = 800;
 const outTokens = hasLyrics ? 1500 : 500;
 return (inTokens / 1_000_000) * p.input + (outTokens / 1_000_000) * p.output;
 };

 // 음악 생성 비용 (길이 기반)
 const estimateMusicCost = (durationSec) => MUSIC_COST_PER_SEC * durationSec;

 // 전체 음악 생성 (프롬프트 + Replicate)
 const estimateTotalMusicCost = (model, durationSec, hasLyrics, hasPreview) => {
 // hasPreview가 true면 자동 작사 미리보기로 이미 가사 생성됨 → 프롬프트 생성 시 가사 부담 없음
 const promptCost = estimatePromptGenCost(model, hasLyrics && !hasPreview);
 const musicCost = estimateMusicCost(durationSec);
 return { promptCost, musicCost, total: promptCost + musicCost };
 };

 // 통화 포맷 (USD → 미국 달러 + 원화 환산, 환율 약 1380원)
 const fmtCost = (usd) => {
 const krw = Math.round(usd * 1380);
 if (usd < 0.01) return `< $0.01 (~₩${krw.toLocaleString()})`;
 return `$${usd.toFixed(usd < 0.1 ? 4 : 3)} (~₩${krw.toLocaleString()})`;
 };

 // 입력 스키마:
 // prompt (required): string - 음악 설명
 // music_length_ms (optional): integer 5000~300000 - 밀리초 단위 길이
 // force_instrumental (optional): boolean - true면 보컬 제거
 // output_format (optional): mp3_standard | mp3_high_quality | wav_16khz | wav_22khz | wav_24khz | wav_cd_quality
 // 출력: audio URL (mp3 또는 wav)
 // v749: 음악 생성 — fal (fal-ai/elevenlabs/music). 기존 Replicate elevenlabs/music과 동일 모델
 const callFalMusic = async ({ prompt, musicLengthMs = 10000, forceInstrumental = true, outputFormat = 'mp3_high_quality' }) => {
 const safeLength = Math.max(5000, Math.min(300000, Math.round(musicLengthMs)));
 // 앱의 포맷 이름(mp3_high_quality 등)을 fal enum(codec_samplerate_bitrate)으로 변환
 const falFormat = FAL_MUSIC_FORMAT[outputFormat] || 'mp3_44100_192';

 try {
 console.group(`Music API Call — ${FAL_MODELS.music}`);
 console.log('Prompt:', (prompt || '').slice(0, 300) + ((prompt || '').length > 300 ? '...' : ''));
 console.log(`Length: ${safeLength}ms (${(safeLength / 1000).toFixed(1)}s) · Instrumental: ${forceInstrumental} · Format: ${outputFormat} → ${falFormat}`);
 console.groupEnd();
 } catch {}

 const out = await falRun(FAL_MODELS.music, {
 prompt,
 music_length_ms: safeLength,
 force_instrumental: !!forceInstrumental,
 output_format: falFormat,
 }, { pollMs: 5000, maxPolls: 60, kind: 'music' }); // 음악은 보통 30~90초 · 최대 5분

 const url = out?.audio?.url || null;
 if (!url) throw new Error(`음악 결과 URL을 받지 못했습니다: ${JSON.stringify(out).slice(0, 200)}`);
 try { recordCreditUsage((safeLength / 1000) * 0.0025, 'music', { workCat: 'sound' }); } catch {}
 return { url, format: outputFormat, durationMs: safeLength };
 };

 // v1050: Inst 만들기 — fal-ai/demucs 로 스템을 나눈 뒤 보컬을 뺀 나머지를 합친다.
 //   htdemucs(4스템)를 쓴다. 어차피 합칠 것이라 6스템으로 잘게 쪼갤 이유가 없고 더 빠르다.
 //   보컬 스템은 받지 않는다 — 쓸 데가 없다. 원곡이 이미 '보컬 포함' 버전이다.
 //   (비용은 스템 수와 무관하다. 오디오 길이로만 매겨진다)
 //   합치기는 브라우저에서 한다. fal 이 '반주 한 트랙' 을 따로 주지 않기 때문이다.
 const callStemSeparate = async ({ audioUrl, durationMs }) => {
 const out = await falRun(FAL_MODELS.stemSeparate, {
 audio_url: audioUrl,
 model: 'htdemucs',
 stems: ['drums', 'bass', 'other'],
 // v1054: mp3 가 아니라 wav 로 받는다. wav 는 압축이 없어 오디오 디코더를
 //   거치지 않고 헤더만 읽어 더할 수 있다. mp3 를 decodeAudioData 로 풀다가
 //   렌더러가 네이티브 크래시(0xC0000005)로 죽었다.
 output_format: 'wav',
 }, { pollMs: 4000, maxPolls: 120, kind: 'music' });

 const pick = (k) => out?.[k]?.url || null;
 const rest = ['drums', 'bass', 'other'].map(pick).filter(Boolean);
 if (!rest.length) {
 throw new Error(`스템 분리 결과가 비었습니다: ${JSON.stringify(out).slice(0, 200)}`);
 }
 const inst = await mixWavUrlsToWavUrl(rest);
 try { recordCreditUsage(((durationMs || 0) / 1000) * DEMUCS_COST_PER_SEC, 'etc', { workCat: 'sound' }); } catch {}
 return { inst };
 };

 // ─────────────────────────────────────────────────────────────
 // v316: Replicate google/gemini-3-flash 호출 (영상 분석용)
 // 입력 스키마:
 // prompt (required): string — 텍스트 프롬프트
 // videos (optional): string[] — 영상 URL 배열 (최대 10개)
 // audio, images: 사용 안 함
 // system_instruction (optional): string — 시스템 프롬프트
 // thinking_level (optional): 'low' | 'high'
 // temperature, top_p, max_output_tokens
 // 출력: 텍스트 응답
 // ─────────────────────────────────────────────────────────────
 // ─────────────────────────────────────────────────────────────
 // v336: Google Gemini API 직접 호출 (영상 분석 전용)
 // Replicate 경유 방식 대체 — YouTube URL 네이티브 지원
 // 모델: gemini-2.5-flash
 // v819: 무료 티어 실측 한도 — 분당 요청 5회 · 분당 입력 25만 토큰.
 //   일일 한도(RPD)는 Google 이 문서에 공개하지 않고 프로젝트마다 다르다.
 //   내 프로젝트 값은 https://aistudio.google.com/rate-limit 에서 확인한다.
 // ─────────────────────────────────────────────────────────────
 // ─────────────────────────────────────────────────────────────
 // v816: 영상 파일을 Gemini Files API 에 올린다 (공개 없이 분석하기 위해).
 //   1) resumable start → x-goog-upload-url 헤더로 업로드 주소 발급
 //   2) 그 주소로 바이트 전송 + finalize (XHR 로 진행률 보고)
 //   3) state 가 ACTIVE 가 될 때까지 폴링
 //   반환: { uri, name, mimeType, expirationTime }
 // ─────────────────────────────────────────────────────────────
 const uploadVideoToGemini = async (file, onStage) => {
 const apiKey = sanitizeApiKey(googleApiKey || window.__OXYZN_GOOGLE_API_KEY__ || '');
 if (!apiKey) throw new Error(apiKeyHelp('Google Gemini API'));
 if (!file) throw new Error('업로드할 영상 파일이 없습니다.');
 if (file.size > GEMINI_FILE_MAX_BYTES) {
 throw new Error(`파일이 너무 큽니다 — ${(file.size / 1024 / 1024 / 1024).toFixed(1)}GB.\n\nGoogle 프로젝트 저장 할당량이 20GB이므로 그보다 큰 파일은 올릴 수 없습니다.\n\n· 편집 프로그램에서 프록시(저용량 사본)로 내보내 올려주세요.\n  분석 품질은 같습니다 — Gemini는 1초당 1프레임만 뽑아 보므로 고비트레이트 원본이 이점이 없습니다.`);
 }
 const mimeType = videoMimeOf(file);

 // 1) 업로드 세션 시작
 onStage?.({ phase: 'start', pct: 0 });
 const startRes = await fetch(`${GEMINI_API_BASE}/upload/v1beta/files`, {
 method: 'POST',
 headers: {
 'x-goog-api-key': apiKey,
 'X-Goog-Upload-Protocol': 'resumable',
 'X-Goog-Upload-Command': 'start',
 'X-Goog-Upload-Header-Content-Length': String(file.size),
 'X-Goog-Upload-Header-Content-Type': mimeType,
 'Content-Type': 'application/json',
 },
 body: JSON.stringify({ file: { display_name: file.name || 'video' } }),
 });
 if (!startRes.ok) {
 const t = await startRes.text().catch(() => '');
 throw new Error(`업로드를 시작할 수 없습니다 (${startRes.status}).\n\n원본: ${t.slice(0, 300)}`);
 }
 const uploadUrl = startRes.headers.get('x-goog-upload-url');
 if (!uploadUrl) throw new Error('업로드 주소를 받지 못했습니다. 잠시 후 다시 시도해주세요.');

 // 2) 바이트 전송 — 진행률을 보려면 XHR 이 필요하다(fetch 는 업로드 진행률을 주지 않는다)
 const uploaded = await new Promise((resolve, reject) => {
 const xhr = new XMLHttpRequest();
 xhr.open('POST', uploadUrl, true);
 xhr.setRequestHeader('X-Goog-Upload-Offset', '0');
 xhr.setRequestHeader('X-Goog-Upload-Command', 'upload, finalize');
 xhr.upload.onprogress = (e) => {
 if (e.lengthComputable) onStage?.({ phase: 'upload', pct: Math.round((e.loaded / e.total) * 100), loaded: e.loaded, total: e.total });
 };
 xhr.onload = () => {
 if (xhr.status >= 200 && xhr.status < 300) {
 try { resolve(JSON.parse(xhr.responseText)); }
 catch { reject(new Error('업로드 응답을 해석할 수 없습니다.')); }
 } else {
 reject(new Error(`업로드 실패 (${xhr.status}).\n\n원본: ${String(xhr.responseText || '').slice(0, 300)}`));
 }
 };
 xhr.onerror = () => reject(new Error('업로드 중 네트워크 오류가 발생했습니다. 연결을 확인하고 다시 시도해주세요.'));
 xhr.onabort = () => reject(new Error('업로드가 취소되었습니다.'));
 // File 을 그대로 넘기면 Chromium 이 스트리밍한다 — 큰 파일도 메모리에 다 올리지 않는다
 xhr.send(file);
 });

 const f = uploaded?.file || {};
 if (!f.name || !f.uri) throw new Error('업로드 결과가 올바르지 않습니다.');

 // 3) ACTIVE 대기 — 영상은 서버에서 처리(프레임 추출)를 거친다
 onStage?.({ phase: 'processing', pct: 100 });
 let state = f.state || 'PROCESSING';
 const deadline = Date.now() + 15 * 60 * 1000; // 긴 영상은 처리도 오래 걸린다
 while (state === 'PROCESSING') {
 if (Date.now() > deadline) throw new Error('업로드한 영상의 처리가 15분을 넘겼습니다.\n\n영상이 매우 길거나 서버가 혼잡할 수 있습니다. 잠시 후 다시 시도해주세요.');
 await new Promise(r => setTimeout(r, 3000));
 const g = await fetch(`${GEMINI_API_BASE}/v1beta/${f.name}`, { headers: { 'x-goog-api-key': apiKey } });
 if (!g.ok) break; // 조회가 안 되면 그대로 진행 — 분석 단계에서 오류가 드러난다
 const gj = await g.json().catch(() => ({}));
 state = gj?.state || state;
 if (gj?.uri) f.uri = gj.uri;
 if (gj?.expirationTime) f.expirationTime = gj.expirationTime;
 }
 if (state === 'FAILED') throw new Error('업로드한 영상을 Gemini가 처리하지 못했습니다.\n\n손상된 파일이거나 지원하지 않는 코덱일 수 있습니다. mp4(H.264)로 변환해 다시 시도해주세요.');

 onStage?.({ phase: 'done', pct: 100 });
 return { uri: f.uri, name: f.name, mimeType: f.mimeType || mimeType, expirationTime: f.expirationTime || '' };
 };

 // 분석이 끝난 파일은 바로 지운다 — 48시간 자동 삭제를 기다릴 필요가 없다.
 // 실패해도 무시한다(자동 만료가 있으므로 치명적이지 않다).
 const deleteGeminiFile = async (name) => {
 if (!name) return;
 try {
 const apiKey = sanitizeApiKey(googleApiKey || window.__OXYZN_GOOGLE_API_KEY__ || '');
 if (!apiKey) return;
 await fetch(`${GEMINI_API_BASE}/v1beta/${name}`, { method: 'DELETE', headers: { 'x-goog-api-key': apiKey } });
 console.log('[Files API] 삭제:', name);
 } catch (e) { console.warn('[Files API] 삭제 실패(자동 만료됨):', e?.message || e); }
 };

 // v809: mediaResolution / timeoutMs 추가 — 1시간 넘는 영상 분석용.
 //   gemini-2.5-flash 의 입력 컨텍스트는 1M 토큰이고, 영상은
 //     기본 해상도  → 초당 약 300 토큰 (프레임 258 + 오디오 32)
 //     저해상도      → 초당 약 100 토큰 (프레임 64  + 오디오 32)
 //   즉 기본 해상도로는 약 1시간이 한계이고, 저해상도로 바꾸면 최대 3시간까지 들어간다.
 //   2시간 영상을 기본 해상도로 보내면 약 216만 토큰이 되어 요청 자체가 거부된다.
 const callGoogleGemini = async ({ prompt, videos = [], systemInstruction = '', temperature = 0.7, maxOutputTokens = 32000, mediaResolution = null, timeoutMs = 25 * 60 * 1000 }) => {
 const apiKey = sanitizeApiKey(googleApiKey || window.__OXYZN_GOOGLE_API_KEY__ || '');
 if (!apiKey) throw new Error(apiKeyHelp('Google Gemini API') + (isAdmin ? '\n\nhttps://aistudio.google.com 에서 무료로 발급할 수 있습니다.' : ''));

 // v813: 어떤 키가 실제로 쓰였는지 식별할 수 있게 지문을 만든다.
 //   403 이 났을 때 '키 권한 문제'라고만 하면 어느 키가 들어갔는지 알 수 없어
 //   진단이 불가능했다. 값 자체는 절대 노출하지 않고 앞4·뒤4 와 출처만 남긴다.
 //   (Google 키는 종류가 달라도 전부 'AIza' 로 시작하고 39자라서 눈으로 구분이 안 된다)
 const keyFp = apiKey.length >= 8 ? `${apiKey.slice(0, 4)}…${apiKey.slice(-4)} (${apiKey.length}자)` : `(${apiKey.length}자)`;
 let keySrc = '내장';
 try {
 if (sanitizeApiKey(localStorage.getItem('oxyzn_google_api_key') || '') === apiKey) keySrc = '직접 입력(이 기기)';
 } catch {}

 const model = 'gemini-2.5-flash';

 // 메시지 parts 구성
 // YouTube URL → fileData (Google 서버끼리 직접 통신)
 // v817: fileUri 는 두 가지만 유효하다 — Files API URI, YouTube 공개 URL.
 //   그 외 링크(Drive·frame.io 등)는 Gemini 가 가져오지 못하므로 변환 시도 자체를 없앴다.
 const parts = [];
 for (const videoUrl of videos) {
 const isObj = videoUrl && typeof videoUrl === 'object';
 parts.push({
 fileData: {
 mimeType: (isObj && videoUrl.mimeType) || 'video/mp4',
 fileUri: isObj ? videoUrl.url : videoUrl,
 },
 });
 }
 parts.push({ text: prompt });

 const requestBody = {
 contents: [{ role: 'user', parts }],
 generationConfig: {
 temperature,
 maxOutputTokens,
 // 값이 없으면 필드를 아예 넣지 않는다(= 기본 해상도).
 ...(mediaResolution ? { mediaResolution } : {}),
 },
 };
 if (systemInstruction) {
 requestBody.systemInstruction = { parts: [{ text: systemInstruction }] };
 }

 try {
 console.group('Google Gemini API — ' + model);
 console.log('Videos:', videos);
 console.log('Media resolution:', mediaResolution || '(기본)', '· Timeout:', Math.round(timeoutMs / 60000) + '분');
 console.log('Prompt:', prompt.slice(0, 300) + (prompt.length > 300 ? '...' : ''));
 console.groupEnd();
 } catch {}

 // v813: 키를 URL 쿼리에서 헤더로 옮겼다. 쿼리로 보내면 로그·에러 리포트·프록시에
 //   전체 URL 이 그대로 남아 키가 새어나간다. x-goog-api-key 는 공식 지원 방식이다.
 const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;

 // v792: 타임아웃이 아예 없어서 긴 영상 분석이 무한정 매달릴 수 있었다.
 // v809: 25분 고정이었던 것을 영상 길이에 맞춰 호출부가 정하도록 바꿨다.
 //   2~3시간 영상은 25분으로 부족해 정상 처리 중인 요청을 끊어버렸다.
 const controller = new AbortController();
 const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
 let response;
 try {
 response = await fetch(endpoint, {
 method: 'POST',
 headers: { 'Content-Type': 'application/json', 'x-goog-api-key': apiKey },
 body: JSON.stringify(requestBody),
 signal: controller.signal,
 });
 } catch (e) {
 if (e && e.name === 'AbortError') {
 throw new Error(`영상 분석이 ${Math.round(timeoutMs / 60000)}분을 초과했습니다.\n\n영상이 너무 길거나 서버 부하가 높을 수 있습니다.\n· 더 짧은 구간을 잘라 분석하거나\n· 잠시 후 다시 시도해주세요.`);
 }
 throw e;
 } finally {
 clearTimeout(timeoutId);
 }

 if (!response.ok) {
 const errText = await response.text().catch(() => '');
 let errMsg = `Google Gemini API 오류 (${response.status}): ${errText.slice(0, 400)}`;
 // v809: 컨텍스트(토큰) 초과인지 먼저 판별한다. 호출부가 이 표식을 보고
 //   저해상도로 자동 재시도하므로, 다른 400 메시지에 묻히지 않게 맨 앞에서 잡는다.
 const overflow = /token count|exceeds the maximum|maximum number of tokens|input token|too large|context length/i.test(errText);
 if (overflow) {
 const e = new Error('영상이 너무 길어 한 번에 분석할 수 있는 한도를 넘었습니다.\n\n원본: ' + errText.slice(0, 200));
 e.ffTokenOverflow = true;
 throw e;
 }
 // mediaResolution 자체가 거부된 경우 — 원인이 드러나지 않으면 진단이 어렵다
 if (mediaResolution && /media_?resolution/i.test(errText)) {
 throw new Error(`긴 영상 모드(저해상도)를 이 모델이 받지 않았습니다.\n\n${model} 기준 문서에는 지원으로 표기돼 있으나 API가 거부했습니다.\n영상을 1시간 이하로 나눠 분석해주세요.\n\n원본: ${errText.slice(0, 200)}`);
 }
 // v813: Google 이 돌려주는 구조화된 사유(error.details[].reason)를 읽어 분류한다.
 //   이전에는 403 을 통째로 'Gemini API 활성화 확인' 으로 바꿔버려서, 실제로는
 //   '이 키가 Gemini 용이 아님(API_KEY_SERVICE_BLOCKED)' 인 경우에도 엉뚱한 곳을
 //   보게 만들었다. 원문을 버리지 않고 항상 함께 보여준다.
 let reason = '';
 try {
 const j = JSON.parse(errText);
 reason = (j?.error?.details || []).map(d => d?.reason).filter(Boolean)[0] || '';
 } catch {}
 const keyInfo = `\n\n사용된 키: ${keyFp} · 출처: ${keySrc}`;

 // 친절한 에러 메시지
 if (response.status === 400) {
 if (errText.includes('API_KEY_INVALID') || errText.includes('API key not valid')) {
 errMsg = 'Google API 키가 유효하지 않습니다.\n\n' + apiKeyCheckHelp + keyInfo;
 } else if (errText.includes('INVALID_ARGUMENT')) {
 errMsg = 'YouTube 영상을 처리할 수 없습니다. 영상이 비공개·삭제됐거나 지역 제한이 있을 수 있습니다.\n\n원본: ' + errText.slice(0, 200);
 }
 } else if (response.status === 403) {
 if (reason === 'API_KEY_SERVICE_BLOCKED') {
 // 키는 살아 있지만 Gemini(generativelanguage) 사용이 허용돼 있지 않다.
 // 실제로 가장 흔한 원인은 다른 Google 키(예: Places 키)가 들어간 것이다.
 // Google 키는 종류가 달라도 모두 'AIza' 로 시작하고 39자라 눈으로 구분되지 않는다.
 errMsg = '이 키로는 Gemini를 호출할 수 없습니다 (키에 Gemini 사용 권한이 없음).'
 + '\n\n· 다른 Google 키(예: Google Places 키)가 Gemini 칸에 들어갔을 가능성이 가장 큽니다.'
 + ' Google 키는 종류가 달라도 모두 AIza로 시작하고 39자라서 눈으로 구분되지 않습니다.'
 + '\n· 설정 > API 관리 탭에서 Google Gemini 키와 Google Places 키가 서로 바뀌지 않았는지 확인해주세요.'
 + '\n· 키에 API 제한(Cloud Console > 사용자 인증 정보 > API 제한)이 걸려 있어도 같은 오류가 납니다.'
 + keyInfo;
 } else if (reason === 'API_KEY_HTTP_REFERRER_BLOCKED' || reason === 'API_KEY_IP_ADDRESS_BLOCKED' || reason === 'API_KEY_ANDROID_APP_BLOCKED' || reason === 'API_KEY_IOS_APP_BLOCKED') {
 errMsg = '키에 걸린 사용 제한 때문에 차단됐습니다 (' + reason + ').'
 + '\n\nCloud Console > 사용자 인증 정보에서 이 키의 "애플리케이션 제한"을 "없음"으로 두거나,'
 + ' 데스크톱 앱에서 쓸 수 있는 제한으로 바꿔주세요.' + keyInfo;
 } else if (reason === 'SERVICE_DISABLED') {
 errMsg = '이 프로젝트에 Generative Language API가 활성화되지 않았습니다.'
 + '\n\naistudio.google.com 또는 Cloud Console에서 활성화해주세요.' + keyInfo;
 } else if (reason === 'CONSUMER_SUSPENDED' || /denied access/i.test(errText)) {
 errMsg = 'Google이 이 프로젝트의 Gemini API 접근을 차단했습니다.'
 + '\n\n새 프로젝트에서 키를 다시 발급하거나 Google 지원에 문의가 필요합니다.' + keyInfo;
 } else if (videos.length > 0) {
 // v815: 사유(details[].reason)가 없는 403 은 키 문제가 아니다.
 //   키에 문제가 있으면 Google 은 항상 reason 을 붙여 보낸다
 //   (API_KEY_SERVICE_BLOCKED · SERVICE_DISABLED 등 — 실측 확인).
 //   reason 없이 "The caller does not have permission" 만 오는 경우는
 //   키가 아니라 '그 영상'에 접근할 수 없다는 뜻이다.
 //   가장 흔한 원인이 일부공개(Unlisted)·비공개 영상이다.
 errMsg = '영상에 접근할 수 없습니다 (403).'
 + '\n\n키 문제가 아닙니다 — 키에 문제가 있으면 Google이 구체적 사유를 함께 보냅니다.'
 + ' 이 응답에는 사유가 없어, 해당 영상을 읽을 권한이 없다는 뜻입니다.'
 + '\n\n확인해주세요:'
 + '\n· 영상 공개 상태가 "공개"인가요? 일부공개(Unlisted)·비공개는 분석할 수 없습니다.'
 + '\n· 멤버십 전용·구매 전용 영상이 아닌가요?'
 + '\n· 지역 차단이 걸려 있지 않나요?'
 + keyInfo + '\n\n원본: ' + errText.slice(0, 300);
 } else {
 errMsg = 'Google API 권한 오류 (403).' + keyInfo + '\n\n원본: ' + errText.slice(0, 300);
 }
 } else if (response.status === 429) {
 // v818: 429 는 '오늘 많이 썼다' 와 '이 요청 하나가 한도보다 크다' 가 섞여 있다.
 //   Google 이 위반한 한도 이름을 details 에 담아주므로 그걸로 구분한다.
 //   실측: 27만 토큰 단일 요청 →
 //     generate_content_free_tier_input_token_count = 250000
 const violations = [];
 let retryHint = '';
 try {
 const j = JSON.parse(errText);
 for (const d of (j?.error?.details || [])) {
 for (const v of (d?.violations || [])) violations.push(v);
 if (d?.retryDelay) retryHint = String(d.retryDelay);
 }
 } catch {}
 const inputLimit = violations.find(v => /input_token_count/.test(v?.quotaMetric || ''));
 const isFree = violations.some(v => /free_tier/.test(v?.quotaMetric || ''));
 if (isFree) vaSetTier('free'); // 다음부터는 올리기 전에 막을 수 있다

 if (inputLimit) {
 const cap = Number(inputLimit.quotaValue) || VA_FREE_TIER_INPUT_LIMIT;
 const budget = Math.max(0, cap - VA_FREE_TIER_BUDGET);
 errMsg = `이 요청 하나가 한도보다 큽니다 — ${isFree ? '무료' : '현재'} 티어는 요청당 입력 ${cap.toLocaleString()} 토큰까지입니다.`
 + `\n\n영상은 1초당 약 ${VA_TOKENS_PER_SEC_DEFAULT}토큰(기본 해상도) / ${VA_TOKENS_PER_SEC_LOW}토큰(긴 영상 모드)을 씁니다.`
 + `\n이 한도에서 분석 가능한 최대 길이:`
 + `\n· 기본 해상도 — 약 ${vaFmtDuration(Math.floor(budget / VA_TOKENS_PER_SEC_DEFAULT))}`
 + `\n· 긴 영상 모드 — 약 ${vaFmtDuration(Math.floor(budget / VA_TOKENS_PER_SEC_LOW))}`
 + `\n\n· 영상을 나눠 각각 분석하거나`
 + `\n· Google Cloud에서 결제를 활성화(유료 티어)하면 이 한도가 풀립니다.`
 + (isFree ? '\n\n※ 공개 전 자료라면 어차피 유료 티어가 필요합니다 — 무료 티어는 Google이 제품 개선에 사용하고 사람이 검토할 수 있습니다.' : '');
 } else {
 // v819: 위반한 한도를 그대로 보여준다. 예전에는 '하루 250회' 라고 단정했는데
 //   Google 이 이 값을 문서에 더는 공개하지 않고 프로젝트마다 다르다.
 //   실측 확인된 무료 티어 값: 분당 요청 5회, 분당 입력 25만 토큰.
 const v = violations[0];
 const perMinute = v && /PerMinute/i.test(v.quotaId || '');
 errMsg = `Google API 사용 한도에 걸렸습니다${v ? ` — ${v.quotaId}` : ''}.`
 + (v?.quotaValue ? `\n한도값: ${Number(v.quotaValue).toLocaleString()}` : '')
 + (perMinute
 ? '\n\n분당 한도입니다. 잠시 기다린 뒤 다시 시도하면 됩니다.'
 + '\n(무료 티어 실측: 분당 요청 5회 · 분당 입력 25만 토큰)'
 : '\n\n하루 한도일 수 있습니다. 일일 한도는 태평양 시간 자정(한국시간 오후 4~5시)에 갱신됩니다.'
 + '\n무료 티어는 YouTube 영상 길이 합계도 하루 8시간으로 제한됩니다.')
 + '\n\n· 내 프로젝트의 정확한 한도: https://aistudio.google.com/rate-limit'
 + '\n· 한도를 늘리려면 Google Cloud에서 결제를 활성화해주세요.'
 + (retryHint ? `\n\n권장 재시도: ${retryHint} 후` : '');
 }
 }
 throw new Error(errMsg);
 }

 const data = await response.json();

 // 응답 파싱
 const candidates = data.candidates || [];
 if (!candidates.length) {
 // 안전 필터링 등으로 응답 없는 경우
 const blockReason = data.promptFeedback?.blockReason;
 if (blockReason) throw new Error(`Gemini 응답 차단됨: ${blockReason}. 영상 내용이 안전 필터에 걸렸을 수 있습니다.`);
 throw new Error('Gemini 응답이 비어있습니다.');
 }

 const parts2 = candidates[0]?.content?.parts || [];
 return parts2.map(p => p.text || '').join('');
 };

 // ─────────────────────────────────────────────────────────────
 // v308: 가사 미리보기 — 음악 생성 전에 가사만 먼저 작성 (lyricsMode === 'auto')
 // ─────────────────────────────────────────────────────────────
 const handleGenerateLyricsPreview = async () => {
 const { genre, mood, customPrompt, duration, lyricsLanguage, lyricsTopic } = musicToolData;
 const moodStr = (mood || []).join(', ');
 const langLabel = { ko: '한국어', en: '영어', zh: '중국어 (보통화)', ja: '일본어', fr: '프랑스어' }[lyricsLanguage] || '한국어';
 const safeDuration = Math.max(5, Math.min(300, Math.round(duration)));

 if (!genre && (!mood || mood.length === 0) && !customPrompt.trim() && !lyricsTopic.trim()) {
 setMusicToolData(p => ({ ...p, error: '장르, 분위기, 자유 묘사, 또는 가사 주제 중 최소 하나는 입력해주세요.' }));
 return;
 }

 setMusicToolData(p => ({ ...p, isGeneratingLyrics: true, error: '' }));

 try {
 // 가사 분량 가이드 (러닝타임 기반)
 let lengthGuide;
 if (safeDuration <= 30) {
 lengthGuide = '짧은 곡 — [Verse] 1개 + [Chorus] 1개 정도 (총 8~12줄)';
 } else if (safeDuration <= 60) {
 lengthGuide = '표준 곡 — [Verse] + [Chorus] + [Verse] 또는 [Bridge] + [Chorus] 정도 (총 12~20줄)';
 } else if (safeDuration <= 120) {
 lengthGuide = '풀송 — [Verse 1] + [Pre-Chorus] + [Chorus] + [Verse 2] + [Chorus] + [Bridge] + [Chorus] (총 20~32줄)';
 } else {
 lengthGuide = '대형 풀송 — Verse·Chorus·Bridge·Outro 풍부하게 (총 28~40줄)';
 }

 const systemPrompt = `당신은 전문 작사가입니다. 음악 분위기와 주제에 어울리는 ${langLabel} 가사를 작성합니다.

[작사 원칙]
1. ★ ${langLabel} 원어로 작사 ★ — 영어로 번역하거나 다른 언어 혼용 금지.
2. 구조 마커 사용: [Intro], [Verse], [Pre-Chorus], [Chorus], [Bridge], [Outro] 등을 영문 그대로 유지.
3. 정서적으로 일관된 흐름 — 도입부의 감정에서 절정으로, 마지막에 정리·여운.
4. 진부한 클리셰 회피 — "사랑해 영원히", "별이 빛나는 밤" 같은 식상한 표현 지양.
5. 구체적 이미지·은유 사용 — 추상적 감정보다 시각·청각·촉각 디테일로.
6. 분량: ${lengthGuide}.
7. 운율·리듬을 자연스럽게 — 한 줄의 글자 수와 호흡을 일정하게.

[출력 형식]
- 구조 마커는 영문([Verse], [Chorus] 등), 가사 본문은 ${langLabel}로.
- 가사만 출력. 다른 설명·해설·따옴표·코드블록 없이.
- 줄바꿈으로 라인 구분, 빈 줄로 섹션 구분.

[좋은 예시 — 한국어]
[Verse]
가로등 아래 너의 그림자
오늘 밤도 혼자 걷는 길
바람에 실려오는 너의 향기

[Pre-Chorus]
잡을 수 없는 어제의 우리
손끝에 남은 마지막 온도

[Chorus]
이 밤이 끝나기 전에
한 번만 더 너의 이름을 부르고 싶어
다시 돌아올 수 없는 우리지만
바람에 실어 보낸 내 마음

[Outro]
잘 가, 나의 사랑
잘 가...`;

 const userMessage = `[작품 정보]
- 음악 장르: ${genre || '미지정'}
- 분위기: ${moodStr || '미지정'}
- 자유 묘사: ${customPrompt || '없음'}
- 가사 주제·키워드: ${lyricsTopic.trim() || '(음악 분위기에 자연스럽게 어울리는 주제로 자유롭게)'}
- 곡 길이: ${safeDuration}초
- 언어: ${langLabel}

위 정보를 바탕으로 ${langLabel} 가사를 작성해주세요.`;

 const lyrics = await callClaude(systemPrompt, userMessage, {
 model: musicLyricsModel,
 maxTokens: 2000,
 workCat: 'sound',
 });

 const cleanedLyrics = (lyrics || '').trim()
 .replace(/^```[\w]*\n?/, '') // 코드블록 시작 제거
 .replace(/\n?```$/, '') // 코드블록 끝 제거
 .replace(/^["']|["']$/g, ''); // 외부 따옴표 제거

 if (!cleanedLyrics || cleanedLyrics.length < 30) {
 throw new Error(`가사 생성 결과가 너무 짧습니다 (${cleanedLyrics.length}자). 다시 시도해주세요.`);
 }

 setMusicToolData(p => ({
 ...p,
 lyricsPreview: cleanedLyrics,
 isGeneratingLyrics: false,
 }));
 } catch (err) {
 console.error('Lyrics preview error:', err);
 setMusicToolData(p => ({
 ...p,
 isGeneratingLyrics: false,
 error: err.message || '가사 미리보기 생성 중 오류가 발생했습니다.',
 }));
 }
 };

 // ─────────────────────────────────────────────────────────────
 // v725: 시나리오 구간 → 장르·분위기·묘사 자동 추출 (BGM 매트릭스 옵션 기준)
 // ─────────────────────────────────────────────────────────────
 const handleExtractBgmFromScenario = async () => {
 const excerpt = (musicToolData.scenarioExcerpt || '').trim();
 if (!excerpt) {
 setMusicToolData(p => ({ ...p, extractGenreError: '시나리오 구간을 먼저 붙여넣어주세요.' }));
 return;
 }
 setMusicToolData(p => ({ ...p, isExtractingGenre: true, extractGenreError: '' }));
 try {
 const genreOptions = WORK_GENRES.map((g, i) => `${i + 1}. ${g}`).join('\n');
 const moodOptions = SCENE_MOOD_GROUPS.map(([group, items]) => `- ${group}: ${items.join(', ')}`).join('\n');
 const systemPrompt = `당신은 드라마 시나리오를 읽고 그 장면에 어울리는 배경음악(BGM) 사양을 판단하는 전문가입니다.
아래 정해진 옵션 목록 중에서만 골라야 합니다(목록에 없는 값은 절대 만들어내지 마세요).

[작품 장르 옵션]
${genreOptions}

[씬 분위기 옵션 — 그룹: 하위 항목들]
${moodOptions}

[작업]
1. 시나리오 구간을 읽고 이 장면이 속한 작품 장르를 위 목록에서 정확히 1개 고른다. (문체·소재로 추정, 애매하면 가장 근접한 것)
2. 이 장면의 정서를 위 씬 분위기 옵션에서 정확히 1개 고른다. (그룹명과 하위 항목명을 정확히 목록의 표기 그대로)
3. 이 장면 고유의 톤·상황(등장인물의 감정 상태, 사건의 성격 등)을 반영한 짧은 자유 묘사를 1~2문장의 한국어로 작성한다. 악기나 장르를 나열하지 말고, 장면의 정서·상황을 묘사한다.

[출력 형식]
다른 설명 없이 아래 JSON 객체 하나만 출력:
{"genre": "<장르 옵션 중 정확히 하나>", "moodGroup": "<씬 분위기 그룹명>", "mood": "<씬 분위기 하위 항목명>", "description": "<한국어 자유 묘사 1~2문장>"}`;
 const userMessage = `[시나리오 구간]\n${excerpt.slice(0, 6000)}`;
 const raw = await callClaude(systemPrompt, userMessage, { maxTokens: 400, workCat: 'sound' });
 const jsonMatch = (raw || '').match(/\{[\s\S]*\}/);
 if (!jsonMatch) throw new Error('AI 응답에서 결과를 읽지 못했습니다.');
 const parsed = JSON.parse(jsonMatch[0]);

 const matchedGenre = WORK_GENRES.find(g => g === parsed.genre) || WORK_GENRES.find(g => parsed.genre && parsed.genre.includes(g)) || '';
 let matchedGroup = '';
 let matchedMood = '';
 for (const [group, items] of SCENE_MOOD_GROUPS) {
 const hit = items.find(it => it === parsed.mood) ;
 if (hit) { matchedGroup = group; matchedMood = hit; break; }
 }
 if (!matchedMood && parsed.moodGroup) {
 const grp = SCENE_MOOD_GROUPS.find(([g]) => g === parsed.moodGroup);
 if (grp) { matchedGroup = grp[0]; matchedMood = grp[1].find(it => parsed.mood && it.includes(parsed.mood)) || grp[1][0] || ''; }
 }
 if (!matchedGenre && !matchedMood) throw new Error('시나리오에서 장르·분위기를 판단하지 못했습니다. 다른 구간으로 시도해주세요.');

 setMusicToolData(p => ({
 ...p,
 genre: matchedGenre || p.genre,
 moodGroup: matchedGroup || p.moodGroup,
 mood: matchedMood ? [matchedMood] : p.mood,
 customPrompt: (parsed.description || '').trim() || p.customPrompt,
 genreInputMode: 'manual', // 추출 완료 후 직접입력 화면으로 전환 → 결과 확인·수정 가능
 isExtractingGenre: false,
 extractGenreError: '',
 }));
 try { showToast('시나리오에서 장르·분위기·묘사를 추출했습니다. 필요하면 수정해주세요.', 'load'); } catch {}
 } catch (err) {
 setMusicToolData(p => ({ ...p, isExtractingGenre: false, extractGenreError: err.message || '추출 중 오류가 발생했습니다.' }));
 }
 };

