 const handleAdaptFileUpload = async (file) => {
 if (!file) return;
 const ext = file.name.toLowerCase().split('.').pop();
 setError('');

 try {
 let text = '';
 if (ext === 'txt') {
 text = await file.text();
 } else if (ext === 'pdf') {
  // v500: extractTextFromPDF 사용 (Y좌표 기반 줄 분리, 한글 공백 정상화 포함)
  // v792: 대용량 PDF는 추출만으로도 오래 걸린다 → 페이지 진행을 표시한다
  text = await extractTextFromPDF(file, (i, total) => {
   if (total > 20 && (i === 1 || i % 10 === 0 || i === total)) setFileReadProgress(`${i} / ${total} 페이지 읽는 중`);
  });
  setFileReadProgress('');
 } else if (ext === 'docx') {
 const arrayBuffer = await file.arrayBuffer();
 const mammoth = await loadMammoth(); // v863
 const result = await mammoth.extractRawText({ arrayBuffer });
 text = result.value;
 } else {
 throw new Error('지원하지 않는 파일 형식입니다. PDF, DOCX, TXT만 지원합니다.');
 }
 // 읽을 수 없는 파일(스캔·이미지 PDF 등) — 추출 텍스트가 사실상 비어있으면 안내
 if (!text || text.trim().length < 20) {
 setError(ext === 'pdf'
 ? '이 PDF에서 텍스트를 읽을 수 없습니다. 스캔본·이미지로 만들어진 PDF일 수 있어요. 텍스트가 포함된 PDF(또는 TXT·DOCX)를 사용해주세요.'
 : '파일에서 텍스트를 읽을 수 없습니다. 내용이 들어있는 파일인지 확인해주세요.');
 setAdaptToolData((prev) => ({ ...prev, fileName: '', sourceText: '' }));
 return;
 }
 setAdaptToolData((prev) => ({ ...prev, fileName: file.name, sourceText: text }));

 // v300+: 큰 원본 파일 안내
 if (typeof console !== 'undefined' && console.log) {
 const sizeMB = (text.length / 1024).toFixed(0);
 const sizeKBytes = (file.size / 1024).toFixed(0);
 console.log(`[파일 업로드] ${file.name}: ${sizeKBytes}KB 원본, 추출 텍스트 ${text.length.toLocaleString()}자`);
 if (text.length > 500000) {
 console.log(` 큰 원본 (${text.length.toLocaleString()}자) — 각색 시 청크 분할 자동 적용 (배치당 50,000자 상한)`);
 }
 if (text.length > 2000000) {
 console.warn(` 매우 큰 원본 (${text.length.toLocaleString()}자) — 처리 시간 길어질 수 있음. 일부 청크가 누락될 수 있으니 화 수를 늘려 청크 분포를 촘촘하게 하세요 (권장: 화 수 ≥ 원본 분량 / 50,000)`);
 }
 }
 } catch (err) {
 setFileReadProgress('');
 setError(`파일 읽기 실패: ${err.message}`);
 }
 };

