 const handleScenarioAnalyzeFileUpload = async (file) => {
 if (!file) return;
 const ext = file.name.toLowerCase().split('.').pop();
 setScenarioAnalyzeData(p => ({ ...p, error: '', marketingResult: null, feedbackResult: null }));

 try {
 let text = '';
 if (ext === 'txt') {
 text = await file.text();
 } else if (ext === 'pdf') {
  // v500: extractTextFromPDF 사용
  text = await extractTextFromPDF(file);
 } else if (ext === 'docx') {
 const arrayBuffer = await file.arrayBuffer();
 const mammoth = await loadMammoth(); // v863
 const result = await mammoth.extractRawText({ arrayBuffer });
 text = result.value;
 } else {
 throw new Error('지원하지 않는 파일 형식입니다. PDF, DOCX, TXT만 지원합니다.');
 }
 // v574: 읽을 수 없는 파일(스캔 PDF 등) 감지 — adapt와 동일 기준
 if (!text || text.trim().length < 20) {
 setScenarioAnalyzeData(p => ({ ...p, fileName: '', sourceText: '', error: '이 PDF에서 텍스트를 읽을 수 없습니다. 스캔 이미지 PDF이거나 보호된 파일일 수 있어요. 텍스트가 포함된 PDF/DOCX/TXT로 다시 시도해주세요.' }));
 return;
 }
 setScenarioAnalyzeData(p => ({ ...p, fileName: file.name, sourceText: text }));
 } catch (err) {
 setScenarioAnalyzeData(p => ({ ...p, error: `파일 읽기 실패: ${err.message}` }));
 }
 };

