 <button onClick={() => updateS({ refSource: 'upload' })} disabled={s.isGenerating} className={(s.refSource || 'upload') === 'upload' ? 'btn btn-primary btn-sm' : 'btn btn-secondary btn-sm'}>업로드</button>
